  def solve(): Unit = {
    val N, M = ni()
    val S = ns(N)
    val tpe = Array.ofDim[Int](N)
    rep(N) { i =>
      tpe(i) = if (S(i) == 'A') 0 else 1
    }

    val From, To = Array.ofDim[Int](2 * M)
    rep(M) { i =>
      val v, u = ni() - 1

      if (tpe(v) == tpe(u)) {
        // 0 -> 1
        From(i * 2) = v
        To(i * 2) = u + N
        From(i * 2 + 1) = u
        To(i * 2 + 1) = v + N
      } else {
        // A0 <-> B0
        From(i * 2) = v + N
        To(i * 2) = u
        From(i * 2 + 1) = u + N
        To(i * 2 + 1) = v
      }
    }
    val g = packDGraph(2 * N, From, To)
    val cycle = findCycle(2 * N, g)
    val ans = if (cycle.isDefined) "Yes" else "No"
    out.println(ans)
  }

  def packDGraph(n: Int, from: Array[Int], to: Array[Int]): Array[Array[Int]] = {
    val t = new Array[Array[Int]](n)
    val p = new Array[Int](n)
    val m = from.length
    rep(m)(i => p(from(i)) += 1)
    rep(n)(i => t(i) = new Array(p(i)))
    rep(m) { i =>
      p(from(i)) -= 1
      t(from(i))(p(from(i))) = to(i)
    }
    t
  }

  def findCycle(n: Int, g: Array[Array[Int]]): Option[Array[Int]] = {
    val flag = Array.ofDim[Int](n)
    val ix = Array.ofDim[Int](n)
    val q = Array.ofDim[Int](n)

    def dfs(i: Int): Option[Array[Int]] = {
      var last = 0
      q(0) = i
      while(last >= 0) {
        val v = q(last)

        flag(v) match {
          case 2 =>
            last -= 1

          case 0 | 1 =>
            flag(v) = 1
            if (g(v).length == ix(v)) {
              last -= 1
              flag(v) = 2
            } else {
              val u = g(v)(ix(v))
              if (flag(u) == 0) {
                last += 1
                q(last) = u
              } else if (flag(u) == 1) {
                val found = q.indexOf(u)
                return Some(java.util.Arrays.copyOfRange(q, found, last + 1))
              }
              ix(v) += 1
            }
        }
      }
      None
    }

    rep(n) { i =>
      if (flag(i) == 0) {
        val res = dfs(i)
        if (res.isDefined) return res
      }
    }

    None
  }

