int solve(int n, vector<string>& s){
    vector<vector<char>> w(n*2, vector<char>(n*2));
    rep(i,n) rep(j,n){
        char ch = s[i][j];
        rep(a,2) rep(b,2) {
            w[i+n*a][j+n*b] = ch;
        }
    }
    int ans = 0;
    rep(of,n) {
        int neq = 0;
        repC2(i,j,n){
            if (w[of+i][j] != w[of+j][i]) ++neq;
        }
        if (neq == 0) ++ans;
    }
    return ans * n;
}

