void solve() {
  int n, m;
  cin >> n >> m;
  string s;
  cin >> s;
  using P = pair<int, int>;
  set<P> se;
  rep(i, m) {
    int u, v;
    cin >> u >> v;
    u--, v--;
    if (u > v) swap(u, v);
    se.emplace(u, v);
  }
  vector<vi32> g(n);
  for (auto p : se) {
    int u, v;
    tie(u, v) = p;
    g[u].emplace_back(v);
    g[v].emplace_back(u);
    // cerr << u << " " << v << endl;
  }
  vi32 abcan(n);
  rep(u, n) {
    int x = 0;
    for (auto v : g[u]) {
      x |= bit32(s[v]=='A');
    }
    abcan[u] = x;
  }
  vi32 seen(n);
  auto dfs = [&](auto dfs, int u) -> bool {
    seen[u] = true;
    int res = 0;
    for (auto v : g[u]) {
      if (abcan[v] != 3) continue;
      if (seen[v]) {
        res |= bit32(s[v]=='A');
      } else if (dfs(dfs, v)) {
        res |= bit32(s[v]=='A');
      }
    }
    seen[u] = false;
    return res == 3;
  };
  rep(u, n) if (!seen[u] && abcan[u] == 3) {
    bool res = dfs(dfs, u);
    if (res) {
      yes();
    }
  }
  no();
}

