void adde(int x,int y)
{
    if (!st[x])
    {
        e[top].y=y;
        e[top].next=0;
        st[x]=top++;
    } else
    {
        e[top].y=y;
        e[top].next=st[x];
        st[x]=top++;
    }
}
void printe()
{
