bool checkig(int i)
{
    if (ig[i]==1) return 0;
    bool A=0,B=0;
    for (int j=st[i];j;j=e[j].next)
    {
        int y=e[j].y;
        if (ig[y]) continue;
        if (label[y]==0) A=1;
        if (label[y]==1) B=1;
    }
    if (A==0 || B==0)
        ig[i]=1;
    return ig[i];
}

