        int now=q[l];
        l--;
        if (checkig(now))
        {
            for (int j=st[now]; j; j=e[j].next)
            {
                int y=e[j].y;
                if (ig[y]) continue;
                l++;
                q[l]=y;
            }
        }
    }
}

