    g[b].push_back(a);
  }
  VI ac(n), bc(n); // count of adjacent vertices
  REP(i, 0, n) {
    for (int w: g[i]) {
      if (s[w] == 'A') ac[i]++;
      else bc[i]++;
    }
  }
  queue<int> que;
  vector<bool> alive(n, true);
  REP(i, 0, n) {
    if (ac[i] == 0 || bc[i] == 0) que.push(i);
