  V[v] |= (1<<t);
  visited[v] = true;
  t = (t+1)%4;
  for(size_t i = 0; i < G[v].size(); ++i){
    int v_ = G[v][i];
    if(S[v_] != s[t]) continue;
    if(v_ == u and not t) return true;
