		--a[i]; --b[i];
		g[a[i]].emplace_back(b[i]);
		g[b[i]].emplace_back(a[i]);
	}

	auto check = [&](int c) {
		std::deque<int> que;
		REP(i, n) {
			if (d[i] == !!(c & 1)) dp[i] = true, que.push_back(i);
		}
		for (auto& x : que) dp[x] = false;

