					if (d[x] == !!(c >> k & 1)) {
						if (!dp[x]) {
							dp[x] = true;
							if (k == D - 1) return true;
							que.push_back(x);
						}
					}
				}
			}
			if (que.empty()) break;
			for (auto& x : que) dp[x] = false;
