#define MX 400005

using namespace std;

int fst[MX], nxt[MX], u[MX], v[MX], lnum;
int id[MX], con[MX][2];
int n, m;

void addeg(int nu, int nv)
{
	nxt[++lnum] = fst[nu];
	fst[nu] = lnum;
	v[lnum] = nv;
	u[lnum] = nu;
}

void input()
{
	scanf("%d%d", &n, &m);
	for(int i=1; i<=n; i++)
	{
		char ch = getchar();
		while(ch != 'A' && ch != 'B') ch = getchar();
		if(ch == 'A') id[i] = 1;
		else id[i] = 0;
	}
	for(int i=1; i<=m; i++)
	{
		int a, b;
		scanf("%d%d", &a, &b);
		addeg(a, b);
		addeg(b ,a);
		con[a][id[b]] ++;
		con[b][id[a]] ++;
	}
}

void work()
{
	static int stk[MX], vis[MX];
	int top = 0, cnt = 0;
	for(int i=1; i<=n; i++)
		if(!con[i][0] || !con[i][1])
			stk[++top] = i, vis[i] = 1;
	while(top)
	{
		int x = stk[top--];
		cnt ++;
		for(int i=fst[x]; i; i=nxt[i])
		{
			con[v[i]][id[x]]--;
			if(!con[v[i]][id[x]] && !vis[v[i]]) stk[++top] = v[i], vis[v[i]] = 1;
		}
	}
	if(cnt == n) printf("No\n");
	else printf("Yes\n");
}

