bool solve(int N, int M, string& s, vi& a, vi& b) {
    vi loop_a, loop_b;
    set<int> s_loop_a, s_loop_b;
    vector<ii> pair_a, pair_b;
    vector<set<int>> paired(N), oppc(N);
    rep(i,M){
        int ca = s[a[i]], cb = s[b[i]];
        // fprintf(stderr, "%d) %d=%c %d=%c\n", i, a[i],ca, b[i],cb);
        if (a[i] == b[i]) {
            if (ca == 'A') {
                loop_a.pb(a[i]);
                s_loop_a.insert(a[i]);
            } else {
                loop_b.pb(a[i]);
                s_loop_b.insert(a[i]);
            }
        } else if (ca == cb) {
            if (ca == 'A') {
                pair_a.pb(ii(a[i], b[i]));
            } else {
                pair_b.pb(ii(a[i], b[i]));
            }
            paired[a[i]].insert(b[i]);
            paired[b[i]].insert(a[i]);
        } else {
            // opposite color
            oppc[a[i]].insert(b[i]);
            oppc[b[i]].insert(a[i]);
        }
    }

    for (int a: loop_a) {
#ifdef DEBUG
        fprintf(stderr, "loop_a %d\n", a);
#endif
        // set<int> bv;
        for (int b: oppc[a]) {
#ifdef DEBUG
            fprintf(stderr, " a%d - b%d\n", a, b);
#endif
            if (found(s_loop_b, b)) {
#ifdef DEBUG
                fprintf(stderr, "! b %d is loop\n", b);
#endif
                return true;
            }
            for (int b2: paired[b]) {
#ifdef DEBUG
                fprintf(stderr, " a%d - b%d - b'%d\n", a, b, b2);
#endif
                if (found(oppc[b2], a)) {
#ifdef DEBUG
                    fprintf(stderr, "! a%d - b%d - b'%d - a%d\n", a, b, b2, a);
#endif
                    return true;
                } else {
                    for (int a2: oppc[b2]) {
                        if (found(s_loop_a, a2)) {
#ifdef DEBUG
                            fprintf(stderr, "! a%d - b%d - b'%d - a'%d\n", a, b, b2, a2);
#endif
                            return true;
                        }
                    }
                }
            }
            // bv.insert(b);
        }
    }
    for (ii p: pair_a) {
        int a1=p.first, a2=p.second;
#ifdef DEBUG
        fprintf(stderr, "pair_a %d %d\n", a1,a2);
#endif
        for (int b: oppc[a1]) {
            if (found(s_loop_b, b)) {
                if (found(oppc[b], a2)) {
#ifdef DEBUG
                    fprintf(stderr, "! a%d - b%d - a'%d\n", a1, b, a2);
#endif
                    return true;
                }
                else {
                    for (int b2: oppc[a2]) {
                        if (found(s_loop_b, b2)) {
#ifdef DEBUG
                            fprintf(stderr, "!! a%d - b%d, a'%d - b'%d\n", a1, b, a2, b2);
#endif
                            return true;
                        }

                    }
                }
            }
            for (int b2: paired[b]) {
                if (found(oppc[b2], a2)) {
#ifdef DEBUG
                    fprintf(stderr, "! a%d - b%d - b'%d - a'%d\n", a1, b, b2, a2);
#endif
                    return true;
                }
            }
        }

    }

    return false;
}

int main() {
    int N, M; cin >> N >> M; // scanf("%d %d", &N, &M);
    // if (fgets(s, N+3, stdin)==NULL) return 0;
    string s; cin >> s;
    vi a(M), b(M);
    rep(i,M) { scanf("%d %d", &a[i], &b[i]); --a[i]; --b[i]; }
    // cerr << a << b << endl;
    cout << (solve(N,M,s,a,b) ? "Yes":"No") << endl;
    return 0;
}

