typedef long long LL; using namespace std;

string S;
int N, M;

const int MAXN = 300000;

vector<int> G[MAXN];

queue<int> myremove;
int degA[MAXN], degB[MAXN];
bool added[MAXN];

int main() {
	ios_base::sync_with_stdio(false);
	cin >> N >> M;
	cin >> S;

	FOR (i, MAXN)
		G[i].clear();
	SET(degA, 0);
	SET(degB, 0);

	int a, b;
	FOR (i, M) {
		cin >> a >> b;
		a--;
		b--;
		G[a].pb(b);
		if (S[b] == 'A')
			degA[a]++;
		else
			degB[a]++;


		G[b].pb(a);
		if (S[a] == 'A')
			degA[b]++;
		else
			degB[b]++;
	}

	SET(added, 0);
	while (!myremove.empty())
		myremove.pop();

	FOR (i, N)
		if (degA[i] == 0 || degB[i] == 0) {
			added[i] = true;
			myremove.push(i);
		}

	int removed = 0;
	while (!myremove.empty()) {
		removed++;
		int v = myremove.front();
		myremove.pop();
		FOR (i, G[v].sz) {
			int w = G[v][i];
			if (added[w])
				continue;
			if (S[v] == 'A')
				degA[w]--;
			else
				degB[w]--;
			if (degA[w] == 0 || degB[w] == 0) {
				myremove.push(w);
				added[w] = true;
			}
		}
	}
	if (removed == N)
		cout << "No" << endl;
	else
		cout << "Yes" << endl;
	return 0;
}

