const int limit = 400010;
int n,m;
vector<int> graph[limit];
int ea[limit],eb[limit];
string s;

bool dupl[limit];
int st[limit];

vector<int> alt_graph[limit];
int visited[limit][2];

bool ok = false;

void dfs(int v,int d,int state){
	visited[v][state % 2] = d;
	for(auto &v2:alt_graph[v]){
		if((state % 2 == 0) == (s[v] == s[v2])){
			if(visited[v2][(state + 1) % 2] != -1){
				const int len = d + 1 - visited[v2][(state + 1) % 2];
				if(len > 0 and len % 4 == 0) ok = true;
				return;
			} else {
				dfs(v2,d+1,(state + 1) % 4);
			}
		}
	}

	return;
}

int main(void){
	cin >> n >> m;
	cin >> s;

	s += s;

	rep(i,m){
		cin >> ea[i] >> eb[i];
		ea[i]--,eb[i]--;
		if(ea[i] == eb[i]){
			dupl[ea[i]] = true;
			graph[ea[i]].push_back(ea[i] + n);
			graph[ea[i] + n].push_back(ea[i]);
		}
	}

	rep(i,m){
		if(ea[i] == eb[i]) continue;
		graph[ea[i]].push_back(eb[i]);
		graph[eb[i]].push_back(ea[i]);
		if(dupl[ea[i]]){
			graph[ea[i] + n].push_back(eb[i]);
			graph[eb[i]].push_back(ea[i] + n);
		} 
		if(dupl[eb[i]]){
			graph[eb[i] + n].push_back(ea[i]);
			graph[ea[i]].push_back(eb[i] + n);
		}
	}

	rep(a,2 * n) for(auto &b:graph[a]){
		st[b] |= (1 << (s[a] - 'A'));
	}

	rep(a,2 * n) for(auto &b:graph[a]){
		if(st[a] != 3 or st[b] != 3) continue;
		alt_graph[a].push_back(b);
	}

	rep(a,2*n)rep(b,2) visited[a][b] = -1;

	rep(a, 2 * n){
		if(st[a] != 3) continue;
		if(s[a] == 'B') continue;

		if(visited[a][0] == -1){
			dfs(a,0,0);
		} 

		if(visited[a][1] == -1){
			dfs(a,0,1);
		}
	}

	cout << (ok?"Yes":"No") << endl;

	return 0;
}

