	used[v] = 1;
	ll A = 0, B = 0;
	REP(i, graph[v].size()) {
		if (graph[v][i].cap == 0&&rest[graph[v][i].to]==0)A = 1;
		if (graph[v][i].cap == 1&&rest[graph[v][i].to]==0)B = 1;
	}
