		REP(i, graph[v].size()) {
			if (used[graph[v][i].to] == 0) {
				dfs(graph, graph[v][i].to);
			}

		}
	}
	else {
		rest[v] = 1;
		REP(i, graph[v].size()) {
			if (rest[graph[v][i].to] == 0) {
				dfs(graph, graph[v][i].to);
			}
		}
	}


}

