const int N = 2e5 + 7;

int n;
vector<int> a;

int pt[N];

int fnd = 0;
int used[N];
int hv[N][2];
vector<pair<int, int>> ng[N];

void dfs(int cur, int pr, int ln) {
    used[cur] = 1;
    for (auto lol : ng[cur]) {
        int t, clr;
        tie(t, clr) = lol;
        if (used[t]) {
            if (ln % 2 == 1 && clr == pr) fnd = 1;
            if (pt[cur] && pr == 0 && (ln % 2) == 0) fnd = 1;
            continue;
        }
        if (pt[cur]) {
            if (pr == 1) continue;
            int add = 1;
            if (clr != pr) add++;
            dfs(t, clr ^ 1, ln + add);
        } else {
            if (clr == pr) dfs(t, clr ^ 1, ln + 1);
        }
    }
}

bool solve() {
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            // cerr << "dfs " << i << endl;
            dfs(i, 0, 0);
        }
    }
    return fnd;
}

