using namespace std;

int search(const vector<vector<int>>& g, const string& s, const char c, vector<int>& mem, int pos){
    if(mem[pos] == -2) return mem[pos] = 1;
    if(mem[pos] != -1) mem[pos];
    mem[pos] = -2;
    for(const auto& next : g[pos]){
        if(s[next] != c) continue;
        if(search(g, s, c, mem, next)) return mem[pos] = 1;
    }
    return mem[pos] = 0;
}

int search2(const vector<vector<int>>& g, const string& s, const char c, const vector<int>& valid, vector<int>& mem, int pos){
    if(!valid[pos]) return mem[pos] = 0;
    if(mem[pos] == -2) return mem[pos] = 1;
    if(mem[pos] != -1) mem[pos];
    mem[pos] = -2;
    for(const auto& next : g[pos]){
        if(s[next] != c) continue;
        if(search2(g, s, c, valid, mem, next)) return mem[pos] = 1;
    }
    return mem[pos] = 0;
}

bool search3(const vector<vector<int>>& g, const vector<int>& valid, vector<int>& visit, vector<int>& mem, int pos){
    if(mem[pos] != -1) return (mem[pos] == 1 ? true : false);
    if(!valid[pos]) return false;
    if(visit[pos]) return true;
    visit[pos] = true;
    for(int next : g[pos]){
        if(search3(g, valid, visit, mem, next)){
            mem[pos] = 1;
            return true;
        }
    }
    mem[pos] = 0;
    return false;
}

int main(){
    int N, M;
    while(cin >> N >> M){
        string s; cin >> s;
        vector<vector<int>> g(N);
        for(int i=0;i<M;i++){
            int a, b; cin >> a >> b;
            --a; --b;
            g[a].push_back(b);
            g[b].push_back(a);
        }
        vector<int> validA(N, -1);
        vector<int> validB(N, -1);
        for(int i=0;i<N;i++){
            search(g, s, 'A', validA, i);
            search(g, s, 'B', validB, i);
        }
        vector<int> valid(N, 0);
        for(int i=0;i<N;i++) valid[i] = (validA[i] && validB[i]);
        fill(validA.begin(), validA.end(), -1);
        fill(validB.begin(), validB.end(), -1);
        for(int i=0;i<N;i++){
            search2(g, s, 'A', valid, validA, i);
            search2(g, s, 'B', valid, validB, i);
        }
        for(int i=0;i<N;i++) valid[i] = (validA[i] && validB[i]);
        bool ok = false;
        vector<int> visit(N, 0);
        vector<int> mem(N, -1);
        for(int i=0;i<N;i++){
            if(visit[i]) continue;
            if(search3(g, valid, visit, mem, i)) ok = true;
        }
        cout << (ok ? "Yes" : "No") << endl;
    }
}

