bool is_loop(ll now, vector<vector<ll>>& graph, vector<ll>& state) {
    state[now] = 1;
    for (ll to : graph[now]) {
        if (state[to] == 1) {
            return true;
        }
        if (state[to] == 2) {
            continue;
        }
        if (is_loop(to, graph, state)) {
            return true;
        }
    }
    state[now] = 2;
    return false;
}

int main() {
    ll N, M;
    cin >> N >> M;
    string s;
    cin >> s;
    vector<vector<ll>> graph(2 * N);
    rep(i,0,M) {
        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        if (s[a] == s[b]) {
            graph[2*a+0].push_back(2*b+1);
            graph[2*b+0].push_back(2*a+1);
        } else {
            graph[2*a+1].push_back(2*b+0);
            graph[2*b+1].push_back(2*a+0);
        }
    }
    vector<ll> state(2 * N);
    rep(i,0,2*N) {
        if (state[i] == 2) {
            continue;
        }
        if (is_loop(i, graph, state)) {
            cout << "Yes" << endl;
            return 0;
        }
    }
    cout << "No" << endl;
}

