unordered_map<int,bool> edges[100000];

void del_edge(int now) {
	int ab_bits = 0;
	for(pair<int,bool> p : edges[now]) {
		int next = p.first;
		if(s.at(next)=='A') ab_bits |= 0b01;
		if(s.at(next)=='B') ab_bits |= 0b10;
	}
	if(ab_bits!=0b11) {
		queue<int> q;
		for(pair<int,bool> p : edges[now]) {
			int next = p.first;
			q.push(next);
			edges[next].erase(now);
		}
		edges[now].clear();
		while(!q.empty()) {
			int next = q.front(); q.pop();
			del_edge(next);
		}
	}
}

int main() {
	cin >> n >> m >> s;
	for(int i = 0; i < m; i++) {
		int a,b;
		cin >> a >> b;
		a--;
		b--;
		edges[a][b] = true;
		edges[b][a] = true;
	}

	//
	for(int i = 0; i < n; i++) {
		del_edge(i);
	}

	//
	for(int i = 0; i < n; i++) {
		if(!edges[i].empty()) {
			cout << "Yes" << endl;
			return 0;
		}
	}

	cout << "No" << endl;

	return 0;
}

