int TopologicalSort(){
	vector<int>in;
	N *= 2;
	in.resize(N);
	for(int i = 0;i < N;i++)fore(x, E[i])in[x]++;

	stack<int>st;
	for (int i = 0; i < N; i++)if (!in[i])st.push(i);
	vector<int>li;
	while (st.size()) {
		int v = st.top();
		st.pop();
		li.pb(v);
		fore(x, E[v]) {
			in[x]--;
			if (!in[x])st.push(x);
		}
	}
	return li.size() != N;
}

