void solve() {
  int n, m; cin >> n >> m;
  string s; cin >> s;
  Spacial<edge> g(n, Graph<edge>(2));
  rep(i,m) {
    int a, b; cin >> a >> b; --a, --b;
    g[a][s[a] == s[b]].emplace_back(b, i*2);
    if (a != b) g[b][s[a] == s[b]].emplace_back(a, i*2+1);
  }

  vb seen(m*2, false), finished(m*2, false);

  function<bool(int, int, bool)> dfs = [&](int v, int p, bool same) {
    for (auto &e : g[v][same]) {
      if (finished[e.idx]) continue;
      if (seen[e.idx]) return true;
      seen[e.idx] = true;
      if (dfs(e.to, v, same ^ true)) return true;
      finished[e.idx] = true;
    }
    return false;
  };

  rep(i,n) {
    if (dfs(i, -1, true) || dfs(i, -1, false)) {
      cout << "Yes\n";
      return;
    }
  }
  cout << "No\n";
}


