bool Dfs(const int cur, auto &visited, const auto &adj) {
    visited[cur] = 1;
    for (auto v : adj[cur]) {
        if (visited[v] == 1) return true;
        else if (!visited[v] && Dfs(v, visited, adj)) return true;
    }
    visited[cur] = 2;
    return false;
}

