const int MN = 200010;

class unionfind {
	vector<int> par, rank;

public:
	void init(int n) {
		par.resize(n);
		rank.resize(n);

		for (int i = 0; i < n; i++) {
			par[i] = i;
			rank[i] = 0;
		}
	}

	int find(int x) {
		if (par[x] == x) return x;
		else return par[x] = find(par[x]);
	}

	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return ;

		if (rank[x] < rank[y]) par[x] = y;
		else {
			par[y] = x;
			if (rank[x] == rank[y]) ++rank[x];
		}
	}

	bool same(int x, int y) { return (find(x) == find(y)); }
} uf;

int N, M;
string s;
vi g[MN];

int main() {
	cin >> N >> M >> s;
	uf.init(N);

	rep(i, M) {
		int a, b;
		scanf("%d %d", &a, &b);
		--a; --b;
		g[a].pb(b); g[b].pb(a);
	}

	rep(i, N) {
		int sz = g[i].size();
		if (s[i] == 'A') {
			rep(j, sz - 1) {
				uf.unite(g[i][j], g[i][j+1]);
			}
		}
	}

	bool ok = 0;

	rep(i, N) {
		if (s[i] == 'B') {
			set<int> st[2];
			for (int to : g[i]) {
				int c = (s[to] == 'A');
				int cmp = uf.find(to);
				if (st[c^1].count(cmp)) {
					ok = 1;
				}
				st[c].insert(cmp);
			}
		}
	}

	puts(ok ? "Yes" : "No");

	return 0;
}

