bool solve(int N, int M, string& s, vi& a, vi& b) {
    vvi next(N);
    vi a_side(N,0), b_side(N,0);

    rep(i,M) {
        int u = a[i], v = b[i];
        int cu = (s[u] == 'A'), cv = (s[v] == 'A');

        if (cv) ++a_side[u];
        else    ++b_side[u];
        next[u].pb(v);

        if (u != v) {
            if (cu) ++a_side[v];
            else    ++b_side[v];
            next[v].pb(u);
        }
    }

    queue<int> q;
    vector<bool> visited(N, false);
    int alive = N;

    rep(i,N){
        if (a_side[i]==0 || b_side[i]==0) {
            q.push(i);
        }
    }
    while (!q.empty()){
        int u = q.front(); q.pop();
        int cu = s[u];

        visited[u] = true;
        --alive;

        for (int v: next[u]) {
            if (cu) --a_side[v];
            else    --b_side[v];
            if (!visited[v] && (a_side[v]==0 || b_side[v]==0)) {
                q.push(v);
            }
        }
    }
    // fprintf(stderr, "alive=%d/%d\n", alive, N);
    return alive > 0;
}

