int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  int N, M; std::cin >> N >> M;
  std::string s; std::cin >> s;
  std::vector<std::vector<int>> G(N);
  for(int i = 0; i < M; ++i) {
    int a, b; std::cin >> a >> b; --a; --b;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  for(;;) {
    bool change = false;
    for(int i  = 0; i < G.size(); ++i) if(s[i] != ' ') {
      int ab = 0;
      for(int x: G[i]) {
        if(s[x] == 'A') ab |= 1;
        if(s[x] == 'B') ab |= 2;
        if(ab==3) break;
      }
      if(ab < 3) {
        s[i] = ' ';
        change = true;
        if(--N==0) fin("No");
        int j = i;
        for(;;) {
          int nj = -1;
          for(int x: G[j]) if(s[j] != ' ') {
            for(int x: G[i]) {
              if(s[x] == 'A') ab |= 1;
              if(s[x] == 'B') ab |= 2;
              if(ab==3) break;
            }
            if(ab==3) continue;
            nj = x;
          }
          if(nj < 0) break;
          s[nj] = ' ';
          if(--N==0) fin("No");
          j = nj;
        }
      }
    }
    if(!change) fin("Yes");
  }
  return 0;
}

