const int N = 2e5+10;
int n, m, c[N], good[N], vis[N], path[N], rn[N], bn[N];
vector<int> g[N];

void yes() {
	cout << "Yes" << endl;
	exit(0);
}

void dfs(int s) {
	vis[s] = 1;
	path[s] = 1;
	for(int v : g[s]) {
		if(!good[v]) continue;
		if(path[v]) yes();
		if(!vis[v]) dfs(v);
	}
	path[s] = 0;
}

signed main() {
    ios::sync_with_stdio(false);
    //cout << fixed << setprecision(7);
    memset(vis, 0, sizeof(vis));
    memset(path, 0, sizeof(path));
    cin >> n >> m;
    FOR(i, 1, n) {
    	char ch;
    	cin >> ch;
    	c[i] = (ch == 'B');
    }
    REP(i, m) {
    	int a, b;
    	cin >> a >> b;
    	g[a].push_back(b);
    	g[b].push_back(a);
    }
    FOR(i, 1, n) {
    	for(int v : g[i]) {
    		if(c[v]) ++bn[i];
    		else ++rn[i];
    	}
    	if(rn[i] && bn[i]) good[i] = true;
    	else good[i] = false;
    }
    memset(vis, 0, sizeof(vis));
    queue<int> nxt;
    FOR(i, 1, n) {
    	if(!good[i]) continue;
    	for(int v : g[i]) {
    		if(!good[v]) {
    			if(c[v]) --bn[i];
    			else --rn[i];
    		}
    	}
    	if(!rn[i] || !bn[i]) {
    		if(!vis[i]) {
    			vis[i] = 1;
    			nxt.push(i);
    		}
    	}
    }
    while(!nxt.empty()) {
    	int cur = nxt.front();
    	nxt.pop();
    	good[cur] = 0;
    	for(int v : g[cur]) {
    		if(good[v]) {
    			if(c[cur]) --bn[v];
    			else --rn[v];
    		}
    		if(!vis[v] && (!rn[v] || !bn[v])) {
    			vis[v] = 1;
    			nxt.push(v);
    		}
    	}
    }

    FOR(i, 1, n) {
    	if(good[i] && !vis[i]) dfs(i);
    }
    cout << "No" << endl;

    return 0;
}

