PR getVal(int u,int v)
{
    if(u > v) swap(u, v);
    return MP(u, v);
}

int rec(int p,int root,int ty)
{
    ///cout << p << ' ' << root << ' ' << ty << endl;
    if(ty == 3) return mopa[getVal(p, root)];

    int temp = 0;

    if(ty == 0)
    {
        for(auto x : mat[p])
        if(col[x] == col[root] && !temp) temp = max(temp, rec(x, root, 1));
    }
    else if(ty == 1)
    {
        for(auto x : mat[p])
            if(col[x] != col[root] && !temp) temp = max(temp, rec(x, root, 2));
    }
    else if(ty == 2)
    {
        for(auto x : mat[p])
            if(col[x] != col[root] && !temp) temp = max(temp, rec(x, root, 3));
    }

    return temp;
}

