bool dfs(const vector<vector<int>> &G, const string &S, vector<int> &V, int v, int t){
  bool ret = false;
  V[v] |= (1<<t);
  t = (t+1)%4;
  for(size_t i = 0; i < G[v].size(); ++i){
    int v_ = G[v][i];
    if(S[v_] != s[t]) continue;
    if(not t and V[v_]%2) return true;
    if((V[v_]>>t)&1) continue;
    ret |= dfs(G,S,V,v_,t);
  }
  return ret;
}

