    g[a].push_back(b);
    if (a != b) g[b].push_back(a);
  }
  for (int i = 0; i < n; i++) {
    V<> vis(n, -1);
    if (rec(i, vis, s, g)) return cout << "Yes" << '\n', 0;
  }
  cout << "No" << '\n';
}

