const int maxn = (int)2e5 + 5;

vector <int> a[maxn];
int t[maxn][2];
int fl_yes = 0;
int n, m;
string s;

void dfs(int v, int z) {
    if (fl_yes)
        return;
    if (t[v][z] == -1) {
        fl_yes = 1;
        return;
    }
    if (t[v][z])
        return;
    t[v][z] = -1;
    for (int to: a[v]) {
        if ((z == 0 && s[to] != s[v]) || (z == 1 && s[to] == s[v]))
            continue;
        dfs(to, z ^ 1);
    }
    t[v][z] = 1;
}

void solve(bool __attribute__((unused)) read) {
	cin >> n >> m;
    cin >> s;
    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y; --x; --y;
        a[x].push_back(y);
        a[y].push_back(x);
    }
    memset(t, 0, sizeof t);
    for (int i = 0; i < n; ++i) {
        dfs(i, 0);
        dfs(i, 1);
    }
    if (fl_yes) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }

}

