void add_edge(Graph &G, ll from, ll to, ll cap, bool revFlag, ll revCap) {
    G[from].push_back(Edge(to, cap, (ll)G[to].size()));
    if(revFlag)
        G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1));
}

void solve() {
    ll n, m;
    cin >> n >> m;
    string s;
    cin >> s;
    Graph g(n);
    REP(i, m) {
        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        add_edge(g, a, b, 1, true, 1);
    }

    vvec<bool> used(n, vec<bool>(2, 0));
    vec<bool> dp(n, false);
    auto dfs = [&](auto &&self, int v, int t) -> bool {
        used[v][t] = true;
        for(auto e : g[v]) {
            if(dp[e.to])
                continue;
            if(t) {
                if(s[v] != s[e.to]) {
                    if(used[e.to][!t]) {
                        return true;
                    }
                    if(self(self, e.to, !t))
                        return true;
                }
            } else {
                if(s[v] == s[e.to]) {
                    if(used[e.to][!t]) {
                        return true;
                    }
                    if(self(self, e.to, !t))
                        return true;
                }
            }
        }
        dp[v] = true;
        return false;
    };

    REP(i, n) {
        if(used[i][0])
            continue;
        if(dfs(dfs, i, 0)) {
            cout << "Yes" << en;
            return;
        }
    }
    cout << "No" << en;
}

