vector<int> getPair(int x, vector<pair<int, int> > pair) {
	int min = 0, max = pair.size();
	for (int mid = max >> 1;max - min > 1;mid = min + (max - min >> 1)) {
		if (pair[mid].first < x) min = mid;
		else max = mid;
	}
	vector<int> ret;
	for (;min < pair.size() && pair[min].first <= x;++ min) {
		if (pair[min].first == x) ret.push_back(pair[min].second);
	}
	return ret;
}

bool getPair(int x, vector<int> pair) {
	int min = 0, max = pair.size();
	for (int mid = max >> 1;max - min > 1;mid = min + (max - min >> 1)) {
		if (pair[mid] <= x) min = mid;
		else max = mid;
	}
	return min < pair.size() && pair[min] == x;
}

