void ins(int u, int v) {nxt[++K] = h[u]; h[u] = K; to[K] = v;}

bool dfs(int x)
{
	if(used[x])
	{
		if(ok[x] == -1 || ok[x] == 1) return 1;
		else return 0;
	}
	used[x] = 1;
	bool ok1 = 0, ok2 = 0;
	for(int i = h[x]; i; i = nxt[i])
	{
		if(dfs(to[i]))
		{
			if(c[to[i]] == 'A') ok1 = 1;
			else ok2 = 1;
		}
	}
	if(ok1 && ok2) ok[x] = 1;
	else ok[x] = 0;
	return ok[x];
}

