		cin >> a >> b;
		-- a; -- b;
		if (s[b] == 'A') edge[a].nodeA.push_back(b);
		else  edge[a].nodeB.push_back(b);
		if (s[a] == 'A') edge[b].nodeA.push_back(a);
		else edge[b].nodeB.push_back(a);
		if (s[a] == s[b]) {
			if (s[a] == 'A') {
				Apair.push_back(make_pair(a, b));
				Apair.push_back(make_pair(b, a));
			} else {
				Bpair.push_back(make_pair(a, b));
				Bpair.push_back(make_pair(b, a));
			}
		}
		if (a == b) loop[a] = true;
	}
	for (int i = 0;i < N;++ i) {
		sort(edge[i].nodeA.begin(), edge[i].nodeA.end());
		sort(edge[i].nodeB.begin(), edge[i].nodeB.end());
	}
	sort(Apair.begin(), Apair.end());
	sort(Bpair.begin(), Bpair.end());

/*	for (int i = 0;i < Apair.size();++ i) {
		cerr << "A:" << Apair[i].first << "," << Apair[i].second << endl;
	}
	for (int i = 0;i < Bpair.size();++ i) {
		cerr << "B:" << Bpair[i].first << "," << Bpair[i].second << endl;
	}*/

	for (int i = 0;i < Apair.size();++ i) {
		int a1 = Apair[i].first, a2 = Apair[i].second;
		for (int j = 0;j < edge[a1].nodeB.size();++ j) {
			vector<int> b2 = getPair(edge[a1].nodeB[j], Bpair); // a1と繋がる全てのbにおける、あるb1のペアb2の列挙
			for (int k = 0;k < b2.size();++ k) {
				if (getPair(b2[k], edge[a2].nodeB)) { // a2に繋がるBのうちb2に繋がるものがあるか
//					cerr << a1 << "," << a2 << " - " << edge[a1].nodeB[j] << "," << b2[k] << endl;
					cout << "Yes";
					return 0;
				}
			}
		}
	}

	if (check(Apair, true, edge, loop) || check(Bpair, false, edge, loop)) cout << "Yes";
	else cout << "No";
	return 0;
}
/*
31536000のコメント解説欄
ここテンプレで用意してるから、A問題とかだとこの先空欄の危険あり
また、コンテスト後に https://31536000.hatenablog.com/ で解説していると思うので、良かったら読んでねー

大事なことは、要素が2個しかないということ
つまり、A→Aの閉路、B→Bの閉路、A→B……の閉路の3個が存在してそれが隣接してればおk
これは、次のどれかを内包しているに他ならない
1. [1]=A, [2]=Bとして[1]-[1], [2]-[2], [1]-[2]
2. [1]=A, [2]=A, [3]=Bとして[1]-[2], [1]-[3], [2]-[3], [3]-[3]
3. [1]=A, [2]=B, [3]=Bとして[1]-[2], [1]-[3], [2]-[3], [1]-[1]
4. [1]=A, [2]=A, [3]=B, [4]=Bとして[1]-[2], [2]-[3], [3]-[4], [4]-[1]

まず、A-AとB-Bのペアを作っておく O(N)
そして、1個のAを決め打つ O(N)
この時、A-BとなるBを1個取り出し(O(logN))、そのペアとなるB(O(logN))とペアとなるA(O(log N))が自身のペアと一致するならYes
そうでないならNo
*/

#include <iostream>
#include <vector>
using namespace std;
const string s = "AABB";

bool dfs(const vector<vector<int>> &G, const string &S, vector<int> &V, int v, int t){
  bool ret = false;
  V[v] |= (1<<t);
  t = (t+1)%4;
  for(size_t i = 0; i < G[v].size(); ++i){
    int v_ = G[v][i];
    if(S[v_] != s[t]) continue;
    if(not t and V[v_]%2) return true;
    if((V[v_]>>t)&1) continue;
    ret |= dfs(G,S,V,v_,t);
  }
  return ret;
}

int main(){
  int N, M;
  cin >> N >> M;
  string S;
  cin >> S;
  vector<vector<int>> G(N);
  for(int i = 0; i < M; ++i){
    int a, b;
    cin >> a >> b;
    --a,--b;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  vector<int> V(N,0);
  bool f = false;
  for(int i = 0; i < N; ++i){
    if(S[i] != 'A' or V[i]%2) continue;
    f |= dfs(G,S,V,i,0);
  }
  if(f) cout << "Yes" << endl;
  else cout << "No" << endl;
  return 0;
}

