						}
						else if(dist[v] == 2)
						{
							// cout << "found cycle with parent " << u << " and child " << v << endl;
							cout << "Yes" << endl;
							return 0;
						}
					}
				}
			}
			visited.clear();
		}
	}
	cout << "No" << endl;
	return 0;
}

