const int SIZE = 200000 + 10;
int cnt[SIZE][2];

bool solve() {
  int N, M; cin>>N>>M;
  string s; cin>>s;
  vector<int> mark(N);
  REP(i,N) mark[i] = (s[i] == 'A' ? 0 : 1);
  vector<pint> edge(M);
  REP(i,M) {
    int a, b; cin>>a>>b; a--; b--;
    edge[i].first = a;
    edge[i].second = b;
  }

  vector<bool> ok(N, true);
  int rem=N;
  while(true) {
    int orem = rem;
    REP(i,N) cnt[i][0] = cnt[i][1] = 0;
    REP(i,M) {
      int a = edge[i].first;
      int b = edge[i].second;
      if(ok[a] && ok[b]) {
	cnt[a][mark[b]]++;
	cnt[b][mark[a]]++;
      }
    }
    rem = 0;
    REP(i,N) {
      if(cnt[i][0] > 0 && cnt[i][1] > 0) {
	ok[i] = true; rem ++;
      } else {
	ok[i] = false;
      }
    }
    if(rem >= orem) break;
  }
  return rem > 0;
}

int main() {
  bool ans = solve();
  cout << (ans ? "Yes" : "No") << endl;
