int n, m, ans, tot, h[N], stk[N], val[N], del[N], ts[N][2];

inline void add(int u, int v) {
	e[++tot] = (E){v, h[u]}, h[u] = tot;
	e[++tot] = (E){u, h[v]}, h[v] = tot;
}

template <class T> inline void in(T &x) {
	x = 0; int f = 0; char ch = getchar();
	for (; ch<'0' || ch>'9';) {if (ch=='-') f=-1; ch = getchar();}
	for (; ch>='0' && ch<='9';) x = x*10 + ch-'0', ch = getchar();
	x = f ? -x : x;
}

inline void read() {
	int ls = 0; char ch = getchar();
	for (; ch<'A' || ch>'B';) ch = getchar();
	for (; ch>='A' && ch<='B';) val[++ls] = ch - 'A', ch = getchar();
}

