	int u, v; in(n), in(m), read();
	for (int i = 1; i <= m; ++i) in(u), in(v), add(u, v);
	for (u = 1; u <= n; ++u) {
		for (int i = h[u]; i; i = e[i].nt)
			++ts[u][val[e[i].v]];
	}
	for (;;) {
		int top = 0;
		for (u = 1; u <= n; ++u) {
			if (del[u]) continue;
			if (!ts[u][0] || !ts[u][1]) del[u] = 1, stk[++top] = u;
		}
		for (int j = 1; j <= top; ++j)
				for (int i = h[u = stk[j]]; i; i = e[i].nt) --ts[e[i].v][val[u]];
		if (!top) break;
	}
	for (int i = 1; i <= n; ++i) if (!del[i]) {puts("Yes"); return 0;}
