inline void addEdge (int u, int v) {
    nxt[++cap] = head[u];
    head[u] = cap;
    to[cap] = v;
}

inline void dfs (int x, int stp) {
    if (vis[x] != 0 && vis[x] != sz) return;
    // printf("%d %d %d\n", x, stp, sz);
    vis[x] = sz;
    for (int i = head[x]; i; i = nxt[i]) {
        if (stp == 1) {
            if (s[to[i]] == s[x]) 
                dfs(to[i], stp + 1);
        } else {
            if (s[to[i]] != s[x]) {
                if (vis[to[i]] == sz) {
                    puts("Yes");
                    exit(0);
                }
                dfs(to[i], 1);
            }
        }
    }
    vis[x] = sz - 1;
}

