#endif
                if (found(oppc[b2], a)) {
#ifdef DEBUG
                    fprintf(stderr, "! a%d - b%d - b'%d - a%d\n", a, b, b2, a);
#endif
                    return true;
                }
            }
            // bv.insert(b);
        }
    }
    for (ii p: pair_a) {
        int a1=p.first, a2=p.second;
#ifdef DEBUG
        fprintf(stderr, "pair_a %d %d\n", a1,a2);
#endif
        for (int b: oppc[a1]) {
            if (found(s_loop_b, b)) {
                if (found(oppc[b], a2)) {
#ifdef DEBUG
                    fprintf(stderr, "! a%d - b%d - a'%d\n", a1, b, a2);
#endif
                    return true;
                }
                else {
                    for (int b2: oppc[a2]) {
                        if (found(s_loop_b, b2)) {
#ifdef DEBUG
                            fprintf(stderr, "!! a%d - b%d, a'%d - b'%d\n", a1, b, a2, b2);b2, a2);
