bool vis[N];

void bfs() {
	queue<int> Q;
	for (int i = 0; i < n; i++) {
		if (cnt[i][0] == 0 || cnt[i][1] == 0) {
			Q.push(i); // invalid nodes
			vis[i] = 1;
		}
	}
	while (!Q.empty()) {
		int cur = Q.front(); // this node will be removed
		Q.pop();
//		for (int i  = 0; i < adj[cur].size(); i++) {
//			int to = adj[cur][i];
//		}
		for (auto to : adj[cur]) {
			if (vis[to])
				continue;
			int curColor = s[cur] - 'A';
			cnt[to][curColor]--;
			if (cnt[to][0] == 0 || cnt[to][1] == 0) {
				Q.push(to);
				vis[to] = 1;
			}
		}
	}
}

