		f--, t--;
		adj[f].push_back(t);
		adj[t].push_back(f);
		cnt[f][s[t] - 'A']++;
		cnt[t][s[f] - 'A']++;
	}
	bfs();
	for (int i = 0; i < n; i++) {
		if (!vis[i]) {
			puts("Yes");
			return 0;
