vector<int> cntA, cntB;

vector<bool> bfs(vector<bool> &vec, int i) {
	vector<bool> isDelete = vec;

	queue<int> que;
	que.emplace(i);

	isDelete[i] = true;
	while (!que.empty()) {
		int now = que.front(); que.pop();

		for (auto next : g[now]) {
			if (isDelete[next]) {
				continue;
			}

			(s[now] == 'A' ? cntA[next] : cntB[next])--;
			if (cntA[next] == 0 || cntB[next] == 0) {
				isDelete[next] = true;
				que.emplace(next);
			}
		}
	}

	return isDelete;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> n >> m >> s;

	g.resize(n, vector<int>(n));
	cntA.resize(n);
	cntB.resize(n);

	for (int i = 0; i < m; i++) {
		int a, b;
		cin >> a >> b;
		a--; b--;

		g[a].emplace_back(b);
		g[b].emplace_back(a);

		(s[b] == 'A' ? cntA[a] : cntB[a])++;
		(s[a] == 'A' ? cntA[b] : cntB[b])++;
	}

	vector<bool> isDelete(n);
	for (int i = 0; i < n; i++) {
		if (cntA[i] == 0 || cntB[i] == 0) {
			isDelete = bfs(isDelete, i);
		}
	}

	for (auto b : isDelete) {
		if (!b) {
			cout << "Yes" << endl;
			return 0;
		}
	}

	cout << "No" << endl;
	return 0;
}

