		adj[u].push_back(v);
		adj[v].push_back(u);
	}
	queue<int> q;
	for (int i = 1; i <= n; i++) {
		if (canRemove(i)) {
			q.push(i);
			removed[i] = 1;
		}
	}
	while (!q.empty()) {
		int u = q.front();
