int main(){
	string S; 
	cin >> N >> M >> S; 
	set<pair<int, int>> T;
	for(int i = 0; i < M; i++){
		int a, b; cin >> a >> b; 
		a--; b--; 
		if(a > b) swap(a, b); 
		T.insert(make_pair(a, b)); 
	}
	int In[800010] = {};
	for(auto it = T.begin(); it != T.end(); it++){
		int a = (*it).first; int b = (*it).second; 
		if(S[a] == 'A' && S[b] == 'A'){
			E[4*a+3].push_back(4*b); In[4*b] ++; 
			if(a!= b) {
				E[4*b+3].push_back(4*a); In[4*a] ++; 
			}
		}
		if(S[a] == 'A' && S[b] == 'B'){
			E[4*a].push_back(4*b+1); In[4*b+1] ++; 
			E[4*b+2].push_back(4*a+3); In[4*a+3] ++; 
		}
		if(S[a] == 'B' && S[b] == 'A'){
			E[4*a+2].push_back(4*b+3); In[4*b+3] ++; 
			E[4*b].push_back(4*a+1); In[4*a+1] ++; 
		}
		if(S[a] == 'B' && S[b] == 'B'){
			E[4*a+1].push_back(4*b+2); In[4*b+2] ++; 
			if(a != b){
				E[4*b+1].push_back(4*a+2); In[4*a+2] ++; 
			}
		}
	}
	stack<int> st;
	for(int i = 0; i < N*4; i++){
		if(!In[i]) st.push(i); 
	}
	vector<int> Top = {}; //トポロジカルソート後
	while(st.size()){
		int i = st.top(); st.pop(); 
		Top.push_back(i); 
		for(int j = 0; j < E[i].size(); j++){
			In[E[i].at(j)] --; 
			if(!In[E[i].at(j)]) st.push(E[i].at(j)); 
		}
	}
	cout << ((Top.size() == N*4) ? "No" : "Yes") << endl;
}

