	edge(int v = 0,int next = 0) : v(v), next(next) {}
} e[maxn * 2];
int hd[maxn] , ek = 1;
inline void adde(int u,int v){
	e[ek] = edge(v,hd[u]);
	hd[u] = ek++;
}
bool vis[maxn];
bool dfs(int len,char pas,int u){
//	if(pas != 'A' && pas != 'B') {
//	}
	for(int i = hd[u];i;i = e[i].next){
		int v = e[i].v;
