struct Graph
{
    Graph(const std::size_t v) : V{v}, edge(v), rev_edge(v) {}
    void addEdge(const std::size_t from, const std::size_t to) { edge[from].insert(to), rev_edge[to].insert(from); }
    const std::size_t V;
    std::vector<std::set<std::size_t>> edge, rev_edge;
};

int main()
{
    int N, M;
    std::cin >> N >> M;
    std::string s;
    std::cin >> s;
    Graph g(N);
    for (int i = 0; i < M; i++) {
        int u, v;
        std::cin >> u >> v, u--, v--;
        g.addEdge(u, v), g.addEdge(v, u);
    }
    std::set<int> cand;
    for (int i = 0; i < N; i++) { cand.insert(i); }
    std::vector<int> a(N, 0), b(N, 0);
    for (int i = 0; i < N; i++) {
        std::set<int> A, B;
        for (const int to : g.edge[i]) {
            if (s[to] == 'A') {
                A.insert(to);
            } else {
                B.insert(to);
            }
        }
        a[i] = A.size(), b[i] = B.size();
    }
    while (true) {
        std::vector<int> er;
        for (const int i : cand) {
            if (a[i] == 0 or b[i] == 0) {
                er.push_back(i);
                for (const int to : g.edge[i]) {
                    if (to == i) { continue; }
                    (s[i] == 'A' ? a[to] : b[to])--;
                }
            }
        }
        if (er.empty()) { break; }
        for (const int e : er) { cand.erase(e); }
    }
    std::cout << (cand.empty() ? "No" : "Yes") << std::endl;
    return 0;
}

