bool OK(int nod){
	return nrB[nod] && nrR[nod];
}

void update(int nod, char c){
	if (c == 'A') nrR[nod]--;
	else nrB[nod]--;
}

int Q[Nmax], lg = 0, cnt = 0;
void elim(){
	cnt = n;
	for (int i=1;i<=n;i++){
		if (!OK(i)){
			cnt--;
			uz[i] = 1;
			Q[++lg] = i;
		}
	}
	while (lg && cnt){
		int crt = Q[lg--];
		for (auto it : v[crt]){
			if (uz[it]) continue;

			update(it, s[crt-1]);
			if (!OK(it)){
				Q[++lg] = it;
				uz[it] = 1;
				cnt--;
			}
		}
	}

	cout << (cnt ? "Yes\n" : "No\n");
}


