#include <bits/stdc++.h>
const int maxn = int(2e5) + 7;
int n, m, flag[maxn][2], type[maxn];
bool vis[maxn];
char str[maxn];
std::vector<int> edge[maxn];
void addedge(int u, int v) {
	edge[u].push_back(v);
	flag[u][type[v]]++;
}
std::queue<int> que;
int main() {
	scanf("%d%d %s", &n, &m, str + 1);
	for (int i = 1; i <= n; i++) type[i] = str[i] - 'A';
	for (int i = 1, u, v; i <= m; i++) {
		scanf("%d%d", &u, &v);
		addedge(u, v);
		addedge(v, u);
	}
	int cnt = n;
	for (int i = 1; i <= n; i++) if (flag[i][0] == 0 || flag[i][1] == 0) vis[i] = true, que.push(i);
	while (!que.empty()) {
		assert(que.size() < maxn);
		cnt--;
		int u = que.front();
		que.pop();
		for (int v : edge[u]) {
			if (vis[v]) continue;
			if (--flag[v][type[u]] == 0) que.push(v), vis[v] = true;
		}
	}
	printf("%s\n", cnt ? "Yes" : "No");
	return 0;
}

