	for (int i = 0; i < g[a].size(); i++) {
		--dega[g[a][i]];
		--sz[g[a][i]];
		if (sz[g[a][i]] == degb[g[a][i]])
			vecb.push_back(g[a][i]);
	}
}

void delb(int a) {
	if (st.find(a) != st.end())
		return ;
	st.insert(a);
	for (int i = 0; i < g[a].size(); i++) {
		--degb[g[a][i]];
		--sz[g[a][i]];
		if (sz[g[a][i]] == dega[g[a][i]])
