multimap<int, int> aa, ab, ba, bb;

bool dfs(int x, int be,int t) {
	if (t == 0) {
		auto p = aa.equal_range(x);
		for (auto i = p.first; i != p.second; ++i) {
			return dfs(i->second, be, 1);
		}
	}
	else if (t == 1) {
		auto p = ab.equal_range(x);
		for (auto i = p.first; i != p.second; ++i) {
			return dfs(i->second, be, 2);
		}
	}
	else if (t == 2) {
		auto p = bb.equal_range(x);
		for (auto i = p.first; i != p.second; ++i) {
			return dfs(i->second, be, 3);
		}
	}
	else if (t == 3) {
		auto p = ba.equal_range(x);
		for (auto i = p.first; i != p.second; ++i) {
			return dfs(i->second, be, 4);
		}
	}
	else if (t == 4) {
		if (x == be)return true; else return dfs(x, be, 0);
	}
}
