  VV deg(n, V(2));

  rep(u, n) for (auto v : G[u]) {
    int k = s[v] - 'A';
    ++deg[u][k];
  }

  int rmv = 0;
  queue<int> que;
  rep(i, n) if (deg[i][0] == 0 || deg[i][1] == 0) que.push(i);

  while (!que.empty()) {
    int u = que.front(); que.pop();
    int k = s[u] - 'A';
    ++rmv;
    for (auto v : G[u]) {
      --deg[v][k];
      if (deg[v][k] == 0) que.push(v);
    }
  }

  if (rmv < n) cout << "Yes" << "\n";
  else cout << "No" << "\n";
  return 0;
}

