int search(const vector<vector<int>>& g, const string& s, const char c, vector<int>& mem, int pos){
    if(mem[pos] == -2) return mem[pos] = 1;
    if(mem[pos] != -1) return mem[pos];
    mem[pos] = -2;
    for(const auto& next : g[pos]){
        if(s[next] != c) continue;
        if(search(g, s, c, mem, next)) return mem[pos] = 1;
    }
    return mem[pos] = 0;
}

int search2(const vector<vector<int>>& g, const string& s, const char c, const vector<int>& valid, vector<int>& mem, int pos){
    if(!valid[pos]) return mem[pos] = 0;
    if(mem[pos] == -2) return mem[pos] = 1;
    if(mem[pos] != -1) return mem[pos];
    mem[pos] = -2;
    for(const auto& next : g[pos]){
        if(s[next] != c) continue;
        if(search2(g, s, c, valid, mem, next)) return mem[pos] = 1;
    }
    return mem[pos] = 0;
}

bool search3(const vector<vector<int>>& g, const vector<int>& valid, vector<int>& visit, vector<int>& mem, int pos){
    if(mem[pos] != -1) return (mem[pos] == 1 ? true : false);
    if(!valid[pos]) return false;
    if(visit[pos]) return true;
    visit[pos] = true;
    for(int next : g[pos]){
        if(search3(g, valid, visit, mem, next)){
            mem[pos] = 1;
            return true;
        }
    }
    mem[pos] = 0;
    return false;
}

