    memset(path, 0, sizeof(path));
    memset(rn, 0, sizeof(rn));
    memset(bn, 0, sizeof(bn));
    cin >> n >> m;
    FOR(i, 1, n) {
    	char ch;
    	cin >> ch;
    	c[i] = (ch == 'B');
    }
    REP(i, m) {
    	int a, b;
    	cin >> a >> b;
    	g[a].push_back(b);
    	g[b].push_back(a);
    }
    FOR(i, 1, n) {
    	for(int v : g[i]) {
    		if(c[v]) ++bn[i];
    		else ++rn[i];
    	}
    	if(rn[i] && bn[i]) good[i] = true;
    	else good[i] = false;
    }
    queue<int> nxt;
    FOR(i, 1, n) {
    	if(!good[i]) continue;
    	for(int v : g[i]) {
    		if(!good[v]) {
    			if(c[v]) --bn[i];
    			else --rn[i];
    		}
    	}
    	if(!rn[i] || !bn[i]) {
			vis[i] = 1;
			nxt.push(i);
    	}
    }
    while(!nxt.empty()) {
    	int cur = nxt.front();
    	nxt.pop();
    	good[cur] = 0;
    	for(int v : g[cur]) {
    		if(good[v]) {
    			if(c[cur]) --bn[v];
    			else --rn[v];
	    		if(!vis[v] && (!rn[v] || !bn[v])) {
	    			vis[v] = 1;
	    			nxt.push(v);
	    		}
    		}
    	}
    }
    memset(vis, 0, sizeof(vis));
    FOR(i, 1, n) {
    	if(good[i] && !vis[i]) dfs(i);
    }
    cout << "No" << endl;

    return 0;
}

