        {
            G[a][1].push_back({b, 0});
            G[b][1].push_back({a, 0});
            deg[b][0]++;
            deg[a][0]++;
        }
        else
        {
            G[a][0].push_back({b, 1});
            G[b][0].push_back({a, 1});
            deg[b][1]++;
            deg[a][1]++;
        }
