int head[maxn], to[maxn << 1], nxt[maxn << 1], tot;
char s[maxn];
bool vis[maxn];
queue<int> q;

void add(int u, int v) {
	to[++tot] = v, nxt[tot] = head[u], head[u] = tot;
	to[++tot] = u, nxt[tot] = head[v], head[v] = tot;
}

int main() {
	memset(head, -1, sizeof head);

	scanf("%d%d%s", &n, &m, s + 1);
	for(int i = 1; i <= m; i++) {
		int u, v;
		scanf("%d%d", &u, &v);
		add(u, v);
		num[u][s[v] == 'B']++;
		num[v][s[u] == 'B']++;
	}
	for(int i = 1; i <= n; i++) if(!num[i][0] || !num[i][1]) q.push(i), vis[i] = true;
	while(!q.empty()) {
		int u = q.front(); q.pop();
		for(int i = head[u]; i != -1; i = nxt[i]) {
			int v = to[i];
			num[v][s[u] == 'B']--;
			if((!num[v][0] || !num[v][1]) && !vis[v]) q.push(v), vis[v] = true;
		}
	}
	for(int i = 1; i <= n; i++) {
		if(!vis[i]) {
			puts("Yes");
			return 0;
		}
	}
	puts("No");
	return 0;
}

