const Int M = 200011;
Int used[M][2],ans = 0;
void dfs(Int pos, Int cnt, Int num,char target){
  ans |= (cnt == 0 && used[pos][cnt] == num);
  if(used[pos][cnt] != 0) return;
  if(ans) return;

  used[pos][cnt]  = num;
  for(Int to:G[pos]){
    if(cnt == 0 && A[to] != A[pos]) continue;
    if(cnt == 1 && A[to] == A[pos]) continue;
    dfs(to, cnt ^ 1, num, target);
  }
  used[pos][cnt] = -1;
}

