const int SIZE = 200000	+ 10;
int cnt[SIZE][2];

bool solve() {
  int N, M; cin>>N>>M;
  string s; cin>>s;
  vector<int> mark(N);
  deque<int> q;
  REP(i,N) {
    mark[i] = (s[i] == 'A' ? 0 : 1);
    q.push_back(i);
  }
  vector<vector<int> > edges(N);
  REP(i,M) {
    int	a, b; cin>>a>>b; a--; b--;
    edges[a].push_back(b);
    edges[b].push_back(a);
    cnt[a][mark[b]]++;
    cnt[b][mark[a]]++;
  }

  vector<bool> ok(N, true);
  int nochange = 0;
  while(! q.empty()) {
    int	cur = q.front();
    q.pop_front();
    if(cnt[cur][0] > 0 && cnt[cur][1] > 0) {
      nochange++;
      if(nochange == q.size()) return true;
      q.push_back(cur);
    } else {
      nochange = 0;
      ok[cur] =	false;
      REP(i, edges[cur].size()) {
	int to = edges[cur][i];
	cnt[to][mark[cur]]--;
      }
    }
  }
  return false;
}

int main() {
  bool ans = solve();
  cout << (ans ? "Yes" : "No") << endl;
  return 0;
}

