        adj[x].insert(y); adj[y].insert(x);
    }
    set<int> nodes;
    for (int i = 0; i < n; i++) nodes.insert(i);
    while (true) {
        bool upd = false;
        set<int> rem;
        for (int i : nodes) {
            bool ba = false, bb = false;
            for (int j : adj[i])
                if (rem.find(j) != rem.end()) (s[j] == 'A' ? ba : bb) = true;
            if (!(ba && bb)) {
                rem.insert(i);
                for (int j : adj[i]) adj[j].erase(i);
                upd = true;
            }
        }
        for (int j : rem) nodes.erase(j);
        if (!upd) break;
    }
    cout << (nodes.empty() ? "No\n" : "Yes\n");
