			if (s[to] == 'B' && goods[to])B = true;
		}
		if (goods[i] != (A&B))change = true;
		goods[i] = (A&B);
	}
}

//計算
void calc()
{
	vector<bool> goods(N, true);
	while (change) {good_points(goods);
	}
	for (auto f : goods)if (f)finalResult = true;
}


//出力
void output()
{
	cout << (finalResult ? "Yes" : "No") << endl;
}


