bool dfs(int x, int l, vector<vector<int> > &adj, string &str, vector<int> &color, vector<int> &L, vector<int> &cv)
{
	//cout << x << " : " << l << endl;

	if (cv[x] >= 2)
		return false;

	int prev = L[x];

	L[x] = l;
	color[x] = 1;
	cv[x]++;

	for (int i = 0; i < adj[x].size(); i++)
	{
		int y = adj[x][i];
		if (y == x)
		{
			if ((color[y] == 1) && (l == prev + 3))
				return true;
		}

		if ((color[y] == 1) && (l == L[y] + 3))
			return true;

		if ((l % 2 == 0) && (str[x] == str[y]))
			continue;

		if ((l % 2 == 1) && (str[x] != str[y]))
			continue;

		if (dfs(y, l + 1, adj, str, color, L, cv))
			return true;
	}

	color[x] = 2;
	return false;
}

