            if (s[v] == 'A' && s[w] == 'A') graph.addEdge(v, N + w);
            if (s[v] == 'A' && s[w] == 'B') graph.addEdge(N+v, 2*N+w);
            if (s[v] == 'B' && s[w] == 'B') graph.addEdge(2*N+v, 3*N+w);
            if (s[v] == 'B' && s[w] == 'A') graph.addEdge(3*N+v, w);
        }
    }

    bool ans = graph.isCyclic();

    if (ans) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }

    return 0;
}

