    while(!removal.empty()) {
        removed++;

        int curr = removal.front();
        removal.pop();

        valid[curr] = false;

        for(auto next : adj[curr]) {
            if(!valid[next]) continue;

            deg[curr]--;
            deg[next]--;

            if(deg[next] < 2 || !both(next)) {
                removal.push(next);
            }
        }
    }

    if(removed < n) works = true;

    if(works) {
        cout << "Yes" << endl;
    }
    else {
        cout << "No" << endl;
    }

    return 0;
}

