void solve() {
  int n, m;
  string s;
  cin >> n >> m >> s;
  while(m--) {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    edges[a].push_back(b);
    edges[b].push_back(a);
    (s[b] == 'A' ? aAdj : bAdj)[a]++;
    (s[a] == 'A' ? aAdj : bAdj)[b]++;
  }
  queue<int> q;
  for(int i = 0; i < n; i++) {
    if(aAdj[i] == 0 || bAdj[i] == 0) {
      q.push(i);
      bad[i] = true;
    }
  }
  while(!q.empty()) {
    int curr = q.front();
    q.pop();
    for(int out: edges[curr]) {
      if(--((s[curr] == 'A' ? aAdj : bAdj)[out]) == 0) {
        if(!bad[out]) {
          bad[out] = true;
          q.push(out);
        }
      }
      assert((s[curr] == 'A' ? aAdj : bAdj)[out] >= 0);
    }
  }
  int good = 0;
  for(int i = 0; i < n; i++) if(!bad[i]) good++;
  if(good) cout << "Yes\n";
  else cout << "No\n";
}

