const int MAX = 2e5+10;

ll N, M;
string S;
set<int> adj[MAX];
int A[MAX], B[MAX];

bool solve() {
    set<int> rm;
    REP (i, N) {
        FORI (iter, adj[i]) {
            if (S[*iter] == 'A') A[i]++;
            else B[i]++;
        }
        if (A[i] == 0 || B[i] == 0) rm.insert(i);
    }

    int count = 0;
    while (!rm.empty()) {
        count++;
        int n = *rm.begin();
        rm.erase(rm.begin());

        FORI (iter, adj[n]) {
            int e = *iter;
            if (e == n) continue;
            adj[e].erase(adj[e].find(n));
            if (S[n] == 'A') A[e]--;
            else B[e]--;
            if (A[e] == 0 || B[e] == 0) rm.insert(e);
        }
    }

    return count != N;
}

