bool sub_a(int a, set<int>& vis) {
    if (found(vis, a)) return false;
    vis.insert(a);

    for (int b: oppc[a]) {
        if (found(vis, b)) continue;
        vis.insert(b);

        if (found(s_loop_b, b)) return true;
        for (int b2: paired[b]) {
            if (sub_b(b2, vis)) return true;
        }
    }
    return false;
}

bool sub_b(int b, set<int>& vis) {
    if (found(vis, b)) return false;
    vis.insert(b);

    for (int a: oppc[b]) {
        if (found(vis, a)) continue;
        vis.insert(a);

        if (found(s_loop_a, a)) return true;
        for (int a2: paired[a]) {
            if (sub_a(a2, vis)) return true;
        }
    }
    return false;
}


bool solve(int N, int M, string& s, vi& a, vi& b) {
    rep(i,M){
        int ca = s[a[i]], cb = s[b[i]];
        // fprintf(stderr, "%d) %d=%c %d=%c\n", i, a[i],ca, b[i],cb);
        if (a[i] == b[i]) {
            if (ca == 'A') {
                loop_a.pb(a[i]);
                s_loop_a.insert(a[i]);
            } else {
                loop_b.pb(a[i]);
                s_loop_b.insert(a[i]);
            }
        } else if (ca == cb) {
            if (ca == 'A') {
                pair_a.pb(ii(a[i], b[i]));
            } else {
                pair_b.pb(ii(a[i], b[i]));
            }
            paired[a[i]].insert(b[i]);
            paired[b[i]].insert(a[i]);
        } else {
            // opposite color
            oppc[a[i]].insert(b[i]);
            oppc[b[i]].insert(a[i]);
        }
    }

    for (ii p: pair_a) {
        int a1=p.first, a2=p.second;

        for (int b1: oppc[a1]) {
            for (int b2: paired[b1]) {
                if (found(oppc[b2], a2)) {
#ifdef DEBUG
                    fprintf(stderr, "! SQUARE");
#endif
                    return true;
                }
            }
        }
    }

    set<int> vis;
    for (int a: loop_a) {
        if (sub_a(a, vis)) return true;
    }
    for (int b: loop_b) {
        if (sub_b(b, vis)) return true;
    }

    return false;
}

