signed main() {
    cin >> N >> M >> s;
    for(int i=0; i<M; i++) {
        int u, v; cin >> u >> v;
        u--; v--;
        G[u].push_back(v);
        G[v].push_back(u);
        // u -> v
        (s[v] == 'A' ? cand_A : cand_B)[u]++;
        // v -> u
        (s[u] == 'A' ? cand_A : cand_B)[v]++;
    }

    // 一手で不可能なやつ
    queue<int> que;
    for(int i=0; i<N; i++) {
        bool find_A = false, find_B = false;
        for(auto to : G[i]) {
            find_A |= (s[to] == 'A');
            find_B |= (s[to] == 'B');
        }
        if((find_A & find_B) == false) {
            // i 番目から任意の文字列を作るのは不可能
            is_terminate[i] = true;
            que.push(i);
        }
    }

    // 推移的にやるやつ
    while(que.size()) {
        int i = que.front(); que.pop();
        // fprintf(stderr, "impossible: %lld\n", i);

        for(auto to : G[i]) {
