#define REP(i, n) for (int i = 0; (i) < (int)(n); ++ (i))
#define REP3(i, m, n) for (int i = (m); (i) < (int)(n); ++ (i))
#define REP_R(i, n) for (int i = int(n) - 1; (i) >= 0; -- (i))
#define REP3R(i, m, n) for (int i = int(n) - 1; (i) >= (int)(m); -- (i))
#define ALL(x) begin(x), end(x)
using ll = long long;
using namespace std;

bool solve(int n, int m, string s, vector<set<int> > const & g) {
    vector<int> a(n), b(n);
    REP (i, n) for (int j : g[i]) {
        (s[j] == 'A' ? a : b)[i] += 1;
    }

    vector<bool> removed(n);
    function<void (int)> go = [&](int i) {
        if (a[i] and b[i]) return;
        if (removed[i]) return;
        removed[i] = true;
        for (int j : g[i]) if (not removed[j]) {
            (s[i] == 'A' ? a : b)[j] -= 1;
            if (not a[j] or not b[j]) {
                go(j);
            }
        }
    };
    REP (i, n) {
        go(i);
    }

    return count(ALL(removed), false);
}

int main() {
    int n, m; cin >> n >> m;
    string s; cin >> s;
    vector<set<int> > g(n);
    REP (i, m) {
        int a, b; cin >> a >> b;
        -- a; -- b;
        g[a].insert(b);
        g[b].insert(a);
    }
    cout << (solve(n, m, s, g) ? "Yes" : "No") << endl;
    return 0;
}

