	if (deleted[i]) {
		return;
	}

	deleted[i] = true;
	for (auto j : edges[i]) {
		if (deleted[j]) {
			continue;
		}

		(s[i] == 'A' ? numA[j] : numB[j])--;

		if (numA[j] == 0 || numB[j] == 0) {
			del(j);
		}
	}
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> n >> m >> s;

	edges.resize(n, vector<int>(n));
	numA.resize(n);
	numB.resize(n);
	deleted.resize(n);

	for (int i = 0; i < m; i++) {
		int a, b;
		cin >> a >> b;
		a--; b--;

		edges[a].emplace_back(b);
		edges[b].emplace_back(a);
		(s[b] == 'A' ? numA[a] : numB[a])++;
		(s[a] == 'A' ? numA[b] : numB[b])++;
	}

	for (int i = 0; i < n; i++) {
		if (numA[i] == 0 || numB[i] == 0) {
			del(i);
		}
	}

	for (int i = 0; i < n; i++) {
		if (!deleted[i]) {
			cout << "Yes" << endl;
			return 0;
		}
	}

	cout << "No" << endl;
	return 0;
}

