inline li calc(li num) {
    li res = 0;
    for (li i = n - 1, k = 0; i >= 0; i -= num, ++k) {
        li right = i;
        li left = max(0ll, i - num + 1);
        if (k == 0) {
            res += 5 * (sum[right + 1] - sum[left]);
        } else {
            res += (2 * k + 3) * (sum[right + 1] - sum[left]);
        }
    }
    return res + x * (num + n);
}


