bool vis[N];

set<int> vc[N];

void add(int x, int y)
{
    int sz = vc[x].size();
    vc[x].insert(y);

    if(sz!=vc[x].size())
        wei[x][type[y]]++;// 0 is red
}

queue<int> Q;
bool topsort()
{
    int ans=0;
    rep(i,1,n+1)
    {
        if(wei[i][0]==0 || wei[i][1]==0){
            Q.push(i);
            vis[i]=1;
            ans++;
        }
    }

    while(Q.size()){
        int cur = Q.front();
        Q.pop();

        for(auto v:vc[cur]){
            wei[v][type[cur]]--;
            if(vis[v]) continue;
            if(wei[v][0]<=0 || wei[v][1]<=0){
                Q.push(v);
                vis[v]=1;
                ans++;
            }

        }
    }
    return ans!=n;
}

