            deg[v][s[u] == 'B']++;
        }
    }

    for (int i = 0; i < n; ++i) {
        minDegV.emplace(min(deg[i][0], deg[i][1]), i);
    }

    set<int> erased;

    while (!minDegV.empty() && minDegV.begin()->first == 0) {
        int v = minDegV.begin()->second;
