            int curMinDeg = min(deg[u][0], deg[u][1]);

            if (curMinDeg != oldMinDeg) {
                assert(minDegV.erase(make_pair(oldMinDeg, u)));
                assert(minDegV.insert(make_pair(curMinDeg, u)).second);
