            dp[lvl][v] = 0;
            forit (it, g[v]) {
                int u = *it;
                dp[lvl][v] |= dp[lvl - 1][u];
            }
        }
    }
    for (int i = 0; i < n; i++)
        if (dp[SZ - 1][i]) return true;
    return false;
}

