            cnts[i][color[v]-'A']++;
        }
    }

    vector<bool> removed(N,false);
    queue<int> leaves;
    rep(i,N) {
        if (cnts[i][0] and cnts[i][1]) continue;
        leaves.push(i);
    }
    while (!leaves.empty()) {
        int v = leaves.front(); leaves.pop();
        for (auto nv : edges[v]) {
            if (removed[nv]) continue;
            cnts[nv][color[v]-'A']--;
            if (v != nv) cnts[v][color[nv]-'A']--;
            if (cnts[nv][0] and cnts[nv][1]) continue;
            leaves.push(nv);
        }
        removed[v] = true;
    }

    bool ok = false;
    rep(i,N) ok |= !removed[i];
    cout << (ok?"Yes":"No") << endl;
    return 0;
}

