int dfs(int i, int c, unordered_set<int>& s) {
	int msk = i * 10 + c;
	if(s.count(msk)) return 1;
	if(seen.count(msk)) return 0;

	s.insert(msk);
	seen.insert(msk);
	int nc = (c + 1) % 4;
	for(auto n : edges[i]) {
		if(color[n] == color_seq[nc]) {
			if(dfs(n, nc, s)) return 1;
		}
	}
	s.erase(msk);
	return 0;
}

