void dfs(int cur, int pr, int ln) {
    used[cur] = 1;
    for (auto lol : ng[cur]) {
        int t, clr;
        tie(t, clr) = lol;
        if (clr != pr) continue;
        if (used[t]) {
            if (ln % 2 == 1) fnd = 1;
        } else {
            dfs(t, pr ^ 1, ln + 1);
        }
    }
}

bool solve() {
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            dfs(i, 0, 0);
        }
    }
    fill(used, used + n, 0);
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            dfs(i, 0, 1);
        }
    }
    return fnd;
}

