bool solve(map<int, pair<set<int>, set<int>>> & A, map<int, pair<set<int>, set<int>>> & B) {
	bool pos = false;
	//Recorremos todas las posiciones de un lado
	for (auto it = A.begin(); it != A.end(); ++it) {
		//Para cada posición buscamos todas aquellas del mismo lado con las que estén conectadas
		for (auto it2 = it->second.first.begin(); it2 != it->second.first.end(); ++it2) {
			for (auto it3 = it->second.second.begin(); it3 != it->second.second.end(); ++it3) {
				for (auto it4 = B[*it3].second.begin(); it4 != B[*it3].second.end(); ++it4) {
					//Cuadrado
					if (A[*it2].second.find(*it4) != A[*it2].second.end()) {
						pos = true;
						goto end;
					}
				}
			}
		}
	}
end:;
	return pos;
}

bool resuelveCaso() {
	int n, m;
	cin >> n >> m;
	if (!cin) return false;

	string lact;
	cin >> lact;

	map<int, pair<set<int>, set<int>>> A;
	map<int, pair<set<int>, set<int>>> B;

	for (int i = 0; i < n; ++i) {
		set<int> aux1, aux2;
		if (lact[i] == 'A') A.insert(mp(i + 1,mp(aux1, aux2)));
		else B.insert(mp(i + 1, mp(aux1, aux2)));
	}

	for (int i = 0; i < m; ++i) {
		int ini, fin;
		cin >> ini >> fin;
		--ini; --fin;
		if (ini == fin) {
			if (lact[ini] == 'A') {
				A[ini + 1].first.insert(ini + 1);
			}
			else {
				B[ini + 1].second.insert(ini + 1);
			}
		}
		else {
			if (lact[min(ini, fin)] == 'A') {
				if (lact[max(ini, fin)] == 'A') {
					A[min(ini, fin) + 1].first.insert(max(ini, fin) + 1);
					A[max(ini, fin) + 1].first.insert(min(ini, fin) + 1);
				}
				else {
					A[min(ini, fin) + 1].second.insert(max(ini, fin) + 1);
					B[max(ini, fin) + 1].first.insert(min(ini, fin) + 1);
				}
			}
			else {
				if (lact[max(ini, fin)] == 'A') {
					B[min(ini, fin) + 1].first.insert(max(ini, fin) + 1);
					A[max(ini, fin) + 1].second.insert(min(ini, fin) + 1);
				}
				else {
					B[min(ini, fin) + 1].second.insert(max(ini, fin) + 1);
					B[max(ini, fin) + 1].second.insert(min(ini, fin) + 1);
				}
			}
		}
	}

	if (solve(A, B)) cout << "Yes\n";
	else cout << "No\n";

	return true;
}

int main() {
	while (resuelveCaso()) {}
	return 0;
}

