struct Graph{
    struct Node{
        char c;
        unordered_set<int> dests;
    };
    vector<Node> nodes;
    Graph(int num): nodes(num){ }
    int id(Node* n){ return n - &nodes[0]; }
    int id(Node& n){ return &n - &nodes[0]; }
    void print(){ for(auto& node : nodes){ prints(id(node), node.dests); } }
    void addEdge(int from, int dest){
        nodes[from].dests.insert(dest);
    }
    void addEdge2(int from, int dest){
        addEdge(from, dest);
        addEdge(dest, from);
    }
    // void dfs(int idx, int from = -1){
    //     for(int didx : nodes[idx].dests){
    //         if(didx == from){ continue; }
    //         dfs(didx, idx);
    //     }
    // }
    bool bad(int idx){
        int s = 0, d = 0;
        for(int didx : nodes[idx].dests){
            s |= nodes[idx].c == nodes[didx].c;
            d |= nodes[idx].c != nodes[didx].c;
        }
        // printd(idx, s, d);
        return s + d != 2;
    }
    void erase(int idx, unordered_set<int>& cands){
        for(int didx : nodes[idx].dests){
            if(idx != didx){
                cands.insert(didx);
                nodes[didx].dests.erase(idx);
            }
        }
        nodes[idx].dests.clear();
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, m;
    cin >> n >> m;
    Graph g(n);
    for(int i = 0; i < n; i++){
        char c; cin >> c;
        g.nodes[i].c = c;
    }
    for(int i = 0; i < m; i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        g.addEdge2(a, b);
    }
    g.print();

    unordered_set<int> cands;
    for(int i = 0; i < n; i++){
        cands.insert(i);
    }
    // iota(cands.begin(), cands.end(), 0);
    unordered_set<int> allBads;
    while(1){
        unordered_set<int> bads;
        for(auto i : cands){
            if(g.bad(i)){
                bads.insert(i);
            }
        }
        if(bads.empty()){ break; }
        allBads.insert(bads.begin(), bads.end());
        cands.clear();
        for(auto i : bads){
            g.erase(i, cands);
        }
        printd(bads, cands);
    }
    // |v| == 1
    g.print();
    cout << ((int)allBads.size() != n ? "Yes" : "No") << '\n';
}

