    vec ab(N);
    REP(i, N){
        if(s[i] == 'A'){
            ab[i] = 1;
        }else{
            ab[i] = 0;
        }
    }
    Graph G(2 * N);
    vec a(M), b(M);
    REP(i, M){
        cin >> a[i] >> b[i];
        a[i]--;
        b[i]--;
        if(ab[a[i]] == ab[b[i]]){
            G.add_edge(a[i], b[i] + N, 0);
            G.add_edge(b[i], a[i] + N, 0);
        }else{
            G.add_edge(a[i] + N, b[i], 0);
            G.add_edge(b[i] + N, a[i], 0);
        }
    }

    bool ans = false;
    vector<bool> tmp_used(2 * N, false), used(2 * N, false);
    REP(i, 2 * N){
        if(used[i]) continue;
        used[i] = true;
        tmp_used[i] = true;
        if(G.dfs(i, tmp_used, used)) ans = true;
        tmp_used[i] = false;
    }


    if(ans){
        cout << "Yes";
    }else{
        cout << "No";
    }

    return 0;
}


