    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; std::swap(a, b);
        u -= t * v; std::swap(u, v);
    }
    u %= m; 
    if (u < 0) u += m;
    return u;
}
bool dfs(ll X,vii  &edge,vii &seen,vector<vector<bool>> &finished,bool type,string &S,ll from){
    rep(i,0,edge[X].size()){
        ll Y=edge[X][i];
        if(Y==from) continue;
        if(seen[Y][!type]==-1){
            if(type){
                if(S[X]==S[Y]) continue;
            }
            else{
                if(S[X]!=S[Y]) continue;
            }
            seen[Y][!type]=seen[X][type]+1;
            bool f=dfs(Y,edge,seen,finished,!type,S,X);
            if(f) return 1;
        }
        else{
            if(type){
                if(S[X]==S[Y]) continue;
            }
            else{
                if(S[X]!=S[Y]) continue;
            }
            if(!finished[Y][!type]&&seen[X][type]-seen[Y][!type]>=3){
            return 1;
        }
    }
    finished[X][type]=1;
    return 0;
}
int main(){
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    ll N,M; cin>>N>>M;
    string S; cin>>S;
    vii edge(N);
    rep(i,0,M){
        ll X,Y; cin>>X>>Y;
        edge[X-1].pb(Y-1);
        edge[Y-1].pb(X-1);
    }
    vii seen(N,vi(2,-1));
    vector<vector<bool>> finished(N,vector<bool>(2));
    rep(i,0,N){
        rep(j,0,2){
            seen[i][j]=0;
            if(dfs(i,edge,seen,finished,j,S,-1)){
                cout<<"Yes"<<endl;
                return 0;
            }
        }
    }
    cout<<"No"<<endl;
}

