{
    long n, m;
    scanf("%ld%ld", &n, &m);
    scanf("%s", str);

    vector<vector<long> > z(n);

    long i,j;
    for(i=0; i<m; i++) {
        long a, b;
        scanf("%ld%ld", &a, &b);
        z[a-1].push_back(b-1);
        z[b-1].push_back(a-1);
    }

    queue<long> que;
    for(i=0; i<n; i++) {
        long a=0, b=0;
        for(j=0; j<z[i].size(); j++) {
            if(str[z[i][j]]=='A') a++;
            else                  b++;
        }
        if(a==0||b==0) {
            que.push(i);
        }
    }

    vector<long> flag(n, 0);
    while( !que.empty() ) {
        long i = que.front();
        que.pop();

        if(flag[i]) continue;

        long a=0, b=0;
        for(j=0; j<z[i].size(); j++) {
            if(!flag[z[i][j]]) {
                if(str[z[i][j]]=='A') a++;
                else                  b++;
            }
        }
        if(a==0||b==0) {
            flag[i]=1;
            for(j=0; j<z[i].size(); j++) {
                if(!flag[z[i][j]]) {
                    que.push( z[i][j] );
                }
            }
        }
    }

    for(i=0; i<n; i++) {
        if(flag[i]==0) {
            printf("Yes\n"); return 0;
        }
    }
    printf("No\n");

    return 0;
}

