bool rec(int v, V<>& vis, const string& s, const VV<>& g) {
  vis[v] = 1;
  bool fa = false, fb = false;
  for (int i : g[v]) if (vis[i] == 1) {
    if (s[i] == 'A') fa = true;
    else fb = true;
  }
  if (!fa) for (int i : g[v]) if (vis[i] == -1 and s[i] == 'A') {
    if (rec(i, vis, s, g)) {
      fa = true;
      break;
    } else vis[i] = 0;
  }
  if (!fb) for (int i : g[v]) if (vis[i] == -1 and s[i] == 'B') {
    if (rec(i, vis, s, g)) {
      fb = true;
      break;
    } else vis[i] = 0;
  }
  return vis[v] = fa and fb;
}

