struct node {
	set<node*> nbs;
	char label;
};

ostream &operator<< (ostream &o, node const& n) {
	return o << "[(" << n.nbs.size() << " neighbours) " << n.label << "]";
}

bool DFS(map<node const *, bool> &marked, node const *a) {
	bool found0 = false, found1 = false;
	if (marked[a]) {
		//Just check if it's good
		for (auto const& i: a->nbs) {
			if(i->label == 'A') found0 = true;
			else found1 = true;
		}
		return found0 && found1;
	}

	marked[a] = true;

	for (auto const &i: a->nbs) {
		if (i->label == 'A') {
			found0 |= DFS(marked, i);
		}
		else {
			found1 |= DFS(marked, i);
		}
	}

	return found0 && found1;
}

bool DFS_driver(vector<node> const& v) {
	map<node const *,bool> marked;

	for(auto const& i: v) {
		marked[&i] = false;
	}

	bool found = false;

	auto it = v.begin();

	do {
		found |= DFS(marked, &(*it));
		it = find_if(it, v.end(), [&marked](node const& n) {return !marked[&n];});
	} while(it != v.end());

	return found;
}

