const int maxn=2e5+5;
const int inf=0x3f3f3f3f;
struct SEG{
#define mid ((l+r)>>1)
#define lef l,mid,pos<<1
#define rgt mid+1,r,pos<<1|1
	int seg[maxn<<2];
	void upd(int p,int v,int l,int r,int pos){
		if(p<l||p>r) return;
		if(l==r) return seg[pos]=v,void();
		if(p<=mid) upd(p,v,lef);
		else upd(p,v,rgt);
		seg[pos]=max(seg[pos<<1],seg[pos<<1|1]);
	}
	int que(int L,int R,int l,int r,int pos){
		if(L>r||R<l) return -inf;
		if(L<=l&&r<=R) return seg[pos];
		return max(que(L,R,lef),que(L,R,rgt));
	}
	void init(){for(int t=0;t<maxn<<2;++t)seg[t]=-inf;}
#undef mid
#undef lef
#undef rgt
}d,s;
int n,data[maxn],val[maxn],Q[maxn],cntx,cnty,MaxX,MaxY;
char ans[maxn];

bool chek(int Max,int rhs){
	if(rhs<0) return 0;
	if(rhs&1) return d.que(Max,n,1,n,1)>=rhs;
	else return s.que(Max,n,1,n,1)>=rhs;
}

int main(){
	n=qr();
	for(int t=1;t<=n;++t) data[t]=qr();
	for(int t=1,Max=0;t<=n;++t){
		if(data[t]>Max) Max=data[t],val[t]=2;
		else val[t]=1;
	}
	for(int t=n;t;--t) Q[t]=Q[t+1]+val[t]-1;
	d.init();
	for(int t=n;t;--t){
		int t1=d.que(data[t],n,1,n,1),t2=s.que(data[t],n,1,n,1);
		if(val[t]==1) d.upd(data[t],t2+1,1,n,1),s.upd(data[t],t1+1,1,n,1);
		else d.upd(data[t],t1+2,1,n,1),s.upd(data[t],t2+2,1,n,1);
	}
	for(int t=1;t<=n;++t){
		d.upd(data[t],1-inf,1,n,1); s.upd(data[t],0,1,n,1);
		if(chek(MaxY,cntx-cnty+Q[t+1]+(data[t]>MaxX))) cntx+=data[t]>MaxX,MaxX=max(MaxX,data[t]),ans[t]='0';
		else if(chek(max(data[t],MaxX),cnty-cntx+Q[t+1]-(data[t]>MaxX))) cntx+=data[t]>MaxX,MaxX=max(MaxX,data[t]),ans[t]='0';
		else cnty+=data[t]>MaxY,ans[t]='1',MaxY=max(MaxY,data[t]);
	}
	if(cntx!=cnty) puts("-1");
	else puts(ans+1);
	return 0;
}

