    stack<int> st;
    st.push(start);
    vector<int> phases(N, -1);
    if (s[start] == 'A') {
      phases[start] = 0;
    } else {
      phases[start] = 2;
    }
    vector<int> this_visited(N);
    while (!st.empty()) {
      int v = st.top();
      st.pop();
      if (visited[v])
        continue;
      visited[v] = 1;
      this_visited[v] = 1;
      ct++;
      int phase = phases[v];
      DEBUG("st", v, phase);
      for (int i : G[v]) {
        if (this_visited[i]) {
