            print("Yes");
            return 0;
          }
        } else {
          if ((phase == 0 || phase == 3) && s[i] == 'A') {
            st.push(i);
            phases[i] = (phase + 1) % 4;
          } else if ((phase == 1 || phase == 2) && s[i] == 'B') {
