vector<int> graph[200006];
string s;

vector<int>* printBFS(int sv,bool *visited){
    vector<int> *v = new vector<int>();
    queue<int> q;
    q.push(sv);
    visited[sv] = true;
    while(!q.empty()){
        int t = q.front();
        q.pop();
        v->push_back(t);
        for(int i=0;i<graph[t].size();i++){
            int neigh = graph[t][i];
            if(!visited[neigh]){
                q.push(neigh);
                visited[neigh] = true;
            }
        }
    }
    return v;
}
bool solve(int n){
    vector<vector<int>*> v;
    bool *visited = new bool[n+1];
    for(int i=1;i<=n;i++)
        visited[i] = false;
    for(int i=1;i<=n;i++)
        if(!visited[i])
            v.push_back(printBFS(i,visited));

    for(int i=0;i<v.size();i++){
        bool done = false;
        int ca = 0,cb = 0;
        for(int j=0;j<v[i]->size();j++){
            if(s[v[i]->at(j)-1]=='A')
                ca++;
            else
                cb++;
        }
        for(int j=0;j<v[i]->size();j++){
            if(ca>=2 && cb>=2)
                break;
            int node = v[i]->at(j);
            if(s[node-1]=='A' && ca<2){
                if(find(graph[node].begin(),graph[node].end(),node)!=graph[node].end())
                    ca++;
            }
            else if(s[node-1]=='B' && cb<2){
                if(find(graph[node].begin(),graph[node].end(),node)!=graph[node].end())
                    cb++;
            }
        }
        if(ca%2==0 && cb%2==0 && ca==cb)
            done = true;
        if(done)
            return true;
    }
    return false;
}
