    for(int i=0;i<m;i++){
        int a,b;
        cin >> a >> b;
        graph[a].pb(b);
        graph[b].pb(a);
    }
    bool ans = solve(n);
    if(ans)
        cout << "Yes";
    else
        cout << "No";
}

