		G[a].pb(b);
		if(a!=b){
			deg[b][s[a]]++;
			G[b].pb(a);
		}
	}
	ms(on, true);
	queue<int> q;
	FOR(v,0,N){
		if(deg[v][0]==0 || deg[v][1]==0){
			on[v]=false;
			q.push(v);
		}
	}
	while(!q.empty()){
		int v=q.front(); q.pop();
		for(int u : G[v]){
			if(!on[u]) continue;
			if((--deg[u][s[v]]) == 0){
				on[u] = false;
				q.push(u);
			}
		}
	}
	bool ans = false;
	FOR(v,0,N) if(on[v]) ans |= deg[v][1-s[v]]>0;
	printf(ans ? "Yes\n" : "No\n");

}

