bool dfs(int now){
  bool a=0,b=0;
  if(dp[now]!=-1){
    if(v[now]!=k)return 0;
    return dp[now];
  }
  if(v[now]==k){
    if(f[now]==0)return false;
    else return true;
  }
  if(v[now]>0)return false;
  v[now]=k;
  if(f[now]==0)return false;
  for(int i=0;i<node[now].size();i++){
    int next=node[now][i];
    if(s[next]=='A'){
      a|=dfs(next);
    }
    if(s[next]=='B'){
      b|=dfs(next);
    }
  }
  return dp[now]=(a&&b);
}

