			if (produceBBAA[a] && S[b] == want) canHit[b] = true;
			if (produceBBAA[b] && S[a] == want) canHit[a] = true;
		}
		produceBBAA = canHit;
	}

	vector<bool> produceAABB (N, true);

	for (char want : {'A', 'A', 'B', 'B'}) {
		vector<bool> canHit (N, false);
		for (auto x : edges) {
			int a = x.first;
			int b = x.second;
			if (produceAABB[a] && S[b] == want) canHit[b] = true;
			if (produceAABB[b] && S[a] == want) canHit[a] = true;
		}
		produceAABB = canHit;
	}

