bool dfs(int u, int t, int d){

	if(d!=u) c[u]=t; bool f=0;

	if(s[u]=='A'){

		if(t==1){
			for(int i=0; i<gr[u].size() && !f; i++){
				int v = gr[u][i];
				if(s[v]=='A'){	
					if(c[v]==-1 || u==v) f=dfs(v,2,u);
				}
			}
		}

		if(t==2){
			for(int i=0; i<gr[u].size() && !f; i++){
				int v = gr[u][i];
				if(s[v]=='B' && c[v]==-1) f=dfs(v,1,u);
			}
		}

	}

	if(s[u]=='B'){

		if(t==1){
			for(int i=0; i<gr[u].size() && !f; i++){
				int v = gr[u][i];
				if(s[v]=='B'){	
					if(c[v]==-1 || u==v) f=dfs(v,2,u);
				}
			}
		}

		if(t==2){
			for(int i=0; i<gr[u].size() && !f; i++){
				int v = gr[u][i];
				if(s[v]=='A' && c[v]==1) return true;
				if(s[v]=='A' && c[v]==-1) f=dfs(v,1,u);
			}
		}

	}

	if(!f && d!=u) c[u]=0;
	return f;
}

