inline bool check(int p){
    char hd;
    if(head[p]<0) return false;
    for(register int j=head[p];j>=0;j=edges[j].next) if(sz[edges[j].to]){
        if(j==head[p]) hd=c[edges[j].to];
        else if(c[edges[j].to]!=hd) return true;
    }
    return false;
}
