	G[from].push_back((edge){to,(int)G[to].size()});
	if(isA[to]){
		GA[from]++;
	}else{
		GB[from]++;
	}
	G[to].push_back((edge){from,(int)G[from].size() - 1});
	if(isA[from]){
		GA[to]++;
	}else{
		GB[to]++;
	}
}

bool delete_edge(int from, edge e){
	GA[from] = 0;
	GB[from] = 0;
