int topo(){
	queue <int> q; while (!q.empty()) q.pop();

	for (int i = 1; i <= n; i++)
		if (!Index[i][0] || !Index[i][1]) q.push(i), vis[i] = true;

	int cnt = 0;
	while (!q.empty()){
		int cur = q.front(); q.pop();
		cnt++;

		for (int i = head[cur]; i; i = e[i].next){
			if (!vis[e[i].to] && !(--Index[e[i].to][str[cur] - 'A'])){
				q.push(e[i].to);
				vis[e[i].to] = true;
			}
		}
	}
	return cnt;

}

