void ins(int u, int v) {nxt[++K] = h[u]; h[u] = K; to[K] = v;}

void dfs(int x, int t)
{
	if(inq[x][t]) {flag = 1; return;}
	if(used[x][t]) return;
	st[++top] = x; T[top] = t; 
	inq[st[top]][T[top]] = 1;
	used[x][t] = 1;
	for(int i = h[x]; i; i = nxt[i])
	{
		if(flag) return;
		if(c[to[i]] == (t ^ 1))
		{
			dfs(to[i], c[x]);
		}
	}
	inq[st[top]][T[top]] = 0;
	top--;
}

