void solve(){
    int N,M;
    string s;
    cin >> N >> M >> s;
    vector<set<int>> graph(N);
    rep(i,0,M){
        int a,b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].insert(b);
        graph[b].insert(a);
    }

    vector<bool> erased(N);
    set<int> st;
    rep(i,0,N){
        bool a=false,b=false;
        for(int j:graph[i]){
            if(s[j]=='A') a=true;
            else b=true;
        }
        if(!a or !b){
            erased[i]=true;
            st.insert(i);
        }
    }

    while(!st.empty()){
        int u=*st.begin();
        st.erase(u);
        for(int v:graph[u])
        {
            graph[v].erase(u);
        }
        for(int v:graph[u]){
            if(erased[v]) continue;
            bool a=false,b=false;
            for(int w:graph[v]){
                if(s[w]=='A') a=true;
                else b=true;
                if(a and b) break;
            }
            if(!a or !b){
                erased[v]=true;
                st.insert(v);
            }
        }
    }

    int cnt=0;
    rep(i,0,N) if(erased[i]) ++cnt;
    cout << (cnt==N?"No":"Yes") << endl;
}

