#include <bits/stdc++.h>
#include <set>
using namespace std;
int N, M; 
vector<int> E[800010]; 
int visited[800010]; 
bool dfs(int V, int &P, bool &loop){
	visited[V] = P;
	for(int i = 0; i < E[V].size(); i++){
      	if(visited[E[V].at(i)] == P) {
			loop = true; break;
		}
		else if(visited[E[V].at(i)] >= 0) break; 
		dfs(E[V].at(i), P, loop); 
	}
	return loop; 
}
int main(){
	string S; 
	cin >> N >> M >> S; 
	set<pair<int, int>> T;
	for(int i = 0; i < M; i++){
		int a, b; cin >> a >> b; 
		a--; b--; 
		if(a > b) swap(a, b); 
		T.insert(make_pair(a, b)); 
	}
	for(auto it = T.begin(); it != T.end(); it++){
		int a = (*it).first; int b = (*it).second; 
		if(S[a] == 'A' && S[b] == 'A'){
			E[4*a+3].push_back(4*b); 
			if(a!= b) E[4*b+3].push_back(4*a); 
		}
		if(S[a] == 'A' && S[b] == 'B'){
			E[4*a].push_back(4*b+1); 
			E[4*b+2].push_back(4*a+3); 
		}
		if(S[a] == 'B' && S[b] == 'A'){
			E[4*a+2].push_back(4*b+3); 
			E[4*b].push_back(4*a+1); 
		}
		if(S[a] == 'B' && S[b] == 'B'){
			E[4*a+1].push_back(4*b+2); 
			if(a != b) E[4*b+1].push_back(4*a+2); 
		}
	}
	bool ans = false; bool loop; 
	fill(visited, visited+N*4, -1); 
	int P; 
	for(int i = 0; i < N*4; i++){
		if(visited[i] != -1) continue; 
		P = i; loop = false; 
		ans |= dfs(i, P, loop); 
	}
	cout << (ans ? "Yes" : "No") << endl;
}

