#include <bits/stdc++.h>
#define R register

const int MN = 8e5 + 5;

std::string s;

int n, m, d[MN];

struct Edge {
	Edge *nxt;
	int to;
	Edge(Edge *hd = nullptr, int v = 0){nxt = hd, to = v;}
}*hd[MN];

inline void ins(int u, int v) {hd[u] = new Edge(hd[u], v); ++d[v];}

int main() {
	std::ios::sync_with_stdio(false);

	std::cin >> n >> m >> s;

	for (R int i = 1, x, y; i <= m; ++i) {
		std::cin >> x >> y;
		if (x == y) {
			ins(x + n, x + n * 2);
			ins(x + n * 3, x);
			continue;
		}
		if (s[x - 1] == s[y - 1]) {
			ins(x + n, y + n * 2);
			ins(y + n, x + n * 2);
			ins(x + n * 3, y);
			ins(y + n * 3, x);
			ins(x + n, y);
			ins(y + n, x);
			ins(x + n * 3, y + n * 2);
			ins(y + n * 3, x + n * 2);
		} 
		else {
			ins(x, y + n);
			ins(x, y + 3 * n);
			ins(x + 2 * n, y + n);
			ins(x + 2 * n, y + 3 * n);
			ins(y, x + n);
			ins(y, x + 3 * n);
			ins(y + 2 * n, x + n);
			ins(y + 2 * n, x + 3 * n);
		}
	}

	std::queue<int> q;
	for (R int i = 1; i <= n * 4; ++i)
		if (!d[i]) q.push(i);

	while (!q.empty()) {
		R int u = q.front(); q.pop();
		for (Edge *e = hd[u]; e != nullptr; e = e -> nxt) 
			if (--d[e -> to] == 0) 
				q.push(e -> to);
	}

	for (R int i = 1; i <= n * 4; ++i) 
		if (d[i]) {
			std::cout << "Yes\n";
			return 0;
		}
	std::cout << "No\n";
	return 0;
}

