bool solve(map<int, pair<set<int>, set<int>>> & A, map<int, pair<set<int>, set<int>>> & B) {
	bool pos = false;
	//Recorremos todas las posiciones de un lado
	for (auto it = A.begin(); it != A.end() && !pos; ++it) {
		//Para cada posición buscamos todas aquellas del mismo lado con las que estén conectadas
		for (auto it2 = it->second.first.begin(); it2 != it->second.first.end() && !pos; ++it2) {
			for (auto it3 = it->second.second.begin(); it3 != it->second.second.end() && !pos; ++it3) {
				for (auto it4 = B[*it3].second.begin(); it4 != B[*it3].second.end() && !pos; ++it4) {
					//Cuadrado
					if (A[*it2].second.find(*it4) != A[*it2].second.end()) {
						pos = true;
					}
				}
			}
		}
	}
	return pos;
}

