const int N=2e5+5;
int n,m,d[N][2],tot,head[N],nex[N<<1],to[N<<1];
void add(int u,int v){to[++tot]=v;nex[tot]=head[u];head[u]=tot;}
bool vis[N];
struct edge
{
    int u,v;
}e[N];
