set<int> E[200000];
string s;
bool u;
int N,M;
int label[200000];
void dfs(int x, int y){
    if(E[x].find(y)==E[x].end()) return;
    if(label[x]==4){
        if(s[x]=='A'&&s[y]=='A') label[x]=0;
        if(s[x]=='A'&&s[y]=='B') label[x]=1;
        if(s[x]=='B'&&s[y]=='B') label[x]=2;
        if(s[x]=='B'&&s[y]=='A') label[x]=3;
    }
    if((s[x]=='A'&&s[y]=='A'&&label[y]==1)||(s[x]=='A'&&s[y]=='B'&&label[y]==2)||
       (s[x]=='B'&&s[y]=='B'&&label[y]==3)||(s[x]=='B'&&s[y]=='A'&&label[y]==0)){
        u=true;
      	E[x].erase(y);
        return;
    }
    else{
        E[x].erase(y);
        set<int> v;
        v=E[y];
        for(auto itr=v.begin();itr!=v.end();itr++){
            if(s[x]!=s[y]&&s[y]==s[*itr]) dfs(y,*itr);
            else if(s[x]==s[y]&&s[y]!=s[*itr]) dfs(y,*itr);
        }
        if(label[x]=1||label[x]=3) label[x]=4;
    }
}
