    }
    rep(i,0,N){
        while(sz(E[i])){
            rep(i,0,N) label[i]=4;
            u=false;
            auto itr=E[i].begin();
            int k=*itr;
            dfs(i,k);
            if(u){
                cout <<"Yes"<<"\n";
                return 0;
            }
        }
    }
    cout <<"No"<<"\n";
}

