typedef long long LL;
inline LL rd() {
	char ch=getchar(); LL i=0,f=1;
	while(!isdigit(ch)) {if(ch=='-')f=-1; ch=getchar();}
	while(isdigit(ch)) {i=(i<<1)+(i<<3)+ch-'0'; ch=getchar();}
	return i*f;
}

const int N=2e5+50, mod=1e9+7;
int n,m,vis[N];
int cnt[N][2],type[N];
vector <int> edge[N];
char ch[N];

int main() {
	n=rd(), m=rd();
	scanf("%s",ch+1);
	for(int i=1;i<=n;i++) type[i]=(ch[i]=='A') ? 0 : 1;
	for(int i=1;i<=m;i++) {
		int x=rd(), y=rd();
		if(x!=y) {
			edge[x].push_back(y);
			edge[y].push_back(x);
		}
		++cnt[x][type[y]];
		++cnt[y][type[x]];
	}
	queue <int> q; int cc=0;
	for(int i=1;i<=n;++i) if(!cnt[i][0] || !cnt[i][1]) q.push(i), vis[i]=1;
	while(!q.empty()) {
		int u=q.front(); q.pop();  ++cc;
		for(auto e:edge[u]) if(!vis[e]) {
			cnt[e][type[u]]--;
			if(!cnt[e][0] || !cnt[e][1]) q.push(e), vis[e]=1;
		}
	}
