const int N = 2e5 + 10;

int n, m;
int dega[N], degb[N];
bool bad[N];
char S[N];
vector<int> G[N];

int main() {

	scanf("%d%d", &n, &m);
	scanf("%s", S + 1);
	For(i, 1, m) {
		int u, v;
		scanf("%d%d", &u, &v);
		G[v].pb(u), G[u].pb(v);
		if (S[v] == 'A') ++dega[u];
		else ++degb[u];
		if (S[u] == 'A') ++dega[v];
		else ++degb[v];
	}

	queue<int> q;
	For(i, 1, n) if (!dega[i] || !degb[i]) {
		bad[i] = true;
		q.push(i);
	}

	while (!q.empty()) {
		int o = q.front(); q.pop();
		for (int v : G[o]) if (!bad[v]) {
			if (S[o] == 'A') --dega[v];
			else --degb[v];
			if (!dega[v] || !degb[v]) q.push(v), bad[v] = true;
		}
	}

	For(i, 1, n) if (!bad[i]) {
		puts("Yes");
		return 0;
	}
	puts("No");

	return 0;
