bool solve(int N, int M, string& s, vi& a, vi& b) {
    vector<set<int>> a_side(N), b_side(N);

    rep(i,M){
        int u = a[i], v = b[i];
        int cu = s[u], cv = s[v];

        if (cv == 'A')
            a_side[u].insert(v);
        else
            b_side[u].insert(v);

        if (cu == 'A')
            a_side[v].insert(u);
        else
            b_side[v].insert(u);
    }

    vi ac(N,0), bc(N,0);
    rep(i,N){
        ac[i] = a_side[i].size();
        bc[i] = b_side[i].size();
    }

    set<int> killed;
    int newly_killed = 0;

    do {
        newly_killed = 0;
        rep(i,N){
            if (found(killed, i)) continue;
            if (ac[i] == 0 || bc[i] == 0) {
                ++newly_killed;
                killed.insert(i);

                for (int a: a_side[i]) {
                    if (s[i] == 'A') --ac[a];
                    if (s[i] == 'B') --bc[a];
                }
                for (int b: b_side[i]) {
                    if (s[i] == 'A') --ac[b];
                    if (s[i] == 'B') --bc[b];
                }
            }
        }
    } while (newly_killed > 0);

    return killed.size() < N;
}

