int get() {
    int res = (rand() << 15)|rand();
    res %= mod;
    if (res < 0) res += mod;
    return res;
}

void shuffle(vector<int> &v) {
    for (int i = 1; i < sz(v); i++) {
        swap(v[i], v[get() % (i + 1)]);
    }
}

void check3(int a, int b, int c, int &res) {
    if (col[a] == col[b] && col[a] == col[c]) return;
    if (col[a] != col[b] && col[a] != col[c] && has_self[a]) res = 1;
    swap(a, b);
    if (col[a] != col[b] && col[a] != col[c] && has_self[a]) res = 1;
    swap(a, c);
    if (col[a] != col[b] && col[a] != col[c] && has_self[a]) res = 1;
}

void check4(int a, int b, int c, int d, int &res) {
    int x[2] = {0, 0};
    x[col[a]]++; 
    x[col[b]]++; 
    x[col[c]]++; 
    x[col[d]]++; 
    if (x[0] != x[1]) return;
    if (col[a] == col[b] || col[b] == col[c] || col[c] == col[d] || col[d] == col[a]) res = 1;
}

void dfs(int v, int p, int lvl, int sz, int &res) {
    used[v] = 1;
    level[v] = lvl;
    par[v] = p;
    forit (it, g[v]) {
        int u = *it;
        if (u == v) continue;
        if (u == p) continue;
        if (used[u] && level[v] - level[u] + 1 == sz) {
            if (sz == 3) check3(v, par[v], par[par[v]], res);
            else check4(v, par[v], par[par[v]], par[par[par[v]]], res);
        }
    }
    forit (it, g[v]) {
        int u = *it;
        if (used[u]) continue;
        dfs(u, v, lvl + 1, sz, res);
    }
}

bool solve(int sz) {
    for (int i = 0; i < n; i++) {
        shuffle(g[i]);
    }
    int res = 0;
    int v = get() % n;
    memset(par, -1, sizeof par);
    memset(used, 0, sizeof used);
    dfs(v, -1, 0, sz, res);
    return res;
}

