        checked[i]=turn;
        while(!cur.empty()){
            pair<int,ll> t=cur.front();
            cur.pop();
            for(int to:v[t.second%p]){
                if((t.first<=2)==(s[to-1]=='A')) continue;
                if(checked[edge2idx[e(t.second%p,to)]]!=0){
                    if(checked[edge2idx[e(t.second%p,to)]]==turn){
