                        return 0;
                    }else{
                        continue;
                    }
                }
                cur.push(make_pair((t.first+1)%4,e(t.second%p,to)));
                checked[edge2idx[e(t.second%p,to)]]=turn;
            }
        }
        turn++;
    }
    cout << "No" << endl;

    return 0;
}

