bool solve(int N, int M, string& s, vi& a, vi& b) {
    vector<set<int>> a_side(N), b_side(N);

    rep(i,M){
        int u = a[i], v = b[i];
        int cu = s[u], cv = s[v];

        if (cv == 'A')
            a_side[u].insert(v);
        else
            b_side[u].insert(v);

        if (cu == 'A')
            a_side[v].insert(u);
        else
            b_side[v].insert(u);
    }

    vi ac(N,0), bc(N,0);
    rep(i,N){
        ac[i] = a_side[i].size();
        bc[i] = b_side[i].size();
    }

    set<int> alive;
    rep(i, N) alive.insert(i);

    while (true) {
        vi to_be_erased;

        for (int i: alive) {
            if (ac[i] == 0 || bc[i] == 0) {
                to_be_erased.pb(i);

                for (int a: a_side[i]) {
                    if (s[i] == 'A') --ac[a];
                    if (s[i] == 'B') --bc[a];
                }
                for (int b: b_side[i]) {
                    if (s[i] == 'A') --ac[b];
                    if (s[i] == 'B') --bc[b];
                }
            }
        }

        if (to_be_erased.empty()) break;
        for (int i: to_be_erased) alive.erase(i);
    }

    return alive.size() > 0;
}

int main() {
    int N, M; cin >> N >> M;
    string s; cin >> s;
    vi a(M), b(M);
    rep(i,M) { scanf("%d %d", &a[i], &b[i]); --a[i]; --b[i]; }
    cout << (solve(N,M,s,a,b) ? "Yes":"No") << endl;
    return 0;
}

