		int yc = (ababa[y] == 'A' ? 0 : 1);

		if(x == y) {
			g[x].count[yc] += 1;
			g[x].edges[yc].push_back(y);
		} else {
			g[x].count[yc] += 1;
			g[x].edges[yc].push_back(y);
			g[y].count[xc] += 1;
			g[y].edges[xc].push_back(x);
		}
	}

	vector<bool> live(n, true);
	queue<int> q;

	for(int i = 0; i < n; ++i) {
		if(g[i].count[0] <= 0 || g[i].count[1] <= 0)
			q.push(i);
	}

	while(!q.empty()) {

		int v = q.front();
		q.pop();

		if(!live[v])
			continue;
		live[v] = false;

		int vc = (ababa[v] == 'A' ? 0 : 1);

		for(int color = 0; color < 2; ++color) {
			for(auto w : g[v].edges[color]) {

				if(v == w)
					continue;
				if(!live[w])
					continue;

				g[w].count[vc] -= 1;
				if(g[w].count[vc] <= 0)
					q.push(w);
			}
		}
	}

	bool ok = false;

	for(auto l : live)
		ok = ok || l;

	printf("%s\n", ok ? "Yes" : "No");

	return 0;
}

