bool dfs(int x, int f) {
	u[x][f] = 1;
	for (int y : e[x]) {
		if (f) {
		  if (a[x] == a[y]) continue;
		  if (u[y][0] == 1) return true;		  
		  if (u[y][0] == 2) continue;
		  if (dfs(y, 0)) return true;
		} else {
			if (a[x] != a[y]) continue;
			if (u[y][1] == 1) return true;		  
		  if (u[y][1] == 2) continue;
			if (dfs(y, 1)) return true;
		}
	}
	u[x][f] = 2;
	return false;
}

bool dfs2(int x, int f) {
	if (loop[x] && f == 0) return 1;
	u[x][f] = 1;

	for (auto y : e[x]) {
		 if (f) {
		  if (a[x] == a[y]) continue;
		  if (u[y][0] == 1) return true;		  
		  if (u[y][0] == 2) continue;
		  if (dfs2(y, 0)) return true;
		} else {
			if (a[x] != a[y]) continue;
			if (u[y][1] == 1) return true;		  
		  if (u[y][1] == 2) continue;
			if (dfs2(y, 1)) return true;
		}
	}

	u[x][f] = 2;
	return false;
}

void solve() {
	memset(u, 0, sizeof(u));
	fi(1, n) {
		if (u[i][0]) continue;
		dbg(i);
		if (dfs(i, 0)) { 
			ok();
		}
	}

	memset(u, 0, sizeof(u));

	fi(1, n) {
		if (u[i][1]) continue;
		if (!loop[i]) continue;
		if (dfs2(i, 1)) ok();
	}

	printf("No\n");
}

