bool dfs(const vector<vector<int>> &G, const string &S, vector<int> &V, int v, int t, int u){
  bool ret = false;
  V[v] |= (1<<t);
  t = (t+1)%4;
  for(size_t i = 0; i < G[v].size(); ++i){
    int v_ = G[v][i];
