int main() {
  scanf("%d %d", &n, &m);
  scanf("%s", s);
  for (int i = 0; i < n; i++) {
    s[i] -= 'A';
  }
  for (int i = 0; i < m; i++) {
    int u, v;
    scanf("%d %d", &u, &v);
    u--;
    v--;
    g[u].push_back(v);
    deg[u][s[v]]++;
    if (u != v) {
      g[v].push_back(u);
      deg[v][s[u]]++;
    }
  }
  queue<int> que;
  for (int i = 0; i < n; i++) {
    if (deg[i][0] == 0 || deg[i][1] == 0) {
      que.push(i);
      used[i] = true;
    }
  }
  while (!que.empty()) {
    n--;
    int u = que.front(); que.pop();
    for (int v : g[u]) if (v != u) {
      if (--deg[v][s[u]] == 0) {
        if (!used[v]) {
          used[v] = true;
          que.push(v);
        }
      }
    }
  }
  puts(n > 0 ? "Yes" : "No");
}

