vector<unordered_map<int,int>> BBConnect;
vector<unordered_map<int,int>> ABConnect;
vector<unordered_map<int,int>> BAConnect;

bool searchPath(bool state, bool cont, vector<bool> unused, int A, int B) {
  if (cont) {
    if (state) { // B
      for (auto itrB = BBConnect[B].begin(); itrB != BBConnect[B].end(); ++itrB) {
        if (unused[itrB->first]) {
          unused[itrB->first] = false;
          if(searchPath(true, false, unused, A, itrB->first)) return true;
        }
      }
    }
    else { // A
      for (auto itrA = AAConnect[A].begin(); itrA != AAConnect[A].end(); ++itrA) {
        if (unused[itrA->first]) {
          unused[itrA->first] = false;
          if(searchPath(false, false, unused, itrA->first, B)) return true;
        }
        else return true;
      }
    }
  }
  else {
    if (state) { // B
      for (auto itrA = BAConnect[B].begin(); itrA != BAConnect[B].end(); ++itrA) {
        if (unused[itrA->first]) {
          unused[itrA->first] = false;
          if(searchPath(false, true, unused, itrA->first, B)) return true;
        }
      }
    }
    else { // A
      for (auto itrB = ABConnect[A].begin(); itrB != ABConnect[A].end(); ++itrB) {
        if (unused[itrB->first]) {
          unused[itrB->first] = false;
          if(searchPath(true, true, unused, A, itrB->first)) return true;
        }
      }
    }
  }
}

