template <class T, class U>
inline bool chmin(T& lhs, const U& rhs) {
  if (lhs > rhs) {
    lhs = rhs;
    return true;
  }
  return false;
}

template <class T, class U>
inline bool chmax(T& lhs, const U& rhs) {
  if (lhs < rhs) {
    lhs = rhs;
    return true;
  }
  return false;
}

// [l, r) from l to r
struct range {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { ++i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr l, r;
  constexpr range(int l_, int r_): l(l_), r(std::max<int>(l_, r_)) { }
  constexpr itr begin() const { return l; }
  constexpr itr end() const { return r; }
};

// [l, r) from r to l
struct revrange {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { --i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr r, l;
  constexpr revrange(int l_, int r_): l(l_ - 1), r(std::max<int>(l_, r_) - 1) { }
  constexpr itr begin() const { return r; }
  constexpr itr end() const { return l; }
};

template <class T>
inline T scan() {
  T res;
  std::cin >> res;
  return res;
}

int main() {
  const int N = scan<int>();
  const int M = scan<int>();
  const std::string S = scan<std::string>();
  std::vector<std::vector<int>> graph(N);
  for (const int i: range(0, M)) {
    const int a = scan<int>() - 1;
    const int b = scan<int>() - 1;
    graph[a].push_back(b);
    graph[b].push_back(a);
  }
  std::vector<int> count_A(N, 0), count_B(N, 0);
  std::vector<bool> done(N, false);
  std::queue<int> que;
  for (const int u: range(0, N)) {
    for (const int v: graph[u]) {
      if (S[v] == 'A') {
        ++count_A[u];
      }
      else {
        ++count_B[u];
      }
    }
    if ((count_A[u] <= 0 || count_B[u] <= 0) && !done[u]) {
      done[u] = true;
      que.push(u);
    }
  }
  int count = 0;
  while (!que.empty()) {
    int u = que.front();
    que.pop();
    ++count;
    for (const int v: graph[u]) {
      if (S[u] == 'A') {
        --count_A[v];
      }
      else {
        --count_B[v];
      }
      if ((count_A[v] <= 0 || count_B[v] <= 0) && !done[v]) {
        done[v] = true;
        que.push(v);
      }
    }
  }
  std::cout << (count == N ? "No" : "Yes") << '\n';
  return 0;
}

