bool solve(int N, int M, string& s, vi& a, vi& b) {
    vector<set<int>> a_side(N), b_side(N);
    vvi connected(N);

    rep(i,M){
        int u = a[i], v = b[i];
        int cu = s[u], cv = s[v];

        if (cv == 'A')
            a_side[u].insert(v);
        else
            b_side[u].insert(v);

        if (cu == 'A')
            a_side[v].insert(u);
        else
            b_side[v].insert(u);

        if (u != v) {
            connected[u].pb(v);
            connected[v].pb(u);
        }
    }

    set<int> killed;
    int newly_killed = 0;

    do {
        newly_killed = 0;
        rep(i,N){
            if (found(killed, i)) continue;
            if (a_side[i].empty() || b_side[i].empty()) {
                ++newly_killed;
                killed.insert(i);
                for (int c: connected[i]) {
                    if (found(a_side[c], i)) a_side[c].erase(i);
                    if (found(b_side[c], i)) b_side[c].erase(i);
                }
            }
        }
    } while (newly_killed > 0);

    return killed.size() < N;
}

