inline LL bigmod(LL b, LL p, LL m)
{
    LL ret = 1, cur = b % m;
    while( p )
    {
        if(p & 1) ret = ( ret * cur ) % m;
        cur = ( cur * cur ) % m;
        p = p >> 1;
    }
    return ret;
}

