		}
		else add(a[i].u,a[i].v),g[a[i].u][f[a[i].v]]++;
	}

	l=0,r=-1,tot=n;
	for (int i=1;i<=n;i++) if (g[i][0]*g[i][1]==0) q[++r]=i,d[i]=1;
	while (l<=r){
		x=q[l++],tot--;
		For(x) if (!d[o]){
			g[o][f[x]]--;
			if (g[o][f[x]]==0) d[o]=1,q[++r]=o;
		}
	}

	if (tot) printf("Yes\n");else printf("No\n");
}

