inline void yes() {
	puts("Yes");
	exit(0);
} 

int main()
{
	#ifdef LOCAL
	freopen(fname".in", "r", stdin);
	freopen(fname".out", "w", stdout);
	#endif

	scanf("%d%d", &n, &m);
	scanf("%s", s);
	for (int i = 0; i < m; ++i) {
		int v1, v2;
		scanf("%d%d", &v1, &v2);
		--v1, --v2;
		if (v1 == v2) {
			ok[v1] = 1;
			continue;
		}
		g[v1].pb(v2);
		g[v2].pb(v1);
		gg[v1].insert(v2);
		gg[v2].insert(v1);
	}

	for (int i = 0; i < n; ++i) {
		sort(all(g[i]));
		g[i].erase(unique(all(g[i])), g[i].end());
	}

	for (int i = 0; i < n; ++i) {
		if (!ok[i]) continue;
		for (const int& j : g[i]) {
			if (ok[j] && s[i] != s[j]) {
				puts("Yes");
				return 0;			
			}
		}
	}

	for (int i = 0; i < n; ++i) {
		if (sz(g[i]) > K) continue;
		int cur = s[i] - 'A';
		for (const int& j1 : g[i]) {
			if (s[i] == s[j1]) continue;
			if (ok[i] && ok[j1]) yes();
			for (const int& j2 : g[i]) {
				if (j1 < j2 && s[i] != s[j2] && ok[i] && gg[j1].count(j2)) yes();
				if (s[i] == s[j2]) {
					if (d[!cur][j1].count(j2)) yes();
					d[cur][j2].insert(j1);				
				}
			}
		}
	}

	for (int i = 0; i < n; ++i) {
		if (sz(g[i]) <= K) continue;
		for (const auto& j : g[i]) mark[j] = 1;
		for (int j = 0; j < n; ++j) {
			if (j != i && s[i] != s[j] && (j < i || sz(g[j]) <= K)) {
				++cc;
				int ij = gg[i].count(j);
				if (ok[i] && ok[j]) yes();
				for (const auto& k : g[j]) {
					if (k != i && mark[k]) {
						if (ok[i] && ij && s[i] != s[k]) yes();
						if (ok[j] && ij && s[i] == s[k]) yes();
						c[s[k] - 'A'] = cc;
					}	
				}
				if (c[0] == cc && c[1] == cc) yes();
			}
		}
		for (const auto& j : g[i]) mark[j] = 0;
	}

	puts("No");

	return 0;
}

