inline void dfs(int x, int c, int nf) {
	// if (pos == 1) printf("%d %c %d\n", x, S[c], nf);
	if (flag) return;
	if (c == 0 && nf) {
		if (x == pos) flag = 1;
		return;
	}
	for (int i = hd[x]; i; i = nxt[i]) {
	//	printf("%d %d %c %c\n", x, to[i], col[to[i]], S[c]);
		if (col[to[i]] == S[c])
			dfs(to[i], (c+1)%4, 1);
	}
}

