ll edges[400001];
int checked[400001];
int phase[400001];
vector<int> v[200001];

int main(){
    int N, M;
    cin >> N >> M;
    string s;
    cin >> s;

    map<ll,int> edge2idx;
    for(int i=1;i<=M;i++){
        int a,b;
        cin >> a >> b;

        edges[2*i]=e(a,b);
        edges[2*i+1]=e(b,a);

        checked[2*i]=0;
        checked[2*i+1]=0;
        phase[2*i]=INT32_MAX;
        phase[2*i+1]=INT32_MAX;

        if(edge2idx[e(a,b)]==0){
            edge2idx[e(a,b)]=2*i;
            v[a].push_back(b);
        }
        else checked[2*i]=-1;

        if(edge2idx[e(b,a)]==0){
            edge2idx[e(b,a)]=2*i+1;
            v[b].push_back(a);
        }
        else checked[2*i+1]=-1;
    }
    int turn=1;
    for(int i=1;i<=M;i++){
        queue<pair<pair<int,ll>,set<ll>>> cur;
        if(s[edges[i]/p-1]!='A' || s[edges[i]%p-1]!='A' || checked[i]!=0) continue;
        set<ll> set_e;
        set_e.insert(edges[i]);
        cur.push(make_pair(make_pair(0,edges[i]),set_e));
        checked[i]=turn;
        phase[i]=0;
        while(!cur.empty()){
            pair<int,ll> t=cur.front().first;

            cur.pop();
            for(int to:v[t.second%p]){
                if((t.first%4<2)==(s[to-1]=='A')) continue;
                if(checked[edge2idx[e(t.second%p,to)]]!=0){
                    if(checked[edge2idx[e(t.second%p,to)]]==turn && phase[edge2idx[e(t.second%p,to)]]<t.first+1){
                        if(cur.front().second.count(e(t.second%p,to))>0){
                            cout << "Yes" << endl;
                            return 0;
                        }else{
                            continue;
                        }
                    }else{
                        continue;
                    }
                }
                set<ll> set_tp(cur.front().second);
                set_tp.insert(e(t.second%p,to));
                cur.push(make_pair(make_pair(t.first+1,e(t.second%p,to)),set_tp));
                phase[edge2idx[e(t.second%p,to)]]=t.first+1;
                checked[edge2idx[e(t.second%p,to)]]=turn;
            }
        }
        turn++;
    }
    cout << "No" << endl;

    return 0;
}

