struct Graph{
    struct Node{
        char c;
        int s = 0, d = 0;
        unordered_set<int> dests;
    };
    vector<Node> nodes;
    Graph(int num): nodes(num){ }
    int id(Node* n){ return n - &nodes[0]; }
    int id(Node& n){ return &n - &nodes[0]; }
    void print(){ for(auto& node : nodes){ prints(id(node), node.dests); } }
    void addEdge(int from, int dest){
        nodes[from].dests.insert(dest);
    }
    void addEdge2(int from, int dest){
        addEdge(from, dest);
        addEdge(dest, from);
    }
    void init(int idx){
        for(int didx : nodes[idx].dests){
            nodes[idx].s += nodes[idx].c == nodes[didx].c;
            nodes[idx].d += nodes[idx].c != nodes[didx].c;
        }
    }
    bool bad(int idx){
        // printd(idx, nodes[idx].s, nodes[idx].d);
        return !nodes[idx].s || !nodes[idx].d;
    }
    void erase(int idx, unordered_set<int>& cands, unordered_set<int>& allBads){
        for(int didx : nodes[idx].dests){
            if(idx != didx){
                nodes[didx].s -= nodes[didx].c == nodes[idx].c;
                nodes[didx].d -= nodes[didx].c != nodes[idx].c;
                if(!allBads.count(didx) && bad(didx)){
                    cands.insert(didx);
                }
                nodes[didx].dests.erase(idx);
            }
        }
        nodes[idx].dests.clear();
    }
};

