        int a, b;
        cin >> a >> b;
        a--; b--;
        g.addEdge2(a, b);
    }
    for(int i = 0; i < n; i++){
        g.init(i);
    }
    // g.print();

    unordered_set<int> cands;
    cands.reserve(n);
    for(int i = 0; i < n; i++){
        cands.insert(i);
    }
    // iota(cands.begin(), cands.end(), 0);
    unordered_set<int> allBads;
    allBads.reserve(n);
    while(1){
        unordered_set<int> bads;
        for(auto i : cands){
            if(g.bad(i)){
                bads.insert(i);
            }
        }
        if(bads.empty()){ break; }
        cands.clear();
        allBads.insert(bads.begin(), bads.end());
        for(auto i : bads){
            g.erase(i, cands, allBads);
        }
