bool ok = false;

void dfs(int v,int d,int state){
	visited[v][state % 2] = d;
	for(auto &v2:alt_graph[v]){
		if((state % 2 == 0) == (s[v] == s[v2])){
			if(visited[v2][1 - (state % 2)] != -1){
				const int len = d + 1 - visited[v2][1 - (state % 2)];
				if(len > 0 and len % 4 == 0) ok = true;
				return;
			} 
			dfs(v2,d+1,(state + 1) % 4);
		}
	}

	return;
}

