		if(ea[i] == eb[i]){
			dupl[ea[i]] = true;
			graph[ea[i]].push_back(ea[i] + n);
			graph[ea[i] + n].push_back(ea[i]);
		}
	}

	rep(i,m){
		if(ea[i] == eb[i]) continue;
		graph[ea[i]].push_back(eb[i]);
