bool dfs(int now,bool need){
    if(dp[now][need])return false;
    in.insert({now,need});
    if(need==f[now]&&self[now]){
        for(int i:graph[now])if(f[i]!=need){
            if(in.find({i,!need})!=in.end())return true;
            else if(dfs(i,!need))return true;
        }
    }
    if(need==f[now]){
        for(int i:graph[now])if(f[i]==need){
            if(in.find({i,!need})!=in.end())return true;
            else if(dfs(i,!need))return true;
        }
    }
    else{
        for(int i:graph[now])if(f[i]==need){
            if(in.find({i,need})!=in.end())return true;
            else if(dfs(i,need))return true;
        }
    }
    in.erase({now,need});
    dp[now][need]=true;
    return false;
}
