int n, m;
string s;
vector<int> g[200005];
bool ok[200005];
bool used[200005];
void dfs(int i) {
    if (!ok[i] || used[i]) return;
    used[i] = true;
    bool b1 = false, b2 = false;
    rep(j, sz(g[i])) {
        auto v = g[i][j];
        dfs(v);
        if (s[v] == 'A') b1 |= ok[v];
        else b2 |= ok[v];
    }
    if (!b1 || !b2) {
        ok[i] = false;
        rep(j, sz(g[i])) {
            auto v = g[i][j];
            used[v] = false;
            dfs(v);
        }
    }
}

void solve() {
    cin >> n >> m >> s;
    rep(i, m) {
        int a, b; cin >> a >> b; --a; --b;
        g[a].push_back(b); g[b].push_back(a);
    }

    rep(i, n) {
        bool b1 = false, b2 = false;
        rep(j, sz(g[i])) {
            auto v = g[i][j];
            if (s[v] == 'A') b1 = true;
            else b2 = true;
        }
        if (b1 && b2) ok[i] = true;
    }

    rep(i, n) dfs(i);

    bool ans = false;
    rep(i, n) if (ok[i]) { ans = true; break; }
    if (ans) cout << "Yes" << endl;
