		swap(g[f[x]],g[f[i]]);
		down(i);
	}
}
void up(int x){
	if (x==1)return;
	if (flag[f[x]][0]*flag[f[x]][1]<flag[f[x/2]][0]*flag[f[x/2]][1]){
		swap(f[x],f[x/2]);
		swap(g[f[x]],g[f[x/2]]);
