        if (colors[t] == 'A') a_cnts[s]++;
        else b_cnts[s]++;
    }

    vector<bool> removed(N, false);

    stack<int> st;
    for (int i = 0; i < N; i++) {
        if (a_cnts[i] == 0 || b_cnts[i] == 0) st.push(i);
    }

    while (!st.empty()) {
        int node = st.top(); st.pop();
        removed[node] = true;
        for (int next : table[node]) {
            if (removed[next]) continue;

            if (colors[node] == 'A') a_cnts[next]--;
            else b_cnts[next]--;

            if (a_cnts[next] <= 0 || b_cnts[next] <= 0) st.push(next);
        }
    }

    int cnt = 0;
    for (int i = 0; i < N; i++) if (removed[i]) cnt++;
    if (cnt == N) {
        cout << "No" << endl;
    } else {
        cout << "Yes" << endl;
    }

    return 0;
}

