	bool pos = false;
	//Recorremos todas las posiciones de un lado
	for (auto it = A.begin(); it != A.end(); ++it) {
		//Para cada posición buscamos todas aquellas del mismo lado con las que estén conectadas
		for (auto it2 = it->second.first.begin(); it2 != it->second.first.end(); ++it2) {
			for (auto it3 = it->second.second.begin(); it3 != it->second.second.end(); ++it3) {
				for (auto it4 = B[*it3].second.begin(); it4 != B[*it3].second.end(); ++it4) {

