void DFS(int x, int y) {
    inst[x][y] = 1;
    vis[x][y] = 1;
    for(int i = 0; i < V[x].size(); i++)
        if(ch[V[x][i]] != ch[x] ^ y) {
            if(inst[V[x][i]][!y]) {
                puts("Yes");
                exit(0);
            } else if(!vis[V[x][i]][!y]) DFS(V[x][i], !y);
        }
    inst[x][y] = 0;
}

