void bfs(int x){
    if(flag[x])return;
    if(a[x]>0&&b[x]>0)return;
    flag[x] = 1;
    for(auto y:v[x]){
        if(flag[y])continue;
        if(p[x]=='A'){
            a[y]--;
            bfs(y);
        }
        if(p[x]=='B'){
            b[y]--;
            bfs(y);
        }
    }
}

