    rep(i,m){
        int s,t;
        cin >> s >> t;
        s--;
        t--;
        if(s>t)swap(s,t);
        if(st.count(MP(s,t))==1){
            continue;
        }else{
            if(s==t){
                v[s].PB(s);
                if(p[s]=='A'){
                    a[s]++;
                }else{
                    b[s]++;
                }
            }else{
                v[s].PB(t);
                v[t].PB(s);
                if(p[s]=='A'){
                    a[t]++;
                }else{
                    b[t]++;
                }
                if(p[t]=='A'){
                    a[s]++;
                }else{
