void del(int v){
    deleted[v] = true;
    for(int i = 0; i < G[v].size(); i++){
        if(S[v] == 'A'){
            cnta[G[v][i]]--;
            if(cnta[G[v][i]] == 0 && !deleted[G[v][i]]) del(G[v][i]);
        }else{
            cntb[G[v][i]]--;
            if(cntb[G[v][i]] == 0 && !deleted[G[v][i]]) del(G[v][i]);
        }
    }
}

