void dfs(int v,int p){
	used[v]=true;
	if(gr[v])cr++;
	for(int i=0;i<G[v].size();i++){
		int nv=G[v][i];
		if(!gr[nv])continue;
		if(nv!=p && used[nv]){
			flag=true;
		}
		if(nv!=p && !used[nv]){
			dfs(nv,v);
		}
	}
}

int main(void){
	scanf("%d%d",&n,&m);
	cin >> str;
	for(int i=0;i<m;i++){
		scanf("%d%d",&a[i],&b[i]);
		a[i]--;
		b[i]--;
		G[a[i]].push_back(b[i]);
		G[b[i]].push_back(a[i]);
	}
	flag=true;
	queue<int> que;
	for(int i=0;i<n;i++){
		int cnt=0;
		for(int j=0;j<G[i].size();j++){
			int v=G[i][j];
			if(str[v]=='A')cnta[i]++;
			if(str[v]=='B')cntb[i]++;
		}
		if(cnta[i]==0 || cntb[i]==0){
			que.push(i);
			queueed[i]=true;
		}
	}
	while(que.size()){
		int v=que.front();
		que.pop();
		for(int i=0;i<G[v].size();i++){
