	for (int i = 1; i <= n; ++ i)
		if (cnt[i][0] == 0 || cnt[i][1] == 0){
			del[i] = true;
			++ del_cnt;
			q.push(i);
		}
	while (! q.empty()){
		int u = q.front();
		q.pop();
		for (int i = 0; i < G[u].size(); ++ i){
