            v[a].push_back(b);
        }
        else checked[2*i]=-1;

        if(edge2idx[e(b,a)]==0){
            edge2idx[e(b,a)]=2*i+1;
            v[b].push_back(a);
        }
        else checked[2*i+1]=-1;
