        if (nod1 != nod2) deg[nod2][mode[nod1]]++;
    }

    stack<int> pile;
    for (int iNod = 1; iNod <= nbNoeuds; ++iNod) {
        if (deg[iNod][0] == 0 || deg[iNod][1] == 0) {
            pile.push(iNod);
            vu[iNod] = true;
        }
    }
    int fini = 0;
    while (! pile.empty()) {
        int nod = pile.top();
        pile.pop();
        ++fini;
        for (int vo : adj[nod]) {
            if ((--deg[vo][mode[nod]]) == 0 && vu[vo] == false) {
                vu[vo] = true;
                pile.push(vo);
            }
        }
    }

    if (fini != nbNoeuds) cout << "Yes\n";
    else cout << "No\n";
}

