template<class T = int> using VV = V< V<T> >;
template<class T> void assign(V<T>& v, int n, const T& a = T()) { v.assign(n, a); }
template<class T, class... U> void assign(V<T>& v, int n, const U&... u) { v.resize(n); for (auto&& i : v) assign(i, u...); }

bool rec(int v, V<>& vis, const string& s, const VV<>& g, bool r = false) {
  // if (!r) vis[v] = 0;
  vis[v] = 1;
  bool fa = false, fb = false;
  for (int i : g[v]) if (vis[i] == 1) {
    if (s[i] == 'A') fa = true;
    else fb = true;
  }
  if (!fa) for (int i : g[v]) if (vis[i] == -1 and s[i] == 'A') {
    if (rec(i, vis, s, g)) {
      fa = true;
      break;
    } else vis[i] = 0;
  }
  if (!fb) for (int i : g[v]) if (vis[i] == -1 and s[i] == 'B') {
    if (rec(i, vis, s, g)) {
      fb = true;
      break;
    } else vis[i] = 0;
  }
  return vis[v] = fa and fb;
}

int main() {
  cin.tie(NULL); ios::sync_with_stdio(false);
  int n, m; cin >> n >> m;
  string s; cin >> s;
  VV<> g(n);
  for (int i = 0; i < m; i++) {
    int a, b; cin >> a >> b, a--, b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  V<> vis(n, -1);
  for (int i = 0; i < n; i++) if (vis[i] == -1) {
    vis[i] = 1;
    if (rec(i, vis, s, g, true)) return cout << "Yes" << '\n', 0;
  }
  cout << "No" << '\n';
}

