		a--;
		b--;
		g[a].push_back(Edge(a, b, 1));
		if (a != b)
			g[b].push_back(Edge(b, a, 1));
	}
	queue<ll> dead;
	vector<ll> isdead(N);
	ll num = N;
	for (int i = 0;i < N;i++) {
		for (int j = 0;j < g[i].size();j++) {
			ll to = g[i][j].dst;
			if (s[to] == 'A')
				alive[i]++;
			else
				blive[i]++;
		}
		if (alive[i] == 0 || blive[i] == 0) {
			dead.push(i);
			isdead[i] = true;
			num--;
		}
	}
