			cnt[z] = 0;
		}
	}

	for (int i = 0; i < sz(g[x]); i++) {
		int y = g[x][i];
		if (col[y] == col[x] ^ 1) {
			for (int j = 0; j < sz(g[y]); j++) {
				int	z = g[y][j];
				if (x == z) continue;
				if (col[y] == col[z]) {
					cnt[z] = 1;
				}
			}
		}
	}

	for (int i = 0; i < sz(g[x]); i++) {
		int y = g[x][i];
		if (col[y] == col[x]) {
			for (int j = 0; j < sz(g[y]); j++) {
				int z = g[y][j];
				if (x == z) continue;
				if (col[y] == col[z] ^ 1) {
					if (cnt[z] == 1)
						return true;
				}
			}
		}
	}


	for (int i = 0; i < sz(g[x]); i++) {
		int y = g[x][i];
		for (int j = 0; j < sz(g[y]); j++) {
			int	z = g[y][j];
			if (x == z) continue;
			cnt[z] = 0;
		}
	}

	bool res = false;
	for (int i = 0; i < sz(g[x]); i++) {
		int y = g[x][i];
		if (!used[y]) {
			res |= check4(y);
			if (res) return res;
		}
	}
	return res;
}


bool check3(int x) {
	used[x] = 1;

	for (int i = 0; i < sz(g[x]); ++i) {
		int y = g[x][i];
		cnt[y] = 1;
	}

	if (ok[x]) {
		for (int i = 0; i < sz(g[x]); i++) {
			int y = g[x][i];
			if (col[x] == col[y] ^ 1) {
				for (int j = 0; j < sz(g[y]); j++) {
					int z = g[y][j];
					if (x == z) continue;
					if (col[z] == col[y] && cnt[z]) {
						return true;
					}
				}
			}
		}
	}

	for (int i = 0; i < sz(g[x]); ++i) {
		int y = g[x][i];
		cnt[y] = 0;
	}

	bool res = false;

	for (int i = 0; i < sz(g[x]); i++) {
		int y = g[x][i];
		if (!used[y]) {
			res |= check3(y);
			if (res) return res;
		}
	}
	return res;
}


bool check2(int x) {
	used[x] = 1;
	for (int i = 0; i < sz(g[x]); i++) {
		int y = g[x][i];
		if (ok[x] && ok[y] && col[x] == col[y] ^ 1) 
