int vis[4 * 2 * 100005], A[4 * 2 * 100005];
vi G[4 * 2 * 100005];
void dfs(int u, int p) {
    A[u]++;
    if (vis[u]++) {
        cout << "Yes" << endl;
        exit(0);
    }
    each(v, G[u])if (v != p) {
