vector <int> vec[SIZE];
char str[SIZE];
int da[SIZE],db[SIZE];
bool use[SIZE];

int main()
{
	int n,m;
	scanf("%d %d",&n,&m);
	scanf("%s",&str);
	for(int i=0;i<m;i++)
	{
		int a,b;
		scanf("%d %d",&a,&b);a--,b--;
		vec[a].push_back(b);
		vec[b].push_back(a);
		if(str[a]=='A') da[b]++;
		else db[b]++;
		if(str[b]=='B') db[a]++;
		else da[a]++;
	}
	queue <int> que;
	for(int i=0;i<n;i++)
	{
		if(da[i]==0||db[i]==0)
		{
			que.push(i);
			use[i]=true;
		}
	}
	int cnt=0;
	while(!que.empty())
	{
		int v=que.front();que.pop();
		cnt++;
		for(int i=0;i<vec[v].size();i++)
		{
			int to=vec[v][i];
			if(!use[to])
			{
				if(str[v]=='A') da[to]--;
				else db[to]--;
				if(da[to]==0||db[to]==0)
				{
					use[to]=true;
					que.push(to);
				}
			}
		}
	}
	if(cnt<n) puts("Yes");
	else puts("No");
	return 0;
}

