    vector<int> v[200005];
    int na[200005] {0}, nb[200005] {0};
    for(int i = 0; i < m; i++){
        cin >> a[i] >> b[i];
        a[i]--;
        b[i]--;
        v[a[i]].push_back(b[i]);
