int a[200005];
vector<int> g[200005];
int cnt[200005][2];
queue<int> q;
bool have[200005];

int main() {
    scanf("%d%d", &n, &m);
    scanf("%s", s);
    forn(i, n) {
        a[i] = (s[i] == 'A' ? 0 : 1);
    }
    forn(i, m) {
        int from, to;
        scanf("%d%d", &from, &to);
        --from, --to;
        g[from].pb(to);
        g[to].pb(from);
        ++cnt[from][a[to]];
        ++cnt[to][a[from]];
    }
    forn(i, n) have[i] = true;
    forn(i, n) if (cnt[i][0] == 0 || cnt[i][1] == 0) {
        have[i] = false;
        q.push(i);
    }
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int to : g[v]) {
            if (--cnt[v][a[to]] == 0 && have[v]) {
                have[v] = false;
                q.push(v);
            }
            if (--cnt[to][a[v]] == 0 && have[to]) {
                have[to] = false;
                q.push(to);
            }
        }
    }
    string ans = "No";
    forn(i, n) if (have[i]) {
        ans = "Yes";
        break;
    }
    cout << ans << endl;
    return 0;
}

