using namespace std;
const string s = "AABB";

bool dfs(const vector<vector<int>> &G, const string &S, vector<int> &V, vector<bool> &visited, int v, int t, int u){
  bool ret = false;
  V[v] |= (1<<t);
  visited[v] = true;
  t = (t+1)%4;
  for(size_t i = 0; i < G[v].size(); ++i){
    int v_ = G[v][i];
    if(S[v_] != s[t]) continue;
    if(v_ == u and not t) return true;
    //if(not t and V[v_]%2) return true;
    if((V[v_]>>t)&1) return true;
    //if((V[v_]>>t)&1) continue;
    ret |= dfs(G,S,V,visited,v_,t,u);
  }
  V[v] = 0;
  return ret;
}

int main(){
  int N, M;
  cin >> N >> M;
  string S;
  cin >> S;
  vector<vector<int>> G(N);
  for(int i = 0; i < M; ++i){
    int a, b;
    cin >> a >> b;
    --a,--b;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  assert(N <= 1000);
  bool f = false;
  vector<bool> visited(N,false);
  vector<int> V(N,0);
  for(int i = 0; i < N; ++i){
    if(S[i] != 'A') continue;
    if(visited[i]) continue;
    f |= dfs(G,S,V,visited,i,0,i);
    if(f){
      cerr << i << endl;
      break;
    }
  }
  if(f) cout << "Yes" << endl;
  else cout << "No" << endl;
  return 0;
}

