using namespace std;
const int N=2e5+10;
bool f[N],self[N];
bool dp[N][2];
set<int> went,graph[N];
set<pair<int,bool>>in;
bitset<N>used;
bool dfs(int now,bool need){
    if(dp[now][need])return false;
    bool ans=false;
    in.insert({now,need});
    if(need==f[now]&&self[now]){
        for(int i:graph[now])if(f[i]!=need){
            if(in.find({i,!need})!=in.end())return true;
            else if(dfs(i,!need))return true;
        }
    }
    if(need==f[now]){
        for(int i:graph[now])if(f[i]==need){
            if(in.find({i,!need})!=in.end())return true;
            else if(dfs(i,!need))return true;
        }
    }
    else{
        for(int i:graph[now])if(f[i]==need){
            if(in.find({i,need})!=in.end())return true;
            else if(dfs(i,need))return true;
        }
    }
    in.erase({now,need});
    return dp[now][need]=ans;
}
int main(){
    int n,m,l,r;
    string s;
    cin>>n>>m>>s;
    for(int i=0;i<n;i++)f[i+1]=(s[i]=='A');
    for(int i=1;i<=n;i++)dp[i][1]=dp[i][0]=self[i]=false;
    used.reset();
    while(m--){
        scanf("%d%d",&l,&r);
        if(l==r)self[l]=true;
        else{
            graph[l].insert(r);
            graph[r].insert(l);
        }
    }
    for(int i=1;i<=n;i++)if(dp[i][f[i]]==0){
        in.clear();
        if(dfs(i,f[i])){
            printf("Yes\n");
            return 0;
        }
    }
    printf("No\n");
}

