class topological {
public:
    bool uniq = true, can = true;
    int maxlen = 0;
    int n;
    queue<int> cnt;
    vector<int> in;
    vector<int> len;
    vector<vector<int>> loute;
    vector<int> res;

    topological (vector<vector<int>> lt) {
        loute = lt;
        n = loute.size();
        in = vector<int>(n);
        len = vector<int>(n);
        for (auto&& from : loute) {
            for (auto&& to : from) {
                in[to]++;
            }
        }
        for (int i = 0; i < n; i++) {
            if (!in[i]) {
                cnt.push(i);
            }
        }
    }

    topological(int n){loute = vector<vector<int>>(n);};

    void add(int u, int v) {
        loute[u].push_back(v);
    }

    void build() {
        n = loute.size();
        in = vector<int>(n);
        len = vector<int>(n);
        for (auto&& from : loute) {
            for (auto&& to : from) {
                in[to]++;
            }
        }
        for (int i = 0; i < n; i++) {
            if (!in[i]) {
                cnt.push(i);
            }
        }
    }

    void run() {
        while (!cnt.empty()) {
            int nxt = cnt.front(); cnt.pop();
            if (cnt.size()) uniq = false;
            res.pb(nxt);
            for (auto&& to : loute[nxt]) {
                --in[to];
                if (!in[to]) cnt.push(to);
                len[to] = max(len[to], len[nxt] + 1);
            }
        }
        if (res.size() != n) can = false;
        for (int i = 0; i < n; i++) {
            maxlen = max(maxlen, len[i]);
        }
    }
};

