int cnt[2][200005];
int size;
bool gone[200005];

void remove(int v){
  std::queue<int> frontier;
  frontier.push(v);
  while(!frontier.empty()){
    int v=frontier.front();
    frontier.pop();
    if(gone[v]) continue;
    //printf("%d checked: %d,%d\n",v+1,cnt[0][v],cnt[1][v]);
    if(cnt[0][v]&&cnt[1][v]) continue;
    for(int adj:edges[v]){
      edges[adj].erase(v);
      if(--cnt[str[v]-'A'][adj]==0){
	frontier.push(adj);
      }
    }
    edges[v].clear();
    size--;
    //printf("%d removed\n",v+1);
    gone[v]=true;
  }
}

