    edges[U].insert(V);
    edges[V].insert(U);
  }
  for(int i=0;i<N;i++){
    for(int adj:edges[i]){
      cnt[str[i]-'A'][adj]++;
    }
  }
  size=N;
  for(int i=0;i<N;i++){
    remove(i);
  }
  if(size>0){
    printf("Yes\n");
  }else{
    printf("No\n");
  }
  return 0;
}

