bool Solve() {
	int n, m; 
	string s;
	cin >> n >> m >> s;

	vvi edges(n);
	vi color(n);
	for(int i = 0; i < n; i++) color[i] = s[i] == 'A' ? 0 : 1;
	for(int _ = 0; _ < m; _++) {
		int x, y; cin >> x >> y;
		x--, y--;
		edges[x].push_back(y);
		if (x != y)
			edges[y].push_back(x);
	}

	int color_seq[4] = {0, 0, 1, 1};
	vi v(n, 0);

	bool ans = false;
	for(int i = 0; i < n && !ans; i++) {
		if(color[i] != 0 || (v[i] & 1)) continue;

		queue<pii> q;
		q.push({i, 0});
		v[i] |= 1;

		while(!q.empty()) {
			auto fr = q.front(); q.pop();
			int j = fr.first, c = fr.second;
			int nc = (c + 1) % 4;
			for(auto n : edges[j]) {
				if(c == 3 && color[n] == 0 && (v[n] & 1)) {
					return true;
				}

				if(color[n] == color_seq[nc] && !(v[n] & (1 << nc))) {
					q.push({n, nc});
					v[n] |= 1 << nc;
				}
			}
		}
	}

	return false;
}

