void dfs(Int pos, Int cnt, Int num,char target){
  ans |= (cnt == 0 && A[pos] == target && used[pos][cnt] == num);
  if(used[pos][cnt] != 0) return;
  if(ans) return;

  used[pos][cnt]  = num;
