bool rec(int v, V<>& vis, const string& s, const VV<>& g) {
  vis[v] = 1;
  bool fa = false, fb = false;
  for (int i : g[v]) if (vis[i] == 1) {
    if (s[i] == 'A') fa = true;
    else fb = true;
  }
  for (int i : g[v]) {
    if (!fa and s[i] == 'A' and vis[i] == -1) {
      if (rec(i, vis, s, g)) {
        fa = true;
        break;
      }
    }
    if (!fb and s[i] == 'B' and vis[i] == -1) {
      if (rec(i, vis, s, g)) {
        fb = true;
        break;
      }
    }    
  }
  return vis[v] = fa and fb;
}

int main() {
  cin.tie(NULL); ios::sync_with_stdio(false);
  int n, m; cin >> n >> m;
  string s; cin >> s;
  VV<> g(n);
  for (int i = 0; i < m; i++) {
    int a, b; cin >> a >> b, a--, b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  V<> vis(n, -1);
  for (int i = 0; i < n; i++) if (vis[i] == -1) {
    if (rec(i, vis, s, g)) return cout << "Yes" << '\n', 0;
  }
  cout << "No" << '\n';
}

