const int maxn=2000000;
struct edge{int to,next;}e[maxn];
int n,m,np,first[maxn],deg[maxn][2];
bool color[maxn],del[maxn];
char str[maxn];
void addedge(int u,int v){
	e[++np]=(edge){v,first[u]};
	first[u]=np;
}
void DFS(int i){
	del[i]=1;
	for(int p=first[i];p;p=e[p].next){
		int j=e[p].to;if(del[j])continue;
		if(--deg[j][color[i]]==0)DFS(j);
	}
}
int main(){
	scanf("%d%d%s",&n,&m,str+1);
	for(int i=1;i<=n;i++)color[i]=str[i]-'A';
	for(int i=1,u,v;i<=m;i++){
		scanf("%d%d",&u,&v);
		if(u==v)deg[u][color[u]]++;
		else{
			deg[u][color[v]]++;
			deg[v][color[u]]++;
			addedge(u,v);addedge(v,u);
		}
	}
	for(int i=1;i<=n;i++)
	if((!deg[i][0]||!deg[i][1])&&!del[i])DFS(i);
	bool can=0;
	for(int i=1;i<=n;i++)if(!del[i])can=1;
	printf("%s",can?"Yes":"No");
	return 0;
}

