	freopen("C.in", "r", stdin);
	freopen("C.out", "w", stdout);
#endif
	N = read(), M = read();
	scanf("%s", S + 1);
	for (int i = 1; i <= M; ++i)
	{
		int x = read(), y = read();
		add_edge (x, y);
		add_edge (y, x);
	}
	for (int i = 1; i <= N; ++i)
		if (!Viss[i])
		{
			ans += dfs(i);
			//			cout<<i<<" "<<ans<<endl;
		}
	if (ans) cout<<"Yes"<<endl;
	else cout<<"No"<<endl;
	return 0;
}

