/*
31536000のコメント解説欄
ここテンプレで用意してるから、A問題とかだとこの先空欄の危険あり
また、コンテスト後に https://31536000.hatenablog.com/ で解説していると思うので、良かったら読んでねー

大事なことは、要素が2個しかないということ
つまり、A→Aの閉路、B→Bの閉路、A→B……の閉路の3個が存在してそれが隣接してればおk
これは、次のどれかを内包しているに他ならない
1. [1]=A, [2]=Bとして[1]-[1], [2]-[2], [1]-[2]
2. [1]=A, [2]=A, [3]=Bとして[1]-[2], [1]-[3], [2]-[3], [3]-[3]
3. [1]=A, [2]=B, [3]=Bとして[1]-[2], [1]-[3], [2]-[3], [1]-[1]
4. [1]=A, [2]=A, [3]=B, [4]=Bとして[1]-[2], [2]-[3], [3]-[4], [4]-[1]

まず、A-AとB-Bのペアを作っておく O(N)
そして、1個のAを決め打つ O(N)
この時、A-BとなるBを1個取り出し(O(logN))、そのペアとなるB(O(logN))とペアとなるA(O(log N))が自身のペアと一致するならYes
そうでないならNo
*/

#include <bits/stdc++.h>

using namespace std;

const int MaxN = 2e5;

int n, m;

vector <int> v[MaxN];
string s;

bool deleted[MaxN];

set<pair<int, int> > S;

int cnt[2][MaxN];

void popV(int x)
{
    deleted[x] = true;

    for(int to : v[x])
        if(!deleted[to])
        {
            S.erase(make_pair(min(cnt[0][to], cnt[1][to]), to));
            if(s[x] == 'A')
                --cnt[0][to];
            else
                --cnt[1][to];
            S.insert(make_pair(min(cnt[0][to], cnt[1][to]), to));
        }
}

int main()
{
    ios_base :: sync_with_stdio(false);
    cin.tie(NULL);
//    freopen("input.txt", "r", stdin);

    cin >> n >> m;
    cin >> s;

    for(int i = 0; i < m; ++i)
    {
        int x, y;
        cin >> x >> y;
        --x, --y;

        v[x].push_back(y);
        v[y].push_back(x);

        if(s[x] == 'A')
            ++cnt[0][y];
        else
            ++cnt[1][y];

        if(s[y] == 'A')
            ++cnt[0][x];
        else
            ++cnt[1][y];
    }

    for(int i = 0; i < n; ++i)
        S.insert(make_pair(min(cnt[0][i], cnt[1][i]), i));

    while(!S.empty() && (*S.begin()).first == 0)
    {
        int x = (*S.begin()).second;
        S.erase(S.begin());

        popV(x);
    }

    if(S.empty())
        cout << "No\n";
    else
        cout << "Yes\n";

    return 0;
}

