  }

  queue<int> Q;

  int cnt = 0;
  vector<bool> marked(N,false); 
  //一度ダメになったらもう一度判定する必要はない

  for(int i = 0; i < N; i++){ 
    if( !(A[i] > 0 && B[i] > 0) ){
      Q.push(i);  marked[i] = true;cnt++;
    }
  }
  //初めから条件を満たさないものについてはドシドシqueueに入れる

  while(!Q.empty()){ 

    int p = Q.front(); Q.pop();

    for(auto q : to[p] ){ 
      if( q == p || marked[q] ){ continue;} //自分自身に伝搬させる必要はない　元からだめ

