	bool used = false;
	vector<int> nexts, sames, others;
	unordered_set<int> sameSet;
};

Node nodes[200010];

bool dfs(int now, unordered_set<int> &visited) {
	if (visited.count(now)) return true;
	visited.insert(now);
	for (int same : nodes[now].sames) {
		for (int other : nodes[same].others) {
			if (nodes[other].used) continue;
			if (dfs(other, visited)) return true;
		}
	}
	visited.erase(now);
	nodes[now].used = true;
	return false;
}

