template <typename Tp>
class segment_tree{
    Tp *tree;
    const size_t len;
    const Tp e;
    Tp (*f)(Tp, Tp);
public:
    segment_tree(size_t n, const Tp &id, Tp (*fn)(Tp, Tp), const Tp *values=nullptr): len(n), e(id), f(fn){
        tree = new Tp[n<<1];
        for(size_t i=0; i<n; ++i) tree[n+i] = values ? values[i] : id;
        for(size_t i=n-1; i>0; --i) tree[i] = fn(tree[i<<1 | 0], tree[i<<1 | 1]);
    }
    void set(size_t pos, const Tp &val){
        tree[pos += len] = val;
        for(pos>>=1; pos>0; pos>>=1) tree[pos] = f(tree[pos<<1 | 0], tree[pos<<1 | 1]);
    }
    void add(size_t pos, const int &val){
        auto v = tree[len+pos];
        v.first += val;
        set(pos, v);
    }
    Tp get(size_t left, size_t right){
        left += len; right += len;
        Tp lval = e, rval = e;
        while(left < right){
            if(left  & 1) lval = f(lval, tree[left ++]);
            if(right & 1) rval = f(tree[--right], rval);
            left >>= 1; right >>= 1;
        }
        return f(lval, rval);
    }
};

