const int MAX_M = 2 * (int) (1e5);
ll N, M, ab[MAX_M][MAX_M];
bool used[MAX_M][MAX_M];
string s;

bool go(int i) {
    bool has_same = false;
    bool has_diff = false;
    REP(j, N) {
        if (ab[i][j] != 1)continue;
        if (!has_same) {
            has_same = s[i] == s[j];
            if (used[i][j]) return true;
            used[i][j] = used[j][i] = true;
        }
        if (!has_diff) {
            has_diff = s[i] != s[j];
            if (used[i][j]) return true;
            used[i][j] = used[j][i] = true;
        }
        if (has_same && has_diff) {
            return go(j);
        }
    }
    return has_same && has_diff;
}

void solve() {
    REP(i, N) {
        if (go(i)) {
            cout << "Yes" << endl;
            return;
        }
    }
    cout << "No" << endl;
}

int main() {
    cin >> N >> M >> s;
    fill(used, used + N, false);
    fill(ab, ab + M, 0);
    int a, b;
    REP(i, M) {
        cin >> a >> b;
        ab[a][b] = 1;
        ab[b][a] = 1;
    }
    solve();
    return 0;
}

