using namespace std;
const int N=2e5+10;
int rd()
{
    int x=0,w=1;char ch=0;
    while(ch<'0'||ch>'9'){if(ch=='-') w=-1;ch=getchar();}
    while(ch>='0'&&ch<='9'){x=x*10+(ch^48);ch=getchar();}
    return x*w;
}
int to[N<<1],nt[N<<1],hd[N],tot=1;
void adde(int x,int y)
{
    ++tot,to[tot]=y,nt[tot]=hd[x],hd[x]=tot;
    ++tot,to[tot]=x,nt[tot]=hd[y],hd[y]=tot;
}
char cc[N];
int n,m,ff[N],sz[N],an[N];
int findf(int x){return ff[x]==x?x:ff[x]=findf(ff[x]);}
bool cr[N],vs[N],ist[N];
bool dd(int x)
{
    vs[x]=1;
    if(!cr[x]&&sz[findf(x)]<=1) return 0;
    if(ist[x]) return 1;
    if(~an[x]) return an[x];
    ist[x]=1;
    bool a1=0;
    for(int i=hd[x];!a1&&i;i=nt[i])
    {
	int y=to[i];
	if(cc[x]==cc[y]) continue;
	a1|=dd(y);
    }
    if(!a1) {ist[x]=0;return an[x]=0;}
    if(cr[x]) {ist[x]=0;return an[x]=1;}
    for(int i=hd[x];i;i=nt[i])
    {
	int y=to[i];
	if(cc[x]!=cc[y]) continue;
	for(int j=hd[y];j;j=nt[j])
	{
	    int z=to[j];
	    if(cc[y]==cc[z]) continue;
	    if(dd(z)){ist[x]=0;return an[x]=1;}
	}
    }
    ist[x]=0;return an[x]=0;

}

int main()
{
    n=rd(),m=rd();
    scanf("%s",cc+1);
    for(int i=1;i<=n;++i) ff[i]=i,sz[i]=1,an[i]=-1;
    for(int i=1;i<=m;++i)
    {
	int x=rd(),y=rd();
	if(x==y) cr[x]=1;
	else
	{
	    adde(x,y);
	    if(cc[x]==cc[y]&&findf(x)!=findf(y))
		sz[findf(x)]+=sz[findf(y)],ff[findf(y)]=findf(x);
	}
    }
    for(int i=1;i<=n;++i)
	if(!vs[i]&&dd(i)){puts("Yes");return 0;}
    puts("No");
    return 0;
}

