		if (s[now] == 'A' &&
			joint[to].first.find(now) != joint[to].first.end()) {
			joint[to].first.erase(now);
			if (goods[to] && joint[to].first.empty()) {
				goods[to] = false;
				apply(joint, goods, to);
			}
		}
		if (s[now] == 'B' &&
			joint[to].second.find(now) != joint[to].second.end()) {
			joint[to].second.erase(now);
			if (goods[to] && joint[to].second.empty()) {
				goods[to] = false;
				apply(joint, goods, to);
			}
		}
	}
}


//計算
void calc()
{
	auto joint = good_set();
	auto goods = make_goods(joint);
	REP(i, N) {
		if (!goods[i]) {
			apply(joint, goods, i);
		}
	}
	for (auto f : goods)finalResult |= f;
}


//出力
void output()
{
	cout << (finalResult ? "Yes" : "No") << endl;
}


