bool both(int curr) {
    bool a = false;
    bool b = false;
    for(auto next : adj[curr]) {
        if(valid[next]) {
            if(s[next] == 'A') a = true;
            if(s[next] == 'B') b = true;
        }
    }

    return a && b;
}

int main() {
    //file();
    //fast();

    int n, m;
    cin >> n >> m;
    cin >> s;

    selfloop.resize(n, false);
    adj.resize(n);
    valid.resize(n, true);

    for(int i = 0; i < m; i++) {
        int n1, n2;
        cin >> n1 >> n2;
        n1--; n2--;

        edges.pb({n1,n2});
        if(n1 == n2) selfloop[n1] == true;

        adj[n1].pb(n2);
        adj[n2].pb(n1);
    }

    queue<int> removal;
    for(int i = 0; i < n; i++) {
        if(!both(i)) {
            removal.push(i);
        }
    }

    int removed = 0;
    while(!removal.empty()) {
        int curr = removal.front();
        removal.pop();

	if(!valid[curr]) continue;
	valid[curr] = false;
        removed++;

        for(auto next : adj[curr]) {
            if(!valid[next]) continue;

            if(!both(next)) {
                removal.push(next);
            }
        }
    }

    if(removed < n) {
        cout << "Yes" << endl;
    }
    else {
        cout << "No" << endl;
    }

