    int N, M;
    string s;
    cin >> N >> M >> s;
    vector<int> num(N);
    for(int i = 0; i < N; ++i)  num[i] = s[i] - 'A';
    vector<vector<int>> graph(N);
    for(int i = 0; i < M; ++i){
        int a, b;
        cin >> a >> b;
        --a, --b;
        graph[a].emplace_back(b);
        if(a != b)  graph[b].emplace_back(a);
    }

    vector<bool> used(N);
    auto dfs = [&](auto&& self, int cur, int prev_num = -1) -> bool {
        used[cur] = true;
        if(prev_num == -1){
            vector<bool> ok(2);
            for(int nxt : graph[cur]){
                if(nxt == cur){
                    ok[num[nxt]] = true;
                    if(ok[0] && ok[1])  return true;
                    continue;
                }
                if(used[nxt] || ok[num[nxt]])   continue;
                if(self(self, nxt, num[cur]))   ok[num[nxt]] = true;
                if(ok[0] && ok[1])  return true;
            }
        }
        else{
            for(int nxt : graph[cur]){
                if(used[nxt] || nxt == cur){
                    if(num[nxt] != prev_num)    return true; 
                    continue;
                }
                if(self(self, nxt, num[cur])) return true;
            }
        }
        return false;
    };

    for(int i = 0; i < N; ++i){
        if(used[i]) continue;
        if(dfs(dfs, i)){
            cout << "Yes\n";
            return 0;
        }
    }
    cout << "No\n";
}

