    for(int i = 0; i < n; i++) {
        if(!both(i)) {
            removal.push(i);
        }
    }

    int removed = 0;
    while(!removal.empty()) {
        removed++;

        int curr = removal.front();
        removal.pop();

        valid[curr] = false;

        for(auto next : adj[curr]) {
            if(!valid[next]) continue;

            if(!both(next)) {
                removal.push(next);
            }
        }
    }

    if(removed < n) works = true;

    if(works) {
        cout << "Yes" << endl;
    }
    else {
        cout << "No" << endl;
    }

    return 0;
}

