inline void prune(li x) {
    vector<li> remove_list;
    rep(i, 2) {
        foreach (it, edge[x][i]) {
            li next = *it;
            if (next == x)continue;
            edge[next][(isa[x] ? 0 : 1)].erase(x);
            remove_list.pb(next);
