    if(a == b) {
      g[a * 2].push_back(a * 2 + 1);
    }
    else if(S[a] == S[b]) {
      g[a * 2].push_back(b * 2 + 1);
      g[b * 2].push_back(a * 2 + 1);
    }
    else {
      g[a * 2 + 1].push_back(b * 2);
      g[b * 2 + 1].push_back(a * 2);
    }
  }
  auto res = strongly_connected_components(g);
  if(2 * N - 1 == *std::max_element(all(res))) {
    cout << "No" << endl;
  }
  else {
    cout << "Yes" << endl;
  }
}

