constexpr int D = 6;
bool dp[200005][D];

signed main() {
	INIT;

	VAR(int, n, m);
	VAR(std::string, s);
	VEC_ROW(int, m, a, b);
	std::vector<bool> d(n);
	REP(i, n) d[i] = s[i] == 'A';

	std::vector<std::vector<int>> g(n);
	REP(i, m) {
		--a[i]; --b[i];
		g[a[i]].emplace_back(b[i]);
		g[b[i]].emplace_back(a[i]);
	}

	auto check = [&](int c) {
		FILL(dp, false);
		REP(i, n) {
			if (d[i] == !!(c & 1)) dp[i][0] = true;
		}
		FOR(k, 1, D) {
			REP(i, n) {
				if (d[i] == !!(c >> k & 1)) {
					for (auto& to : g[i]) {
						if (dp[to][k - 1]) {
							dp[i][k] = true;
							if (k == D - 1) return true;
							break;
						}
					}
				}
			}
		}
		return false;
	};

	REP(i, 1 << D) {
		if (!check(i)) {
			OUT("No")BR;
			return 0;
		}
	}
	OUT("Yes")BR;
	return 0;
}

