int n, m; 
string have; 
vector<int> gr[maxn]; 
set<pii> kek; 

int A[maxn], B[maxn]; 

int use[maxn];
vector<int> path;

void dfs(int u) {
    use[u] = 1; 
    path.pb(u); 
    for (auto v : gr[u]) {
        if (!use[v]) dfs(v); 
    }
}

int use1[maxn]; 

bool bfs() {
    deque<int> q;   
    int d = 0; 
    for (auto v : path) {
        if (A[v] == 0 || B[v] == 0) { 
            q.pb(v);
            use1[v] = 1;                
            ++d;
        }
    }
    while (q.size()) {
        int v = q.front(); 
        q.pop_front();
        for (auto u : gr[v]) {
            if (have[v] == 'A') A[u]--; 
            else B[u]--; 

            if (!use1[u] && (B[u] == 0 || A[u] == 0)) {
                q.pb(u); 
                use1[u] = 1; 
                ++d;
            }
        }
    }
    if (d != path.size()) return true; 
    return false; 
}

void solve() {
    cin >> n >> m >> have; 
    for (int i = 0; i < m; ++i) {
        int a, b; cin >> a >> b;        
        --a, --b;
        if (a > b) swap(a, b); 
        if (kek.count(mp(a, b))) continue;
        kek.insert({a, b});
        gr[a].pb(b); 
        gr[b].pb(a); 
        if (have[b] == 'A') A[a]++;
        else B[a]++;

        if (have[a] == 'A') A[b]++; 
        else B[b]++; 
    }

    for (int i = 0; i < n; ++i) {
        if (!use[i]) {
            path.clear(); 
            dfs(i); 

            if (bfs()) {
                cout << "Yes";
                return; 
            } 
        }
    }        
    cout << "No";  
}                               

