using namespace output;

int N, M;
vector<vi> graph;
string S;
vector<bool> connectedToSelf;

bool backtrack(int cur, vi as, vi bs) {
	if ((S[cur] == 'A' && as.size() == 2) || (S[cur] == 'B' && bs.size() == 2)) {
		if (as.size() != 2 || bs.size() != 2) return false;

		bool aConnected = find(graph[as[0]].begin(), graph[as[0]].end(), as[1]) != graph[as[0]].end();
		bool bConnected = find(graph[bs[0]].begin(), graph[bs[0]].end(), bs[1]) != graph[bs[0]].end();

		if (!bConnected && aConnected && connectedToSelf[bs[0]] && connectedToSelf[bs[1]]) return true;
		if (!aConnected && bConnected && connectedToSelf[as[0]] && connectedToSelf[as[1]]) return true;

		if (!bConnected || !aConnected) return false;

		// connect opposites
		for (int a : as) {
			bool found = false;
			for (int b : bs) {
				found |= find(graph[a].begin(), graph[a].end(), b) != graph[a].end();
			}
			if (found == false) return false;			
		}
		for (int a : bs) {
			bool found = false;
			for (int b : as) {
				found |= find(graph[a].begin(), graph[a].end(), b) != graph[a].end();
			}
			if (found == false) return false;			
		}
		return true;
	}

	bool ans = false;

	if (S[cur] == 'A') {
		as.push_back(cur);
		for (int n : graph[cur]) ans |= backtrack(n, as, bs);

		if (connectedToSelf[cur] && (as.size() == 0)) {
			as.push_back(cur);
			for (int n : graph[cur]) ans |= backtrack(n, as, bs);
		}

	}

	if (S[cur] == 'B') {
		bs.push_back(cur);
		for (int n : graph[cur]) ans |= backtrack(n, as, bs);

		if (connectedToSelf[cur] && (bs.size() == 0)) {
			bs.push_back(cur);
			for (int n : graph[cur]) ans |= backtrack(n, as, bs);
		}

	}

	return ans;
}

int main() {
    ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> N >> M;
	cin >> S;
	graph.resize(N);
	connectedToSelf.resize(N);
	F0R(i, M) {
