string S;

bool backtrack(int cur, vi as, vi bs) {
	if ((S[cur] == 'A' && as.size() == 2) || (S[cur] == 'B' && bs.size() == 2)) {
		if (as.size() != 2 || bs.size() != 2) return false;

		// each a connected to each other 
		if (find(graph[as[0]].begin(), graph[as[0]].end(), as[1]) == graph[as[0]].end()) return false;
		if (find(graph[bs[0]].begin(), graph[bs[0]].end(), bs[1]) == graph[bs[0]].end()) return false;



		// connect opposites
		for (int a : as) {
			bool found = false;
			for (int b : bs) {
				found |= find(graph[a].begin(), graph[a].end(), b) != graph[a].end();
			}
			if (found == false) return false;			
		}
		for (int a : bs) {
			bool found = false;
			for (int b : as) {
				found |= find(graph[a].begin(), graph[a].end(), b) != graph[a].end();
			}
			if (found == false) return false;			
		}
		return true;
	}

	bool ans = false;

	if (S[cur] == 'A') {
		if ((find(graph[cur].begin(), graph[cur].end(), cur) != graph[cur].end()) && (as.size() == 0)) {
			as.push_back(cur);
		}
		as.push_back(cur);
		for (int n : graph[cur]) ans |= backtrack(n, as, bs);
	}

	if (S[cur] == 'B') {
		if ((find(graph[cur].begin(), graph[cur].end(), cur) != graph[cur].end()) && (bs.size() == 0)) {
			bs.push_back(cur);
		}
		bs.push_back(cur);
		for (int n : graph[cur]) ans |= backtrack(n, as, bs);
	}

	return ans;
}

