struct Node {
    std::vector<int> edge;
    bool is_searched;
};

const int MAX_N = 200050;
std::string s_in;
char s[MAX_N];
int N, M;
int a[MAX_N], b[MAX_N];

Node graph[MAX_N];
std::unordered_set<int> us;

bool can_loop(int i, int from) {
    if (from == -1 || s[i] != s[from]) {
        if (us.find(i) != us.end()) {
            return true;
        } else {
            us.insert(i);
            graph[i].is_searched = true;
        }
    }
    for (int next : graph[i].edge) {
        if (from == -1 || s[i] != s[from]) {
            if (s[next] == s[i] && can_loop(next, i)) {
                return true;
            } 
        } else {
            if (s[next] != s[i] && can_loop(next, i)) {
                return true;
            }
        }
    }
    if (from == -1 || s[i] != s[from]) {
        us.erase(i);
    }

    return false;

}

