    for (int i = 1; i <= N; i++) {
        graph[i].is_searched = false;
    }

    for (int i = 1; i <= N; i++) {
        //std::cout << "check0:" << i << std::endl;
        if (!graph[i].is_searched && can_loop(i, -1)) {
            std::cout << "Yes" << std::endl;
            return 0;
        }
    }

    std::cout << "No" << std::endl;
    return 0;
}

