void work ()
{
	// main work

	int fr, to;
	INIT ( la, -1 );
	lpi ( i, 1, n ) {
		lp ( j, 0, 4 ) {
			fr = j >> 1;
			to = ( ( j + 1 ) & 3 ) >> 1;
			if ( s[i] == fr + 'A' ) {
				for ( auto v : e[i] ) {
					if ( s[v] == to + 'A' ) {
						addedge ( I ( i, j ), I ( v, ( j + 1 ) & 3 ) );
					}
				}
			}
		}
	}

	int l = 0, r = 0, now, v;
	lpi ( i, I ( 1, 0 ), I ( n, 3 ) ) if ( !deg[i] ) q[r++] = i;
	while ( l < r ) {
		now = q[l++];
		for ( int i = la[now]; ~i; i = edge[i].last ) {
			--deg[v = edge[i].v];
			if ( !deg[v] ) q[r++] = v;
		}
	}
	printf ( ( r ^ ( n * 4 ) ) ? "Yes\n" : "No\n" );
}

