const int Maxn = 2e5 + 100;

int N, M, e, Begin[Maxn], To[Maxn << 1], Next[Maxn << 1];
char S[Maxn];

inline void add_edge (int x, int y)
{
	To[++e] = y;
	Next[e] = Begin[x];
	Begin[x] = e;
}

int Vis[Maxn], Viss[Maxn], ans, P[Maxn];
int PP[Maxn];

inline int dfs (int x)
{
	int a = 0, b = 0;
	Vis[x] = Viss[x] = 1;
	for (int i = Begin[x]; i; i = Next[i])
	{
		int y = To[i];
		if (Viss[y])
		{
			if (Vis[y])
			{
				if (S[y] == 'A') a = 1;
				if (S[y] == 'B') b = 1;
			}
			else if (P[y])
			{
				if (S[y] == 'A') a = 1;
				if (S[y] == 'B') b = 1;
			}
		}
		else
		{
			if (dfs(y))
			{
				if (S[y] == 'A') a = 1;
				if (S[y] == 'B') b = 1;
			}
		}
	}
	Vis[x] = 0;
	if (a && b) return P[x] = 1;
	return P[x] = 0;
}

