		Add(b, a);
	}
	for (i = 1; i <= n; i++) {
		for (j = 0; j < 2; j++) {
			Deg[i][j] = E[i][j].size();
			if (E[i][j].size() == 0 && !v[i]) {
				Q[++tail] = i;
				v[i] = 1;
			}
		}
	}
	while (head < tail) {
		int x = Q[++head];
		int ck = p[x] - 'A';
		for (auto &y : E[x][0]) {
			Deg[y][ck]--;
			if (!Deg[y][ck] && !v[y]) {
				Q[++tail] = y;
				v[y] = 1;
			}
		}
		for (auto &y : E[x][1]) {
			Deg[y][ck]--;
			if (!Deg[y][ck] && !v[y]) {
				Q[++tail] = y;
				v[y] = 1;
			}
		}
	}
