int T, n, m;

int main(int argc, char *argv[]){
    ios::sync_with_stdio(false);
    while(cin >> n >> m) {
        string s;
        cin >> s;
        vi col(n);
        REP(i, n) {
            col[i] = s[i] == 'B';
        }
        vector<vector<set<int>>> g(n, vector<set<int>>(2));
        vector<vector<int>> rg(n);
        REP(i, m) {
            int u, v;
            cin >> u >> v; u--; v--;
            g[u][col[v]].insert(v);
            rg[v].push_back(u);
            swap(u, v);
            g[u][col[v]].insert(v);
            rg[v].push_back(u);
        }
        vector<int> ok(n, 1);
        queue<int> q;
        REP(i, n) {
            if (g[i][0].empty() || g[i][1].empty()) {
                ok[i] = 0;
                q.push(i);
            }
        }
        while(!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : rg[u]) {
                if (ok[v]) {
                    g[v][col[u]].erase(u);
                    if (g[v][col[u]].empty()) {
                        ok[v] = 0;
                        q.push(v);
                    }
                }
            }
        }
        int ans = accumulate(ALL(ok), 0);
        cout << (ans ? "Yes" : "No") << endl;
    }
    return 0;
}

