bool check(int u) {
	return cnt[u][0]&&cnt[u][1];
}

int main() {
	int u,v;
	scanf("%d%d",&n,&m);
	scanf("%s",s+1);
	for(int i=1;i<=n;i++) {
		tp[i]=s[i]-'A';
	}
	for(int i=1;i<=m;i++) {
		scanf("%d%d",&u,&v);
		G[u].pb(v);cnt[v][tp[u]]++;
		G[v].pb(u);cnt[u][tp[v]]++;
	}
	for(int i=1;i<=n;i++) {
		G[0].pb(i);G[i].pb(0);cnt[0][tp[i]]++;
		if(!check(i)) Q.push(i),vis[i]=1;
	}
	if(!check(0)) return puts("No"),0;
	while(!Q.empty()) {
		int u=Q.front();Q.pop();
		for(int v:G[u]) {
			if(vis[v]) continue;
			cnt[v][tp[u]]--;
