int main() {
  int N, M;
  std::string S;

  std::cin >> N >> M >> S;

  std::vector<int> A(N, 0), B(N, 0);
  std::vector<std::vector<int>> E(N);

  for (int i = 0; i < M; i++) {
    int a, b;
    std::cin >> a >> b;

    a--; b--;

    E[a].push_back(b);
    E[b].push_back(a);
  }

  std::queue<int> que;
  std::vector<bool> visited(N, false);

  for (int i = 0; i < N; i++) {
    sort(E[i].begin(), E[i].end());
    E[i].erase(std::unique(E[i].begin(), E[i].end()), E[i].end());

    for (auto u : E[i]) {
      (S[u] == 'A' ? A[i] : B[i])++;
    }

    if (A[i] == 0 || B[i] == 0) {
      que.push(i);
    }
  }

  for (; !que.empty(); que.pop()) {
    auto u = que.front();
    visited[u] = true;

    for (auto v : E[u]) {
      if (visited[v]) {
        continue;
      }

      (S[u] == 'A' ? A[v] : B[v])--;
      (S[v] == 'A' ? A[u] : B[u])--;

      // std::cout << u << " " << v << " " << A[u] << " " << B[u] << " " << A[v] << " " << B[v] << " " << std::endl;

      if (A[v] == 0 || B[v] == 0) {
        que.push(v);
      }
    }
  }

  bool ok = false;

  for (int i = 0; i < N; i++) {
    // std::cout << A[i] << " " << B[i] << std::endl;

    if (A[i] > 0 && B[i] > 0) {
      ok = true;
    }
  }

  std::cout << (ok ? "Yes" : "No") << std::endl;
}

