int vis[4 * 2 * 100005], A[4 * 2 * 100005];
vi G[4 * 100005];
void dfs(int u, int p) {
    A[u]++;
    if (vis[u]++) {
        cout << "Yes" << endl;
        exit(0);
    }
    each(v, G[u])if (v != p) {
        dfs(v, u);
    }
    vis[u]--;
}

void solve() {
    int N, M;
    cin >> N >> M;

    string S;
    cin >> S;

    rep(i, M) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        int a = 4 * u + (S[u] - 'A') * 2;
        int b = 4 * v + (S[v] - 'A') * 2;
        if (u == v) {
            G[a].push_back(a + 1);
            G[a + 1].push_back(a);
        } else {
            for (int p : {a, b}) {
                int q = p ^ a ^ b;
                if (S[u] == S[v]) {
                    G[p].push_back(q + 1);
                    G[p + 1].push_back(q);
                } else {
                    G[p + 1].push_back(q);
                }
            }
        }
    }

    rep(i, 4 * N)if (!A[i]) {
        dfs(i, -1);
    }
    cout << "No" << endl;
}

