typedef long long ll;

const int nax = 2e5 + 5;
char sl[nax];
vector<int> w[nax];
int cnt[nax][2];
bool removed[nax];

pair<int,int> f(int a) {
	return make_pair( min(cnt[a][0], cnt[a][1]), a );
}

int main() {
	int n, m;
	scanf("%d%d", &n, &m);
	scanf("%s", sl);
	while(m--) {
		int a, b;
		scanf("%d%d", &a, &b);
		--a;
		--b;
		w[a].push_back(b);
		w[b].push_back(a);
		++cnt[a][sl[b]-'A'];
		++cnt[b][sl[a]-'A'];
	}
	set<pair<int,int>> secik;
	for(int a = 0; a < n; ++a) {
		secik.insert(f(a));
	}
	while(!secik.empty()) {
		debug() << imie(secik);
		pair<int,int> p = *secik.begin();
		if(p.first != 0) {
			break;
		}
		secik.erase(secik.begin());
		int a = p.second;
		assert(!removed[a]);
		removed[a] = true;
		secik.erase(f(a));
		debug() << "remove" imie(a);
		for(int b : w[a]) {
			if(removed[b]) {
				continue;
			}
			secik.erase(f(b));
			--cnt[b][sl[a]-'A'];
			secik.insert(f(b));
		}
	}
	puts(secik.size() ? "Yes" : "No");
}

