#include <bits/stdc++.h>
using namespace std;
using lint = long long int;
template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;
template<class T> void assign(V<T>& v, int n, const T& a = T()) { v.assign(n, a); }
template<class T, class... U> void assign(V<T>& v, int n, const U&... u) { v.resize(n); for (auto&& i : v) assign(i, u...); }

bool rec(int v, V<>& vis, const string& s, const VV<>& g) {
  vis[v] = 1;
  bool fa = false, fb = false;
  for (int i : g[v]) if (vis[i] == 1) {
    if (s[i] == 'A') fa = true;
    else fb = true;
  }
  if (!fa) for (int i : g[v]) if (s[i] == 'A') {
    if (rec(i, vis, s, g)) {
      fa = true;
      break;
    }
  }
  if (!fb) for (int i : g[v]) if (s[i] == 'B') {
    if (rec(i, vis, s, g)) {
      fb = true;
      break;
    }
  }
  return vis[v] = fa and fb;
}

int main() {
  cin.tie(NULL); ios::sync_with_stdio(false);
  int n, m; cin >> n >> m;
  string s; cin >> s;
  VV<> g(n);
  for (int i = 0; i < m; i++) {
    int a, b; cin >> a >> b, a--, b--;
    g[a].push_back(b);
    if (a != b) g[b].push_back(a);
  }
  V<> vis(n, -1);
  bool ga = false, gb = false;
  for (int i = 0; i < n; i++) if (vis[i] and s[i] == 'A') {
    if (rec(i, vis, s, g)) ga = true;
  }
  vis.assign(n, -1);
  for (int i = 0; i < n; i++) if (vis[i] and s[i] == 'B') {
    if (rec(i, vis, s,g )) gb = true;
  }
  cout << (ga and gb ? "Yes" : "No") << '\n';
}

#include <bits/stdc++.h>
using namespace std;

const int MAX = (int)2e5 + 5;

vector<int> graph[MAX];
bool visited[MAX];
string charNodes;
int cnt[MAX][2];
queue<int> invalidNodes;

void bfs(){
	while(!invalidNodes.empty()){
		int currentNode = invalidNodes.front();
		visited[currentNode] = 1;
		invalidNodes.pop();

		for(int i = 0; i < graph[currentNode].size(); i++){
			int currentNeighbour = graph[currentNode][i];

			if(visited[currentNeighbour]) continue;

			cnt[currentNeighbour][charNodes[currentNode] - 'A']--;

			if(cnt[currentNeighbour][0] == 0 || cnt[currentNeighbour][1] == 0)
				invalidNodes.push(currentNeighbour);
		}
	}
}

int main() {
	int n, m;
	cin >> n >> m;
	cin >> charNodes;

	for(int i = 0; i < m; i++){
		int a, b;
		cin >> a >> b;
		--a; --b;

		graph[a].push_back(b);
		graph[b].push_back(a);

		cnt[a][charNodes[b] - 'A']++;
		cnt[b][charNodes[a] - 'A']++;
	}


	for(int i = 0; i < n; i++){
		if(cnt[i][0] == 0 || cnt[i][1] == 0)
			invalidNodes.push(i);
	}

	bfs();

	for(int i = 0; i < n; i++){
		if(!visited[i]){
			cout << "Yes\n";
			return 0;
		}
	}
	cout << "No\n";
	return 0;
}

