bool visit(int i, const vector<set<int>>& e, const vector<set<int>>& d, int s, int p)
{
	if (p && p % 4 == 0 && i == s)
		return true;
	for (auto j : (p % 2 ? d : e)[i])
	{
		if (visit(j, e, d, s, p + 1))
			return true;
	}
	return false;
}

