const int N = 2e5 + 7;

int n;
vector<int> a;

int fnd = 0;
int used[4 * N];
vector<int> ng[4 * N];

int new_state(int v, int x) {
    return 4 * v + x;
}

void add_edge(int v, int xv, int u, int xu) {
    ng[new_state(v, xv)].push_back(new_state(u, xu));
}

void dfs(int cur) {
    used[cur] = 1;
    for (auto t : ng[cur]) {
        if (used[t] == 1) {
            fnd = 1;
        }
        if (!used[t]) {
            dfs(t);
        }
    }
    used[cur] = 2;
}

int solve() {
    for (int i = 0; i < 4 * n; i++) {
        if (!used[i]) {
            dfs(i);
        }
    }
    return fnd;
}

