using namespace std;
typedef long long ll;

ll N, M, S[200000];
vector<ll> E[200000];
bool visited[200000][2][2];

bool dfs(ll v, ll p1, ll p2) {
  if (visited[v][p1][p2]) return true;
  visited[v][p1][p2] = true;

  bool ret = false;
  for (ll u : E[v]) {
    if ((p2 == p1 && p1 != S[v] && S[v] == S[u]) || (p2 != p1 && p1 == S[v] && S[v] != S[u])) {
      ret = ret || dfs(u, S[v], p1);
    }
  }

  visited[v][p1][p2] = false;

  return ret;
}

int main(void) {
  string s;
  cin >> N >> M >> s;
  REP(i, 0, N) S[i] = (s[i] == 'A' ? 0 : 1);
  REP(i, 0, M) {
    ll A, B;
    cin >> A >> B, A--, B--;
    E[A].push_back(B);
    E[B].push_back(A);
  }

  bool ok = false;
  REP(p1, 0, 2) REP(p2, 0, 2) {
    if ((p2 == p1 && p1 != S[0]) || (p2 != p1 && p1 == S[0])) {
      REP(i, 0, N) REP(j, 0, 2) REP(k, 0, 2) visited[i][j][k] = false;
      ok = ok || dfs(0, p1, p2);
    }
  }
  cout << (ok ? "Yes" : "No") << endl;
}

