bool vis[N];
void dfs(int u, int cnt) {
	if(cnt == 4) {
		puts("Yes");
		f = true;
		return ;
	}
	if(f) return ;
	vis[u] = true;
	for  (int i = 0;i < g[u].size(); i++) {
		int v = g[u][i];
		if(cnt == 0) {
			if(s[v-1] == 'A') dfs(v, cnt+1);
		}
		else if(cnt == 2) {
			if(s[v-1] == 'B') dfs(v, cnt+1);
		}
		else if(cnt == 1) {
			if(s[v-1] == 'B' && !vis[v]) dfs(v, cnt+1);
		}
		else if(cnt == 3) {
			if(s[v-1] == 'A' && vis[v]) dfs(v, cnt+1);
		}
	}
}
