// 2 <= N <= 2 × 10^{5}
// 1 <= M <= 2 × 10^{5}
// |s| = N
// s_i は A または B
// 1 <= a_i, b_i <= N
// 与えられるグラフは単純とも連結とも限らない

// ll N, ll M, string s, vl a, vl b
// ヌスークが文字 A,B のみからなる任意の文字列が作ることが可能なら Yes を、そうでなければ No を出力せよ。
void solve(){
    vvl g(N),cnt(N,vl(2));
    rep(i,M){
        g[a[i]-1].push_back(b[i]-1);
        g[b[i]-1].push_back(a[i]-1);
        ++cnt[a[i]-1][s[b[i]-1]-'A'];
        if(a[i]!=b[i])++cnt[b[i]-1][s[a[i]-1]-'A'];
    }

    queue<ll> q;
    rep(i,N){
        if(!cnt[i][0]||!cnt[i][1])q.push(i);
    }

    ll rem_cnt=0;
    vl used(N);
    while(q.size()){
        ll x=q.front();q.pop();
        if(used[x])continue;
        ++rem_cnt;
        used[x]=true;
        for(ll to:g[x]){
            --cnt[to][s[x]-'A'];
            if(!cnt[to][s[x]-'A'])q.push(to);
        }
    }
    cout<<(rem_cnt<N?YES:NO)<<endl;
}

