const int N = 200 * 1000 + 228;
set<int> g[N];
int c[N][2];
bool gen[N][2];
int t[N];
bool killed[N];
int hui;

void dfs(int v) {
    if(killed[v]) {
        return;
    }

    if((c[v][0] || gen[v][0]) && (c[v][1] || gen[v][1])) {
        return;
    }

    killed[v] = true;
    //cout << v << endl;
    --hui;
    for(int i : g[v]) {
        --c[i][t[v]];
        g[i].erase(v);
    }

    for(int i : g[v]) {
        dfs(i);
    }
    g[v].clear();
}

inline void _main_function() {
    int n, m;
    cin >> n >> m;
    hui = n;

    string s;
    cin >> s;

    for(int i = 1; i <= n; ++i) {
        t[i] = (s[i - 1] == 'B');
    }

    for(int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;

        if(a == b) {
            gen[a][t[a]] = true;
            continue;
        }

        if(!g[a].count(b)) {
            g[a].insert(b);
            g[b].insert(a);
            ++c[a][t[b]];
            ++c[b][t[a]];
        }
    }

    for(int i = 1; i <= n; ++i) {
        dfs(i);
    }

    if(hui) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }
}

