const int MAXN = 200005;

struct node {
	int to, next;
} edge[MAXN*2];
int head[MAXN], top = 0;
inline void push(int i, int j)
{ edge[++top] = (node){j, head[i]}, head[i] = top; }

int n, m;
char str[MAXN];
int cnt[MAXN][2];
int stk[MAXN], stk_top = 0;
int vis[MAXN];

int main()
{
	scanf("%d%d", &n, &m);
	scanf("%s", str+1);
	for (int i = 1; i <= m; i++) {
		int u, v;
		scanf("%d%d", &u, &v);
		if (u != v) push(u, v), push(v, u);
		else push(u, v);
	}
	for (int i = 1; i <= n; i++) {
		for (int j = head[i]; j; j = edge[j].next) {
			int to = edge[j].to;
			if (str[to] == 'A') cnt[i][0]++;
			else cnt[i][1]++;
		}
		if (cnt[i][1] == 0 || cnt[i][0] == 0) {
			stk[++stk_top] = i;
			vis[i] = 1;
		}
	}
	// cout << cnt[7][0] << " " << cnt[7][1] << endl;
	while (stk_top) {
		int nd = stk[stk_top--], id;
		if (str[nd] == 'A') id = 0;
		else id = 1;
		for (int i = head[nd]; i; i = edge[i].next) {
			int to = edge[i].to;
			if (vis[to]) continue;
			if ((--cnt[to][id]) == 0)
				stk[++stk_top] = to, vis[to] = 1;
		}
	}
	for (int i = 1; i <= n; i++)
		if (!vis[i]) {
			cout << "Yes" << endl;
			return 0;
		}
	cout << "No" << endl;
	return 0;
}

