bool solve(int N, int M, string& s, vi& a, vi& b) {
    vvi next(N);
    vi a_side(N,0), b_side(N,0);

    rep(i,M) {
        int u = a[i], v = b[i];
        int cu = (s[u] == 'A'), cv = (s[v] == 'A');

        if (cv) ++a_side[u];
        else    ++b_side[u];
        next[u].pb(v);

        if (u != v) {
            if (cu) ++a_side[v];
            else    ++b_side[v];
            next[v].pb(u);
        }
    }

    queue<int> q;
    vector<bool> visited(N, false);
    int alive = N;

    rep(i,N){
        if (a_side[i]==0 || b_side[i]==0) {
            q.push(i);
        }
    }
    while (!q.empty()){
        int u = q.front(); q.pop();
        int cu = s[u];

        visited[u] = true;
        --alive;

        for (int v: next[u]) {
            if (visited[v]) continue;
            if (cu) --a_side[v];
            else    --b_side[v];
            if (a_side[v]==0 || b_side[v]==0) {
                q.push(v);
            }
        }
    }
#ifdef DEBUG 
    cerr << N << " " << alive << " " << visited << " " << a_side << b_side << endl;
#endif
    // fprintf(stderr, "alive=%d/%d\n", alive, N);
    return alive > 0;
}

int main() {
    int N, M; cin >> N >> M;
    string s; cin >> s;
    vi a(M), b(M);
    rep(i,M) { scanf("%d %d", &a[i], &b[i]); --a[i]; --b[i]; }
    cout << (solve(N,M,s,a,b) ? "Yes":"No") << endl;
    return 0;
}

