		s[v][st[u] - 'A'] ++;
	}
	int sum = 0, r = 0, l = 0;
	for (int i = 1; i <= n; ++i)
		if (!s[i][0] || !s[i][1]) 
			q[++r] = i, vis[i] = 1, sum ++;
	while (l <= r) {
		for (int i = fst[q[l]]; i; i = nxt[i])
			if (!vis[des[i]]) {
				s[des[i]][st[q[l]] - 'A'] --;
				if (!s[des[i]][0] || !s[des[i]][1]) {
					vis[des[i]] = 1;
					q[++r] = des[i];
					sum ++;
				}
			}
		++ l;
	}
