	for(int i = 1; i <= n; i++){
		char c;
		scanf(" %c", &c);
		label[i] = (c - 'A');
	}
	for(int i = 1; i <= m; i++){
		int a, b;
		scanf("%d %d", &a, &b);
		if(a > b){
			swap(a, b);
		}
