			continue;
		}
		edgelist[{a, b}] = true;

		edge[a].push_back(b);
		con[a][label[b]]++;
		if(a != b){
			edge[b].push_back(a);
			con[b][label[a]]++;
		}
	}

	for(int i = 1; i <= n; i++){
		if(con[i][0] == 0 || con[i][1] == 0){
			del.push(i);
