#define MAXN 200005
#define INF 2100000000

using namespace std;

int n, m, st[MAXN], ed[MAXN];
pair<int, int> prs[MAXN * 2];
int head, tail, qu[MAXN];
int cnt[MAXN][2];
int lab[MAXN];
bool flag[MAXN];
char line[MAXN];

int main()
{
    //freopen("c.txt", "r", stdin);
    while (cin >> n >> m) {
        scanf("%s", line);
        for (int i = 1; i <= n; i++) {
            lab[i] = line[i - 1] - 'A';
            cnt[i][0] = cnt[i][1] = 0;
            st[i] = ed[i] = 0;
        }
        int x, y;
        for (int i = 0; i < m; i++) {
            scanf("%d%d", &x, &y);
            prs[i] = make_pair(x, y);
            prs[i + m] = make_pair(y, x);
        }
        sort(prs, prs + m + m);
        st[0] = ed[0] = 0;
        for (int i = 1; i <= n; i++) {
            st[i] = ed[i - 1];
            ed[i] = st[i];
            while (ed[i] < m + m && prs[ed[i]].first == i)
                ed[i]++;
            for (int j = st[i]; j < ed[i]; j++) {
                cnt[i][lab[prs[j].second]]++;
            }
        }
        head = tail = 0;
        for (int i = 1; i <= n; i++) {
            flag[i] = true;
            if (cnt[i][0] <= 0 || cnt[i][1] <= 0) {
                flag[i] = false;
                qu[tail++] = i;
            }
        }

        while (head < tail) {
            int u = qu[head++];
            for (int i = st[u]; i < ed[u]; i++) {
                int v = prs[i].second;
                if (flag[v] && (--cnt[v][lab[u]]) == 0) {
                    flag[v] = false;
                    qu[tail++] = v;
                }
            }
        }
        bool ck[2] = {false, false};
        for (int i = 1; i <= n; i++)
            if (flag[i])
                ck[lab[i]] = true;
        if (ck[0] && ck[1])
            cout << "Yes" << endl;
        else
            cout << "No" << endl;
    }
    return 0;

}

