vector<bool> bfs(vector<bool> &vec, int i) {
	vector<bool> isDelete = vec;

	if (isDelete[i]) {
		return isDelete;
	}

	queue<int> que;
	que.emplace(i);

	isDelete[i] = true;
	while (!que.empty()) {
