struct UF{
	int n;
	vector<int>parent,rank;
	UF(int n_=0):n(n_),parent(n_),rank(n_,1)
	{
		for(int i=0;i<n_;i++)parent[i]=i;
	}
	int find(int a)
	{
		return parent[a]!=a?parent[a]=find(parent[a]):a;
	}
	bool same(int a,int b)
	{
		return find(a)==find(b);
	}
	bool unite(int a,int b)
	{
		a=find(a),b=find(b);
		if(a==b)return false;
		if(rank[a]<rank[b])
		{
			parent[a]=b;
			rank[b]+=rank[a];
		}
		else
		{
			parent[b]=a;
			rank[a]+=rank[b];
		}
		return true;
	}
};
int N,M;
string s;
vector<int>G[2<<17];
int vis[4][2<<17];
main()
{
	cin>>N>>M>>s;
	for(int i=0;i<M;i++)
	{
		int a,b;
		cin>>a>>b;
		a--,b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	queue<pair<int,int> >P;
	for(int i=0;i<N;i++)
	{
		for(int j=0;j<4;j++)vis[j][i]=-1;
		if(s[i]=='A')
		{
			vis[1][i]=i;
			P.push(make_pair(i*4+1,i));
		}
	}
	UF uf(2*N);
	while(!P.empty())
	{
		int c=P.front().first%4,u=P.front().first/4,id=P.front().second;
		P.pop();
		for(int v:G[u])
		{
			if(s[v]=='A')
			{
				if(c<2)
				{
					if(vis[c+1][v]>=0)
					{
						if(c+1==1)uf.unite(v,N+id);
						else uf.unite(N+vis[c+1][v],N+id);
					}
					else
					{
						vis[c+1][v]=id;
						P.push(make_pair(v*4+c+1,id));
					}
				}
			}
			else
			{
				if(c>1)
				{
					if(vis[(c+1)%4][v]>=0)
					{
						uf.unite(N+vis[(c+1)%4][v],N+id);
					}
					else
					{
						vis[(c+1)%4][v]=id;
						P.push(make_pair(v*4+(c+1)%4,id));
					}
				}
			}
		}
	}
	for(int i=0;i<N;i++)
	{
		if(uf.same(i,N+i))
		{
			cout<<"Yes"<<endl;
			return 0;
		}
	}
	return 1;
}

