			if (s[to[i]]=='A')p[ys[u]][ys[to[i]]]=1;
	}
	F(i,1,m)
		if (s[a[i]]=='B'&&s[b[i]]=='B'){
			b1=p[ys[a[i]]]&p[ys[b[i]]];
			if (!b1.none()){
				printf("Yes\n");
				return 0;
			}
		}
	printf("No\n");
	return 0;
}

