void dfs(int v, int d, int root){
	visited[v][0] = d;
	visited[v][1] = root;
	for(auto &v2:graph[v]){
		if(visited[v2][0] >= 0){
			const int len = d + 1 - visited[v2][0];
			if(visited[v2][1] == root and len > 0 and len % 4 == 0){
				ok = true;
				//cout << len << " " << v << " " << v2 << endl;
			}
			return;
		} else {
			dfs(v2,d+1,root);
		}
	}
	return;
}

