void selectNodes() {
    queue<int> Q;

    for (int u = 0; u < N; u++) {
        if (neighbourA[u] == 0 or neighbourB[u] == 0) {
            isDead[u] = true;
            Q.push(u);
        }
    }

    while (!Q.empty()) {
        int u = Q.front(); Q.pop();

        for (int to : G[u]) {
            if (isDead[to] or u == to) continue;

            if (s[u] == 'A') neighbourA[to]--;
            else neighbourB[to]--;

            if (neighbourA[to] == 0 or neighbourB[to] == 0) {
                isDead[to] = true;
                Q.push(to);
            }
        }
    }
}

