#define int long long

struct UnionFind{
  vector<int> par; //親
  vector<int> size; //集合の大きさ

  UnionFind(int n){
    par.resize(n); size.resize(n, 1);
    for(int i = 0; i < n; i++){
      par[i] = i;
    }
  }

  //木の根を求める
  int root(int x){
    if(par[x] == x){
      return x;
    }else{
      return par[x] = root(par[x]);
    }
  }

  //xとyの属する集合を併合
  void unite(int x,int y){
    x = root(x), y = root(y);
    if(x == y) return;
    if(size[x] < size[y]) swap(x,y);
    par[y] = x;
    size[x] += size[y];
  }

  bool same(int x, int y){
    return root(x) == root(y);
  }
};

signed main(){

  int n, m; cin >> n >> m;
  string s; cin >> s;
  UnionFind uf(n * 2);
  vector<int> a(m), b(m);
  vector<vector<int>> G(n * 2);
  for(int i = 0; i < m; i++){
    cin >> a[i] >> b[i];
    a[i]--, b[i]--;
    if(s[a[i]] == s[b[i]]){
      if(a[i] == b[i]){
        uf.unite(a[i], a[i] + n);
      }else{
        uf.unite(a[i], b[i]);
      }
    }else{
      G[a[i]].push_back(b[i]);
      G[b[i]].push_back(a[i]);
    }
  }

  for(int i = 0; i < m; i++){
    if(a[i] == b[i]){
      for(int v : G[a[i]]){
        G[a[i] + n].push_back(v);
        G[v].push_back(a[i] + n);
      }
    }
  }

  vector<vector<int>> G2(n * 2);
  for(int i = 0; i < n * 2; i++){
    G2[uf.root(i)].push_back(i);
  }

  for(int i = 0; i < n; i++){
    if(uf.size[i] >= 2){
      for(int v : G[i]){
        if(uf.size[v] >= 2){
          for(int u : G2[v]){
            for(int p : G[u]){
              if(u != i && uf.same(p, i)){
                cout << "Yes" << endl;
                return 0;
              }
            }
          }
        }
      }
    }
  }
  cout << "No" << endl;

  return 0;
}

