        g[b].emplace_back(a);
        (s[b] == 'A' ? cntA[a] : cntB[a])++;
        (s[a] == 'A' ? cntA[b] : cntB[b])++;
    }
    vector<int> alive(n, true);
    int cnt = n;
    function<void(int)> del = [&](int u) {
