bool dfs(int pos, string str, int spos) {
	if (visited[pos]) {
		return pos == spos && str == "AABB";
	}
	visited[pos] = true;
	str += s[pos % s.size()];
	if (str.size() > 4) {
		str = str.substr(4);
	}
	rep(i, edge[pos].size()) {
		int to = edge[pos][i];
		if (str.size() == 2 || str.size() == 3) {
			if (s[to % s.size()] == 'A')	continue;
		}
		else if (s[to % s.size()] == 'B')	continue;
		if (dfs(to, str, spos)) {
			visited[pos] = false;
			return true;
		}
	}
	visited[pos] = false;
	return false;
}

