};

void solve(istream& in, ostream& out) {
  l n, m; in >> n >> m;
  string s; in >> s;
  Graph g(n);
  F(i, 0, m) {
    l a, b; in >> a >> b; a--; b--;
    g.add_undirected(a, b);
  }
  vl ca(n), cb(n);
  F(i, 0, n) {
    for (auto e : g.adj[i]) {
      if (s[e.to] == 'A') {
        ca[i]++;
      } else {
        cb[i]++;
      }
    }
  }

  vb visited(g.v);
  queue<l> q;
  F(i, 0, n) {
    if (ca[i] < 1 or cb[i] < 1) {
      visited[i] = true;
      q.emplace(i);
    }
  }
  while (not q.empty()) {
    l a = q.front(); q.pop();
    for (auto e : g.adj[a]) {
      if (visited[e.to]) continue;
      if (s[a] == 'A') {
        ca[e.to]--;
      } else {
        cb[e.to]--;
      }
      if (ca[e.to] > 0 and cb[e.to] > 0) continue;
      visited[e.to] = true;
      q.emplace(e.to);
    }
  }
  l k = n;
  F(i, 0, n) if (visited[i]) k--;
  out << (k == 0 ? "No" : "Yes") << lf;
}

