vector<int> getPair(int x, vector<pair<int, int> > pair) { // pair.first == xとなる全てのpair.secondを返したい
	int min = 0, max = pair.size();
	for (int mid = max >> 1;max - min > 1;mid = min + (max - min >> 1)) {
		if (pair[mid].first < x) min = mid;
		else max = mid;
	}
	vector<int> ret;
	for (;min < pair.size() && pair[min].first <= x;++ min) {
		if (pair[min].first == x) ret.push_back(pair[min].second);
	}
	return ret;
}

bool getPair(int x, vector<int> node) { // pair == xとなるものが存在するか
	int min = 0, max = node.size();
	for (int mid = max >> 1;max - min > 1;mid = min + (max - min >> 1)) {
		if (node[mid] < x) min = mid;
		else max = mid;
	}
	for (;min < node.size() && node[min] <= x;++ min) {
		if (node[min] == x) return true;
	}
	return false;
}

bool check(vector<pair<int, int> > pair, bool isA, Edge *e, bool *loop) {
	for (int i = 0;i < pair.size();i ++) {
		vector<int> ch = isA ? e[pair[i].first].nodeB : e[pair[i].first].nodeA;
		int count = 0;
		for (int j = 0;j < ch.size();++ j) {
			if (loop[ch[j]]) {
				count ++;
				break;
			}
		}
		ch = isA ? e[pair[i].second].nodeB : e[pair[i].second].nodeA;
		for (int j = 0;j < ch.size();++ j) {
			if (loop[ch[j]]) {
				count ++;
				break;
			}
		}
		if (count >= 2) return true;
	}
	return false;
}

