                a[numsq[v]][num[u]] = 1;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        if (s[i] != 'A') continue;
        bitset <N> A, B, C = 0;
        for (int u : gr[i]) {
            if (numsq[u] == -1) {
                for (int x : gr[u]) {
                    if (num[x] == -1) continue;
                    if (s[u] == 'A') {
                        A[num[x]] = 1;
                    } else {
                        B[num[x]] = 1;
                    }
                }
                continue;
            }
            if (s[u] == 'A') {
                A |= a[numsq[u]];
            } else {
                B |= a[numsq[u]];
            }
        }
        if ((A & B) != C) {
            cout << "Yes\n";
            return 0;
        }
    }
    cout << "No\n";
}

