    for(int i = 0; i < m; i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        g.addEdge2(a, b);
    }
    g.print();

    unordered_set<int> cands;
    for(int i = 0; i < n; i++){
        cands.insert(i);
    }
    // iota(cands.begin(), cands.end(), 0);
    unordered_set<int> allBads;
    while(1){
        unordered_set<int> bads;
        for(auto i : cands){
            if(g.bad(i)){
                bads.insert(i);
            }
        }
        if(bads.empty()){ break; }
        cands.clear();
        for(auto i : bads){
            if(allBads.count(i)){ continue; }
            g.erase(i, cands);
        }
        allBads.insert(bads.begin(), bads.end());
