    if (A == B) {
      if (S[A] == 'A') add_arc(g, A, A + N);
      else add_arc(g, A + 2 * N, A + 3 * N);
    } else if (S[A] == S[B]) {
      if (S[A] == 'A') {
        add_arc(g, A, B + N);
        add_arc(g, B, A + N);
      } else {
        add_arc(g, A + 2 * N, B + 3 * N);
        add_arc(g, B + 2 * N, A + 3 * N);
      }
    } else {
      if (S[A] == 'A') {
        add_arc(g, A + N, B + 2 * N);
        add_arc(g, B + 3 * N, A);
      } else {
        add_arc(g, A + 3 * N, B);
        add_arc(g, B + N, A + 2 * N);
      }
    }
  }

  Yes(!TopologicalSort(g));

}

