{
    if(col[root] != 1) return 0;

    int temp = 0;

    if(ty == 0)
    {
        for(auto x : mat[p])
        if(col[x] == 1 && !temp) temp = max(temp, rec(x, root, 1));
    }
    else if(ty == 1)
    {
        for(auto x : mat[p])
            if(col[x] == 2 && !temp) temp = max(temp, rec(x, root, 2));
    }
    else if(ty == 2)
    {
        for(auto x : mat[p])
            if(col[x] == 2 && !temp) temp = max(temp, rec(x, root, 3));
    }
    else if(ty == 3)
    {
        for(auto x : mat[p])
            if(col[x] == col[root]) temp = 1;
    }

    return temp;
}

