int head[maxn], tot = 0;
void addedge(int u, int v){e[++tot].to = v, e[tot].next = head[u]; head[u] = tot;}

int n, m, Index[maxn][2];
char str[maxn];

bool vis[maxn];

void topo(){
	queue <int> q; while (!q.empty()) q.pop();

	for (int i = 1; i <= n; i++)
		if (!Index[i][0] || !Index[i][1]) q.push(i);

	while (!q.empty()){
		int cur = q.front(); q.pop();
		vis[cur] = true;

		for (int i = head[cur]; i; i = e[i].next){
			if (!vis[e[i].to] && !--Index[e[i].to][str[cur] - 'A'] || !Index[e[i].to][!(str[cur] - 'A')]){
				q.push(e[i].to);
			}
		}
	}	
}

