const int N = 2e5 + 5;
vector<int> g[N];
int cnt[2][N];
char s[N];
bool mark[N];

void solve() {
	int n, m;
    sc(n, m);
    fr(i, 1, n) {
        sc(s[i]);
    }
    fr(i, 1, m) {
        int u, v;
        sc(u, v);
        g[u].pb(v);
        g[v].pb(u);
    }
    fr(i, 1, n) {
        for(int v : g[i]) {
            cnt[s[v] - 'A'][i]++;
        }
    }
    queue<int> q;
    fr(i, 1, n) {
        if(!cnt[0][i] || !cnt[1][i]) { q.push(i); mark[i] = 1; }
    }
    while(!q.empty()) {
        int u = q.front();
        q.pop();
        for(int v : g[u]) {
            if(mark[v]) continue;
            cnt[s[u] - 'A'][v]--;
            if(!cnt[s[u] - 'A'][v]) {
                mark[v] = 1;
                q.push(v);
            }
        }
    }
    fr(i, 1, n) {
        if(cnt[0][i] && cnt[1][i]) {
            cout << "Yes";
            return;
        }
    }
    cout << "No";
}

