struct StronglyConnectedComponents{
    vector<int> used,cmp,vs;
    vector<vector<int>> v,rv;
    StronglyConnectedComponents(int n):used(n),cmp(n,-1),v(n),rv(n){}

    void add_edge(int x,int y){
        v[x].push_back(y);
        rv[y].push_back(x);
    }
    void dfs(int x){
       used[x]=true;
       for(auto to:v[x])if(!used[to])dfs(to);
       vs.push_back(x);
    }

    void rdfs(int x,int k){
       cmp[x]=k;
       for(auto to:rv[x])if(cmp[to]==-1)rdfs(to,k);
    }

    void build(vector<vector<int>> &g){
       rep(i,used.size())if(!used[i])dfs(i);
       reverse(vs.begin(),vs.end());
       int k=0;
       for(auto x:vs)if(cmp[x]==-1)rdfs(x,k++);
       g.resize(k);
       rep(i,v.size()){
           for(auto& to:v[i]){
               int x=cmp[i],y=cmp[to];
               if(x!=y)g[x].push_back(y);
           }
       }
    }
};
int main(){
    int n,m;
    cin>>n>>m;
    string s;
    cin>>s;
    StronglyConnectedComponents scc(2*n);
    rep(i,m){
        int x,y;
        cin>>x>>y;
        --x;--y;
        if(s[x]==s[y]){
            scc.add_edge(x,y+n);
            scc.add_edge(y,x+n);
        }
        else {
            scc.add_edge(x+n,y);
            scc.add_edge(y+n,x);
        }
    }
    vector<vector<int>> ret;
    scc.build(ret);
    cout<<(ret.size()==2*n?"No":"Yes")<<endl;
    return 0;
}

