	for (int i=1;i<=n;i++) if (a[i] == 0 || b[i] == 0) {del[i] = 1;  Q.push(i);}
	while (!Q.empty()) {
		int u = Q.front();  Q.pop();
		for (edge *p=head[u];p;p=p->nxt) if (!del[p->to]) {
			if (s[u] == 'A') --a[p->to];  else --b[p->to];
			if (a[p->to] == 0 || b[p->to] == 0) {del[p->to] = 1;  Q.push(p->to);}
		}
	}
	for (int i=1;i<=n;i++) if (!del[i]) {
		for (edge *p=head[i];p;p=p->nxt) if (!del[p->to] && s[i] != s[p->to]) {
			puts("YES");
			return 0;
		} 
	}
	puts("NO");
}

