const int MAXN = (int)2e5 + 7;
vector<int> g[MAXN];
int n, m;
string S;
int cntA[MAXN], cntB[MAXN], killed[MAXN];

void solve() {
	cin >> n >> m >> S;
	for(int i = 0; i < m; ++i) {
		int v = fetch<int>() - 1;
		int u = fetch<int>() - 1;
		g[v].push_back(u);
		g[u].push_back(v);
	}
	for(int v = 0; v < n; ++v) {
		auto& row = g[v];
		sort(row.begin(), row.end());
		row.erase(unique(row.begin(), row.end()), row.end());
	}
	for(int v = 0; v < n; ++v) {
		for(auto& u: g[v]) {
			if(S[u] == 'A') ++cntA[v];
			if(S[u] == 'B') ++cntB[v];
		}
	}
	set<pii> setik;
	for(int v = 0; v < n; ++v) {
		setik.emplace(min(cntA[v], cntB[v]), v);
	}
	while(!setik.empty()) {
		auto iter = setik.begin();
		int v = iter->second;
		killed[v] = 1;
		if(cntA[v] > 0 && cntB[v] > 0) break;
		setik.erase(iter);
		for(auto& u: g[v]) {
			if(killed[u]) continue;
			setik.erase(make_pair(min(cntA[u], cntB[u]), u));
			if(S[v] == 'A') --cntA[u];
			if(S[v] == 'B') --cntB[u];
			setik.emplace(min(cntA[u], cntB[u]), u);
		}
	}
	int cnt = 0;
	for(int v = 0; v < n; ++v) cnt += (cntA[v] > 0) && (cntB[v] > 0);
	cout << (cnt > 0 ? "Yes\n" : "No\n");
}

