const int MAX = 200000;
struct Edge {
	vector<int> nodeA;
	vector<int> nodeB;
};

vector<int> getPair(int x, vector<pair<int, int> > pair) {
	int min = 0, max = pair.size();
	for (int mid = max >> 1;max - min > 1;mid = min + (max - min >> 1)) {
		if (pair[mid].first < x) min = mid;
		else max = mid;
	}
	vector<int> ret;
	for (;min < pair.size() && pair[min].first <= x;++ min) {
		if (pair[min].first == x) ret.push_back(pair[min].second);
	}
	return ret;
}

bool getPair(int x, vector<int> pair) {
	int min = 0, max = pair.size();
	for (int mid = max >> 1;max - min > 1;mid = min + (max - min >> 1)) {
		if (pair[mid] < x) min = mid;
		else max = mid;
	}
	return (min < pair.size() && pair[min] == x) || (max < pair.size() && pair[max] == x);
}

bool check(vector<pair<int, int> > pair, bool isA, Edge *e, bool *loop, int N) {
	for (int i = 0;i < pair.size();i ++) {
		vector<int> ch = isA ? e[pair[i].first].nodeB : e[pair[i].first].nodeA;
		int count = 0;
		for (int j = 0;j < ch.size();++ j) {
			if (loop[ch[j]]) {
				count ++;
				break;
			}
		}
		ch = isA ? e[pair[i].second].nodeB : e[pair[i].second].nodeA;
		for (int j = 0;j < ch.size();++ j) {
			if (loop[ch[j]]) {
				count ++;
				break;
			}
		}
		if (count >= 2) return true;
	}
	return false;
}

int main() {
	int N, M, a, b;
	string s;
	cin >> N >> M >> s;
	static Edge edge[MAX];
	static vector<pair<int, int> > Apair, Bpair; // A-AとB-Bの辺
	static bool loop[MAX];
	memset(loop, false, N);
	for (int i = 0;i < M;++ i) {
		cin >> a >> b;
		-- a; -- b;
		if (s[b] == 'A') edge[a].nodeA.push_back(b);
		else  edge[a].nodeB.push_back(b);
		if (s[a] == 'A') edge[b].nodeA.push_back(a);
		else edge[b].nodeB.push_back(a);
		if (s[a] == s[b]) {
			if (s[a] == 'A') {
				Apair.push_back(make_pair(a, b));
				Apair.push_back(make_pair(b, a));
			} else {
				Bpair.push_back(make_pair(a, b));
				Bpair.push_back(make_pair(b, a));
			}
		}
		if (a == b) loop[a] = true;
	}
	for (int i = 0;i < N;++ i) {
		sort(edge[i].nodeA.begin(), edge[i].nodeA.end());
		sort(edge[i].nodeB.begin(), edge[i].nodeB.end());
	}
	sort(Apair.begin(), Apair.end());
	sort(Bpair.begin(), Bpair.end());

/*	for (int i = 0;i < Apair.size();++ i) {
		cerr << "A:" << Apair[i].first << "," << Apair[i].second << endl;
	}
	for (int i = 0;i < Bpair.size();++ i) {
		cerr << "B:" << Bpair[i].first << "," << Bpair[i].second << endl;
	}*/

	for (int i = 0;i < Apair.size();++ i) {
		int a1 = Apair[i].first, a2 = Apair[i].second;
		for (int j = 0;j < edge[a1].nodeB.size();++ j) {
			static vector<int> b2 = getPair(edge[a1].nodeB[j], Bpair);
			for (int k = 0;k < b2.size();++ k) {
				if (getPair(b2[k], edge[a2].nodeB)) {
//					cerr << a1 << "," << a2 << " - " << edge[a1].nodeB[j] << "," << b2[k] << endl;
					cout << "Yes";
					return 0;
				}
			}
		}
	}
	if (check(Apair, true, edge, loop, N) || check(Bpair, false, edge, loop, N)) cout << "Yes";
	else cout << "No";
	return 0;
}
