void dfs(int start, int number) {
    if (check_color[start] == BLACK) return;
    check_disjoint[start] = number;
    check_color[start] = BLACK;
    for (int i = 0; i < graph[start].size(); i++) {
        dfs(graph[start][i], number);
    }
    return;
}

int main() {
    int N, M, a, b;
    cin >> N >> M;
    string s;
    cin >> s;
    for (int i = 0; i < N; i++) {
        check_side[i].A = false;
        check_side[i].B = false;
        check_color[i] = WHITE;
    }
    for (int i = 0; i < M; i++) {
        cin >> a >> b;
        a--, b--;
        graph[a].push_back(b);
        graph[b].push_back(a);
        if (s[b] == 'A' && check_side[a].A == false) check_side[a].A = true;
        if (s[b] == 'B' && check_side[a].B == false) check_side[a].A = true;
        if (s[a] == 'A' && check_side[b].A == false) check_side[b].A = true;
        if (s[b] == 'B' && check_side[b].B == false) check_side[b].A = true;
    }
    int disjoint_num = 0;
    for (int i = 0; i < N; i++) {
        if (check_color[i] == WHITE) {
            dfs(i, disjoint_num);
            disjoint_num++;
        }
    }
    dsj tmp;
    for (int i = 0; i < N; i++) {
        tmp.first = check_disjoint[i];
        tmp.second = i;
        check_group.push_back(tmp);
    }
    sort(check_group.begin(), check_group.end());
    int now_dsj = check_group[0].first;
    bool success = true;
    if (! check_side[check_group[0].second].A || ! check_side[check_group[0].second].B) success = false;
    for (int i = 1; i < check_group.size(); i++) {
        if (check_group[i].first == now_dsj) {
            if (! check_side[check_group[i].second].A || ! check_side[check_group[i].second].B) success = false;
        }
        else {
            now_dsj = check_group[i].first;
            success = true;
            if (! check_side[check_group[i].second].A || ! check_side[check_group[i].second].B) success = false;
        }
    }
    if (success) cout << "Yes" << endl;
    else cout << "No" << endl;
    return 0;
}

