bool dfs(int i=0, char pre='-', char now='-') {
    visited[i] = true;
    bool nextA = true, nextB = true;
    if (pre != 'A') {
        nextA = false;
        for (auto g:G[1][i]) {
            if (visited[g]) {
                nextA = true;
                break;
            }
        }
        if (!nextA)
        for (auto g:G[1][i]) {
            if (dfs(g, now, 'B')) {
                nextA = true;
                break;
            }
        }
    }
    if (pre != 'B') {
        nextB = false;
        for (auto g:G[0][i]) {
            if (visited[g]) {
                nextB = true;
                break;
            }
        }
        if (!nextB)
        for (auto g:G[0][i]) {
            if (dfs(g, now, 'B')) {
                nextB = true;
                break;
            }
        }
    }
    if (nextA && nextB) {
        return true;
    } else {
        visited[i] = false;
        return false;
    }
}

