bool dfs(int pos, string str) {
	if (failed[pos].count(str) > 0)	return false;
	if (visited[pos].count(str) > 0)	return true;
	visited[pos].insert(str);
	string newstr = str + s[pos % s.size()];
	if (newstr.size() > 4) {
		newstr = newstr.substr(4);
	}
	rep(i, edge[pos].size()) {
		int to = edge[pos][i];
		if (newstr.size() == 2 || newstr.size() == 3) {
			if (s[to % s.size()] == 'A')	continue;
		}
		else if (s[to % s.size()] == 'B')	continue;
		if (dfs(to, newstr)) {
			return true;
		}
	}
	failed[pos].insert(str);
	return false;
}

