        scanf("%d %d", &u, &v);
        g[u].pb(v);
        g[v].pb(u);
    }
    for (int i = 1; i <= n; i++) {
        for (int v : g[i]) {
            d[v][s[i-1] - 'A']++;
        }
    }
    for (int i = 1; i <= n; i++) {
        if(!d[i][0] || !d[i][1]) que[++top] = i;
    }
    int now = 1;
    while(now <= top) {
        int u = que[now];
        for (int v : g[u]) {
            d[v][s[u-1] - 'A'] --;
            if(!d[v][s[u-1] - 'A']) que[++top] = v;
        }
        now++;
    }
    if(top < n) puts("Yes");
    else puts("No");
    return 0;
}

