void solve() {
	cin >> n >> m >> s;
	vector<int> dega(n, 0), degb(n, 0);
    rep(i, m) {
        int a, b; cin >> a >> b; --a; --b;
        g[a].push_back(b);
        g[b].push_back(a);
		if(s[a] == 'A') {
			dega[b] ++;
		} else {
			degb[b] ++;
		}
		if(s[b] == 'A') {
			dega[a] ++;
		} else {
			degb[a] ++;
		}
    }
	queue<int> que;
	vector<bool> ispushed(n, 0);
	rep(i, n) {
		if(dega[i] == 0 || degb[i] == 0) {
			que.push(i);
			ispushed[i] = 1;
		}
	}
	while(!que.empty()) {
		int v = que.front(); que.pop();
		for(auto& nv: g[v]) {
			if(ispushed[nv]) continue;
			if(s[v] == 'A') {
				dega[nv] --;
			} else {
				degb[nv] --;
			}

			if(dega[nv] == 0 || degb[nv] == 0) {
				que.push(nv);
				ispushed[nv] = 1;
			}
		}
	}
	bool ok = false;
	rep(i, n) {
		if(!ispushed[i]) ok = true;
	}
	if(ok) {
		cout << "Yes" << endl;
	} else {
		cout << "No" << endl;
	}
}  

