                    if(ab[G.G[a[i]][k].to] == 0 && ab[G.G[b[i]][l].to] == 0){
                        G2.add_edge(G.G[a[i]][k].to, G.G[b[i]][l].to + N, 0);
                        G2.add_edge(G.G[b[i]][l].to, G.G[a[i]][k].to + N, 0);
                    }
                }
            }
        }
        if(ab[a[i]] == 0 && ab[b[i]] == 0){
            G2.add_edge(a[i] + N, b[i], 0);
            G2.add_edge(b[i] + N, a[i], 0);
        }
    }

    vector<bool> flag(2 * N, false);
    bool ans = false;
    set<Pii> S;
    REP(i, N){
        if(!flag[i]){
            flag[i] = true;
            if(G2.dfs(i, flag, S)){
                ans = true;
                //cout << i << endl;
            }
        }
    }

    if(ans){
        cout << "Yes";
    }else{
        cout << "No";
    }

    return 0;
}


