struct ed{
  int x;
  int y;
  bool operator<(const struct ed & right) const{
    return (x==right.x?(y<right.y):(x<right.x));
  }
};

int main(){
  int n,m;
  cin >> n >> m;
  vector<list<int>> e(n);
  string s;
  cin >> s;
  int tmp;
  vector<struct ed> me(m);
  for(int i=0;i<m;i++){
    cin >> me[i].x >> me[i].y;
    me[i].x--;
    me[i].y--;
    if(me[i].y>me[i].x){
      tmp=me[i].x;
      me[i].x=me[i].y;
      me[i].y=tmp;
    }
  }
  sort(me.begin(),me.end());
  e[me[0].x].push_back(me[0].y);
  if(me[0].x!=me[0].y) e[me[0].y].push_back(me[0].x);
  for(int i=1;i<m;i++){
    if(me[i].x!=me[i-1].x||me[i].y!=me[i-1].y){
      e[me[i].x].push_back(me[i].y);
      if(me[i].x!=me[i].y) e[me[i].y].push_back(me[i].x);
    }
  }
  char aa[4]={'A','B','B','A'};
  vector<vector<LL>> mem(4,vector<LL>(n,-1));
