  struct st now;
  for(int i=0;i<n;i++){
    if(s[i]=='A'&&mem[0][i]==-1&&mem[1][i]==-1){
      list<int> r;
      q.push({i,0});
      r.push_back(i);
      mem[0][i]=0;
      while(!q.empty()){
        now=q.front();
        q.pop();
        // cout << "---" << now.num+1 << " " << now.d << endl;
        for(auto next:e[now.num]){
          if(s[next]==aa[now.d%4]){
            if(mem[(now.d+1)%4][next]>=0){
              if(mem[(now.d+1)%4][next]<now.d+1){
                cout << "Yes" << endl;
                return 0;
              }
            }else{
              q.push({next,now.d+1});
              mem[(now.d+1)%4][next]=now.d+1;
              r.push_back(next);
            }
          }
        }
      }
      for(auto j:r){
        for(int k=0;k<4;k++) mem[k][j]=-100;
      }
    }
