bool dfs(const int u, const int src, const int d) {
    if (d == 4)
        return u == src;
    FOR_ALL(j,G[u]) {
        const int v = j->v;
        if (d == 0 || d == 3) {
            if (colr[v] == 0 && dfs(v,src,d+1))
                return true;
        }
        else {
            if (colr[v] == 1 && dfs(v,src,d+1))
                return true;
        }
    }
    return false;
}

