#define IREP(i, n) IFOR(i,0,n)

int N, M;
string s;
constexpr int Nmax = 400000;
vector<int> to[Nmax * 2];
bitset<Nmax * 2> isGood;

void Yes()
{
    cout << "Yes" << endl;
    exit(0);
}

int main()
{
    cin >> N >> M >> s;
    REP(i, M)
    {
        int a, b;
        cin >> a >> b;
        a--; b--;
        if (s[a] == s[b])
        {
            to[a].push_back(b + N);
            to[b].push_back(a + N);
        }
        else
        {
            to[a + N].push_back(b);
            to[b + N].push_back(a);
        }
    }

    REP(i, N * 2) isGood.set(i);
    REP(i, N * 2)
    {
        set<int> visited;
        queue<int> tovisit;
        tovisit.push(i);
        while (!tovisit.empty())
        {
            int now = tovisit.front();
            tovisit.pop();
            if (visited.find(now) != visited.end()) Yes();
            visited.insert(now);
            for (auto v : to[now]) if (isGood[v])
            {
                tovisit.push(v);
            }
        }

        for (auto v : visited) isGood.reset(v);
    }
    cout << "No" << endl;
}

