int n, w[200000];
vector<int> v[200000], u[200000];
string s;
int b[200000];
bool f(int x, int y, int z){
    for(int i=0;i<v[x].size();i++){
        int t=v[x][i];
        if(y==0&&s[t]=='A'){
            if(f(t, y+1, z))return true;
        }else if((y==1||y==2)&&s[t]=='B'){
            if(f(t, y+1, z))return true;
        }else if(y==3&&t==z){
            return true;
        }
    }
    return false;
}
bool g(int x, int y, int z){
    for(int i=0;i<v[x].size();i++){
        int t=v[x][i];
        if(y==0&&s[t]=='B'){
            if(g(t, y+1, z))return true;
        }else if((y==1||y==2)&&s[t]=='A'){
            if(g(t, y+1, z))return true;
        }else if(y==3&&t==z){
            return true;
        }
    }
    return false;
}

void h(int x, int y, int z){
    for(int i=0;i<v[x].size();i++){
        if(i>0){
            if(v[x][i]==v[x][i-1])continue;
        }
        int t=v[x][i];
        if(y==0&&s[t]=='A'){
            h(t, y+1, z);
        }else if((y==1||y==2)&&s[t]=='B'){
            h(t, y+1, z);
        }else if(y==3&&s[t]=='A'){
            u[z].push_back(t);
            //cout<<z<<" ---- "<<t<<endl;
        }
    }
}

bool k(int x, int y){
    b[x]=y;
    sort(u[x].begin(), u[x].end());
    for(int i=0;i<u[x].size();i++){
        if(i>0){
            if(u[x][i]==u[x][i-1])continue;
        }
        if(b[u[x][i]]==y)return true;
        if(b[u[x][i]]==-1&&k(u[x][i], y))return true;
    }
    return false;
}


