        a--;
        b--;
        v[a].push_back(b);
        if(a!=b)v[b].push_back(a);
    }
    for(int i=0;i<n;i++){
        sort(v[i].begin(), v[i].end());
    }
    for(int i=0;i<n;i++){
        w[i]=0;
        if(s[i]=='A'){
            if(f(i, 0, i)){
                cout<<"Yes"<<endl;
                return 0;
            }else if(f(i, 1, i)){
                w[i]=1;
            }
        }else if(g(i, 1, i)){
            w[i]=2;
        }
        if(w[i]>0){
            //cout<<i<<"of w : "<<w[i]<<endl;
            for(int j=0;j<v[i].size();j++){
                if(w[v[i][j]]==w[i]){
                    cout<<"Yes"<<endl;
                    return 0;
                }
            }
        }
    }
    for(int i=0;i<n;i++){
        if(s[i]=='A'){
            h(i, 0, i);
        }
    }
    fill(b, b+n, -1);
    for(int i=0;i<n;i++){
        if(b[i]==-1){
            if(k(i, i)){
                cout<<"Yes"<<endl;
                //cout<<i<<endl;
                return 0;
            }
        }
    }
