typedef ll val_t;

struct graph_t {
	int n;           // |V|, index begins with 0
	int m;           // |E|
	vector<P> edges; // E
	vector<val_t> vals; // V
	vector<ll> cost; // cost or distance
	vector<ll> cap;  // capacity
};

class Graph {
private:
	struct node {
		int id; val_t val; bool done; vi to_eid; vi to;
	};
	vector<node> nodes;
	int n;
public:
	Graph(graph_t G) {
		n = G.n;
		nodes.resize(n);
		Loop(i, n) nodes[i] = { i,G.vals[i],false,{},{} };
		Loop(i, G.edges.size()) {
			nodes[G.edges[i].first].to_eid.push_back(i);
			nodes[G.edges[i].first].to.push_back(G.edges[i].second);
		}
		return;
	}
	bool solve() {
		queue<int> que;
		vi cnt_a(n, 0), cnt_b(n, 0);
		Loop(i, n) {
			for(int j : nodes[i].to) {
				if (nodes[j].val == 0) cnt_a[i]++;
				else cnt_b[i]++;
			}
			if (cnt_a[i] == 0 || cnt_b[i] == 0) que.push(i);
		}
		vector<bool> valids(n, true);
		while (que.size()) {
			int a = que.front(); que.pop();
			if (!valids[a]) continue;
			valids[a] = false;
			for (int b : nodes[a].to) {
				if (nodes[a].val == 0) cnt_a[b]--;
				else cnt_b[b]--;
				if (cnt_a[b] == 0 || cnt_b[b] == 0) que.push(b);
			}
		}
		Loop(i, n) {
			if (valids[i]) return true;
		}
		return false;
	}
};

int main() {
	graph_t G;
	cin >> G.n >> G.m;
	string s; cin >> s;
	Loop(i, G.n) G.vals.push_back(s[i] - 'A');
	Loop(i, G.m) {
		int s, t; cin >> s >> t;
		s--; t--;
		G.edges.push_back({ s,t });
		G.edges.push_back({ t,s });
	}
	Graph graph(G);
	bool ans = graph.solve();
	if (ans) cout << "Yes" << endl;
	else cout << "No" << endl;
}

