int n, m;
char tmp[200200];
int col[200200];
vector<int> g[200200];
int has_self[200200];
map<pii, int> has;
vector<pii> edges;
vector<int> target;
const int SZ = 200;
char dp[202][200200];

bool solve() {
    target.clear();
    for (int i = 0; i < SZ; i++) target.pb(rand() & 1);
    for (int i = 0; i < n; i++) {
        dp[0][i] = (target[0] == col[i]);
    }
    for (int lvl = 1; lvl < SZ; lvl++) {
        for (int v = 0; v < n; v++) {
            if (col[v] != target[lvl]) {
                dp[lvl][v] = 0;
                continue;
            }
            dp[lvl][v] = 0;
            forit (it, g[v]) {
                int u = *it;
                dp[lvl][v] |= dp[lvl - 1][u];
            }
        }
    }
    for (int i = 0; i < n; i++)
        if (dp[SZ - 1][i]) return true;
    return false;
}

