vector <int> v[MaxN];
string s;

bool deleted[MaxN];

set<pair<int, int> > S;

int cnt[2][MaxN];

void popV(int x)
{
    deleted[x] = true;

    for(int to : v[x])
        if(!deleted[to])
        {
            S.erase(make_pair(min(cnt[0][to], cnt[1][to]), to));
            if(s[x] == 'A')
                --cnt[0][to];
            else
                --cnt[1][to];
            S.insert(make_pair(min(cnt[0][to], cnt[1][to]), to));
        }
}

