    for(int i = 0; i < m; ++i)
    {
        int x, y;
        cin >> x >> y;
        --x, --y;

        v[x].push_back(y);
        v[y].push_back(x);

        if(s[x] == 'A')
            ++cnt[0][y];
        else
            ++cnt[1][y];

        if(s[y] == 'A')
            ++cnt[0][x];
        else
            ++cnt[1][x];
    }

    for(int i = 0; i < n; ++i)
        S.insert(make_pair(min(cnt[0][i], cnt[1][i]), i));

    while(!S.empty() && (*S.begin()).first == 0)
    {
        int x = (*S.begin()).second;
        S.erase(S.begin());

        popV(x);
    }

    if(S.empty())
