bool dfs(int now){
  bool a=0,b=0;
  if(dp[now]!=-1)return dp[now];
  if(v[now]==true){
    if(f[now]==0)return false;
    else return true;
  }
  v[now]=true;
  if(f[now]==0)return false;
  for(int i=0;i<node[now].size();i++){
    int next=node[now][i];
    if(s[next]=='A'){
      a|=dfs(next);
    }
    if(s[next]=='B'){
      b|=dfs(next);
    }
  }
  return dp[now]=(a&&b);
}

