signed main() {
	INIT;

	VAR(int, n, m);
	VAR(std::string, s);
	VEC_ROW(int, m, a, b);

	// まずは与えられたグラフを用意
	std::vector<std::vector<int>> g(n);
	REP(i, m) {
		--a[i]; --b[i];
		g[a[i]].emplace_back(b[i]);
		g[b[i]].emplace_back(a[i]);
	}

	// 頂点倍化して(AABB)*形の閉路が検出できる有向グラフの形にする
	std::vector<std::vector<int>> G(n * 2);
	REP(i, n) {
		for (auto& to : g[i]) {
			if (s[i] == s[to]) G[i + 0].emplace_back(to + n);
			if (s[i] != s[to]) G[i + n].emplace_back(to + 0);
		}
	}
	n += n;

	// ------------->8 ここからトポロジカルソート >8-------------

	// 各頂点の入次数を調べる
	std::vector<int> in(n, 0);
	REP(i, n) for (auto& to : G[i]) ++in[to];

	// 入次数が0の頂点をキューにいれていく
	std::queue<int> que;
	REP(i, n) if (in[i] == 0) que.push(i);

	std::vector<int> topo(n, -1);
	int p = 0;
	while (!que.empty()) {
		int now = que.front(); que.pop();
		topo[now] = p++;
		for (auto& to : G[now]) {
			// 自信を除くと行き先頂点の入次数が1減る,
			// この時点で行き先頂点の入次数が0になるなら次に削除するキューにいれておく
			if (--in[to] == 0) {
				que.push(to);
			}
		}
	}
	// ------------->8 ここまでトポロジカルソート >8-------------


	// 値が書き込まれていない頂点が存在すれば閉路があるのでYes
	REP(i, n) {
		if (topo[i] == -1) {
			OUT("Yes")BR;
			return 0;
		}
	}
	// そうでなければNo
	OUT("No")BR;
	return 0;
}

