bool used[MAXN];

bool read() {
    if (!(cin >> n >> m >> s))
        return false;

    forn (i, m) {
        int u, v;
        cin >> u >> v;
        g[u - 1].insert(v - 1);
        g[v - 1].insert(u - 1);
    }

    return true;
}

void solve() {
    queue<int> Q;
    int rem = 0;

    for (int v = 0; v < n; ++v) {
        for (auto u : g[v]) {
            cntA[v] += (s[u] == 'A');
            cntB[v] += (s[u] == 'B');
        }

        if (cntA[v] == 0 || cntB[v] == 0) {
            Q.push(v);
            used[v] = true;
        }
    }

    while (!Q.empty()) {
        auto v = Q.front();
        Q.pop();
        ++rem;

        for (auto to : g[v]) {
            if (to == v)
                continue;

            g[to].erase(v);
            cntA[to] -= (s[v] == 'A');
            cntB[to] -= (s[v] == 'B');

            if (!used[to] && (cntA[to] == 0 || cntB[to] == 0)) {
                used[to] = true;
                Q.push(to);
            }
        }

        g[v].clear();
    }

    if (rem == n)
        cout << "No\n";
    else
        cout << "Yes\n";
}

