inline char fgc() {
    static char buf[1 << 15], *p1 = buf, *p2 = buf; 
    return p1 == p2 && (p2 = (p1 = buf) + fread(buf, 1, 1 << 15, stdin), p1 == p2) ? EOF : *p1++; 
}

inline int read() {
    static int x, f, ch; 
    x = 0, f = 0, ch = fgc(); 
    while (ch < '0' || ch > '9') ch == '-' ? f = 1 : 0, ch = fgc(); 
    while (ch >= '0' && ch <= '9') x = x * 10 + ch - '0', ch = fgc(); 
    return f ? -x : x; 
}

inline void addEdge(int u, int v) {
    N[++cnt].v = v; 
    N[cnt].next = Head[u]; 
    Head[u] = cnt; 
}

int deg[Maxv][2], q[Maxv], head, tail, n, m; 
char col[Maxv]; 
bool vis[Maxv]; 

int main() {
    n = read(); 
    m = read(); 
    scanf("%s", col + 1); 

    for (int i = 1; i <= m; i++) {
        int u = read(); 
        int v = read();
        addEdge(u, v); 
        addEdge(v, u); 
        deg[u][col[v] == 'B']++; 
        deg[v][col[u] == 'B']++; 
    }

    for (int i = 1; i <= n; i++) {
        if (deg[i][0] == 0 || deg[i][1] == 0) {
            vis[i] = true; 
            q[tail++] = i; 
        }
    }

    while (head != tail) {
        int x = q[head++]; 

        for (int i = Head[x]; i; i = N[i].next) {
            if (!vis[ N[i].v ]) {
                if (--deg[ N[i].v ][col[x] == 'B'] == 0) {
                    vis[ N[i].v ] = true; 
                    q[tail++] = N[i].v; 
                }
            }
        }
    }

    if (tail == n) puts("No"); 
    else puts("Yes"); 

    return 0; 
}

