#define POS(k,i) ((k)*n+(i))

void assign(int a,int b,int *vertex,int *next,int *start,int index){
  vertex[index]=b;
  next[index]=start[a];
  start[a]=index;
  return;
}

void run(void){
  int n,m;
  scanf("%d%d",&n,&m);
  char *s=(char *)malloc(sizeof(char)*(n+1));
  scanf("%s",s);
  int *vertex=(int *)malloc(sizeof(int)*2*m);
  int *next=(int *)malloc(sizeof(int)*2*m);
  int *start=(int *)malloc(sizeof(int)*n);
  int i;
  for(i=0;i<n;i++) start[i]=-1;
  for(i=0;i<m;i++){
    int a,b;
    scanf("%d%d",&a,&b);
    a--;
    b--;
    assign(a,b,vertex,next,start,2*i);
    assign(b,a,vertex,next,start,2*i+1);
  }
  const int f=18*4;
  int *cond=(int *)calloc((f+1)*n,sizeof(int));
  for(i=0;i<n;i++) cond[i]=1;
  int k;
  for(k=1;k<=f;k++){
    for(i=0;i<n;i++){
      if(!cond[POS(k-1,i)]) continue;
      int flagA=0;
      int flagB=0;
      int p;
      for(p=start[i];p!=-1;p=next[p]){
	int v=vertex[p];
	if(s[v]=='A' && cond[POS(k-1,v)]){
	  flagA=1;
	} else if(s[v]=='B' && cond[POS(k-1,v)]){
	  flagB=1;
	}
      }
      if(flagA && flagB) cond[POS(k,i)]=1;
    }
  }
  int flagA=0;
  int flagB=0;
  for(i=0;i<n;i++){
    if(s[i]=='A' && cond[POS(f,i)]) flagA=1;
    if(s[i]=='B' && cond[POS(f,i)]) flagB=1;
  }
  printf("%s\n",flagA&&flagB?"Yes":"No");
}

int main(void){
  run();
  return 0;
}

