import java.util.HashSet;
import java.util.Set;




public class Main {


  static long inf = 100000000000L;

  private static void solve() {
    int n = ni();
    int m = ni();
    char[] s = ns();
    int[] from = new int[m];
    int[] to = new int[m];

    Set<int[]> edgeH = new HashSet<>();
    Set<Integer> edgeA = new HashSet<>();
    Set<Integer> edgeB = new HashSet<>();
    for (int i = 0; i < m; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;


      if (s[from[i]] == s[to[i]]) {
        if (s[from[i]] == 'A') {
          edgeA.add(from[i]);
          edgeA.add(to[i]);
        } else {
          edgeB.add(from[i]);
          edgeB.add(to[i]);
        }
      } else {
        if (s[from[i]] == 'B') {
          int tmp = from[i];
          from[i] = to[i];
          to[i] = tmp;
        }
        edgeH.add(new int[] {from[i], to[i]});
      }
    }
    int[][] g = packU(n, from, to);

    for (int[] e : edgeH) {
      int va = e[0];
      int vb = e[1];

      Set<Integer> setA = new HashSet<>();
      for (int v : g[va]) {
        if (s[v] == 'A') {
          setA.add(v);
        }
      }
      for (int v : g[vb]) {
        if (s[v] == 'B') {
          for (int u : g[v]) {
            if (setA.contains(u)) {
              System.out.println("Yes");
              return;
            }
          }
        }
      }
    }
    System.out.println("No");


  }

  static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
        p[f]++;
    for (int t : to)
        p[t]++;
    for (int i = 0; i < n; i++)
        g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
        g[from[i]][--p[from[i]]] = to[i];
        g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
}



