	static int INF = 1 << 30;
	static long LINF = 1L << 55;
	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	@SuppressWarnings("unchecked")
	static class TaskX {

		char[] s;
		int[] visited;
		List<Integer>[] g;
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			int m = in.nextInt();
			s = in.nextString().toCharArray();
			visited = new int[2*n];

			// 頂点倍化して(AABB)*の形の閉路が検出できる有向グラフの形にする
			g = new ArrayList[2*n];
			g = Stream.generate(ArrayList::new).limit(2*n).toArray(List[]::new);
			for (int i = 0; i < m; i++) {
				int a = in.nextInt()-1;
				int b = in.nextInt()-1;
				if (s[a] == s[b]) {
					g[a].add(b + n);
					g[b].add(a + n);
				} else {
					g[a + n].add(b);
					g[b + n].add(a);
				}
			}

			for (int i = 0; i < n; i++) {
				if (visited[i] != 1) dfs(i);
			}

			out.println("No");

		}

		void dfs(int i) {
			visited[i] = -1;
			for (int j : g[i]) {
				if (visited[j] == -1) {
					System.out.println("Yes");
					System.exit(0);
				} else if (visited[j] != 1) {
					dfs(j);
				}
			}
			visited[i] = 1;
		}
	}

