import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.PrimitiveIterator;
import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        int m = In.ni();
        char[] c = In.nc();
        boolean[] s = new boolean[n];
        for (int i = 0; i < n; i++) s[i] = c[i] == 'A';
        IntArrayList[] g = new IntArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new IntArrayList();
        int[][] in = new int[2][n];
        for (int i = 0; i < m; i++) {
            int u = In.ni() - 1;
            int v = In.ni() - 1;
            g[u].add(v);
            if (s[u]) in[0][v]++;
            else in[1][v]++;
            if (v != u) {
                g[v].add(u);
                if (s[v]) in[0][u]++;
                else in[1][u]++;
            }
        }
        boolean[] removed = new boolean[n];
        IntQueue z = new IntQueue(n);
        for (int i = 0; i < n; i++) if (in[0][i] == 0 || in[1][i] == 0) z.add(i);
        while (z.size() > 0) {
            int u = z.poll();
            removed[u] = true;
            g[u].iterator().forEachRemaining((int v) -> {
                if (!removed[v] && (s[u] && --in[0][v] == 0 || !s[u] && --in[1][v] == 0)) z.add(v);
            });
        }
        for (boolean rm : removed) {
            if (!rm) {
                out.append("Yes");
                return;
            }
        }
        out.append("No");
    }
}


