class Main{
	static class Node{
		int id;
		boolean A;
		int a=0, b=0;
		Node(int i, boolean a){id=i;A=a;};
		boolean banned = false;
	}

	static void solve(){
		int n=ni();
		int m =ni();
		String s = ns();
		List<Integer> edges[] = new List[n];
		for(int i=0;i<n;++i)edges[i]=new ArrayList<>();
		Node[] nodes = new Node[n];
		for(int i=0;i<n;++i)nodes[i] = new Node(i, s.charAt(i)=='A');
		for(int i=0;i<m;++i){
			int ss = ni()-1, t=ni()-1;
			edges[ss].add(t);edges[t].add(ss);
			if(nodes[t].A)nodes[ss].a++;
			else nodes[ss].b++;
			if(nodes[ss].A)nodes[t].a++;
			else nodes[t].b++;
		}
		int cnt = 0;
		Deque<Integer> que = new ArrayDeque<>();
		for(int i=0;i<n;++i){
			if(nodes[i].a==0 || nodes[i].b==0){
				que.addLast(i);
				++cnt;
				nodes[i].banned=true;
			}
		}
		while(!que.isEmpty()){
			int id = que.pollFirst();
			for(int u: edges[id]){
				if(nodes[u].banned)continue;
				if(nodes[id].A)nodes[u].a--;
				else nodes[u].b--;
				if(nodes[u].a==0 || nodes[u].b==0){
					++cnt;
					nodes[u].banned=true;
					que.addLast(u);
				}
			}
		}
		for(int i=0;i<n;++i)if(!nodes[i].banned){
			out.println("Yes");
			return;
		}
		out.println("No");
	} 




	 public static void main(String[] args){ 
		 solve(); 
		 out.flush(); 
	 } 
