/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        CABlandYard solver = new CABlandYard();
        solver.solve(1, in, out);
        out.close();
    }

    static class CABlandYard {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt(), m = in.nextInt();
            ArrayList<Set<Integer>> graph = new ArrayList<>();
            for (int i = 0; i < n; i++) graph.add(new HashSet<Integer>());
            String s = in.next();
            int[][] num = new int[n][2];
            for (int i = 0; i < m; i++) {
                int a = in.nextInt() - 1, b = in.nextInt() - 1;
                if (graph.get(a).contains(b)) continue;
                graph.get(a).add(b);
                num[a][s.charAt(b) - 'A']++;
                if (a != b) {
                    num[b][s.charAt(a) - 'A']++;
                    graph.get(b).add(a);
                }
            }
            TreeSet<Integer> q = new TreeSet<Integer>();
            for (int i = 0; i < n; i++) {
                int val = (num[i][0] > 0 ? 1 : 0) * 2 + (num[i][1] > 0 ? 1 : 0);
                q.add((val << 20) + i);
            }
            boolean[] done = new boolean[n];
            while (!q.isEmpty()) {
                int cur = q.first();
                q.remove(cur);
                int val = cur >>> 20;
                int node = cur & ((1 << 20) - 1);
                done[node] = true;
                if (val == 3) {
                    out.println("Yes");
                    break;
                }
                if (q.isEmpty()) {
                    out.println("No");
                    break;
                }
                int type = s.charAt(node) - 'A';
                for (Integer i : graph.get(node)) {
                    if (done[i]) continue;
                    int valueOld = (num[i][0] > 0 ? 1 : 0) * 2 + (num[i][1] > 0 ? 1 : 0);
                    q.remove((valueOld << 20) + i);
                    num[i][type]--;
                    int valueNew = (num[i][0] > 0 ? 1 : 0) * 2 + (num[i][1] > 0 ? 1 : 0);
                    q.add((valueNew << 20) + i);
                    graph.get(i).remove(node);
                }
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c;
            while (isSpaceChar(c = this.read())) {
                ;
            }

            StringBuilder result = new StringBuilder();
            result.appendCodePoint(c);

            while (!isSpaceChar(c = this.read())) {
                result.appendCodePoint(c);
            }

            return result.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void println(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
            writer.print('\n');
        }

        public void close() {
            writer.close();
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.InputMismatchException;
import java.util.List;
import java.util.StringTokenizer;
import java.util.stream.Stream;

public class Main {

	public static void main(String[] args) throws IOException {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskX solver = new TaskX();
		solver.solve(1, in, out);
		out.close();
	}

	static int INF = 1 << 30;
	static long LINF = 1L << 55;
	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	@SuppressWarnings("unchecked")
	static class TaskX {

		List<Integer>[] g;
		int[][] cnt;
		char[] s;
		boolean[] used;
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt(), m = in.nextInt();
			s = in.nextString().toCharArray();

			g = new ArrayList[n];
			g = Stream.generate(ArrayList::new).limit(n).toArray(List[]::new);

			cnt = new int[n][2];
			used = new boolean[n];
			for (int i = 0; i < m; i++) {
				int a = in.nextInt()-1, b = in.nextInt()-1;
				g[a].add(b);
				g[b].add(a);
				cnt[a][s[b]-'A']++;
				cnt[b][s[a]-'A']++;
			}

			boolean[] ok = new boolean[n];
			for (int i = 0; i < n; i++) {
				if (cnt[i][0] >= 1 && cnt[i][1] >= 1) {
					ok[i] = true;
				}
			}

			for (int i = 0; i < n; i++) {
				if (ok[i]) continue;
				dfs(i, ok);
			}

			for (boolean b : ok) {
				if (b) {
					out.println("Yes");
					return;
				}
			}

			out.println("No");
		}

		void dfs(int cur, boolean[] ok) {
			if (used[cur]) return;
			used[cur] = true;

			for (int to : g[cur]) {
				if (!ok[to]) continue;
				if (--cnt[to][s[cur]-'A'] == 0) {
					ok[to] = false;
					dfs(to, ok);
				}
			}
		}
	}

	static class InputReader {
		BufferedReader in;
		StringTokenizer tok;

		public String nextString() {
			while (!tok.hasMoreTokens()) {
				try {
					tok = new StringTokenizer(in.readLine(), " ");
				} catch (IOException e) {
					throw new InputMismatchException();
				}
			}
			return tok.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(nextString());
		}

		public long nextLong() {
			return Long.parseLong(nextString());
		}

		public double nextDouble() {
			return Double.parseDouble(nextString());
		}

		public int[] nextIntArray(int n) {
			int[] res = new int[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextInt();
			}
			return res;
		}

		public int[] nextIntArrayDec(int n) {
