    char[] s = ns();
    int[] from = new int[m];
    int[] to = new int[m];
    for (int i = 0; i < m; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
    }
    int[][] g = packU(n, from, to);
    for (int i = 0; i < n; i++) {
      if (s[i] == 'A') {
        boolean ret = dfs(i, 0, false, i, g, s);
        if (ret) {
          System.out.println("Yes");
          return;
        }
      }
    }
    System.out.println("No");
  }

  private static boolean dfs(int cur, int cs, boolean loop, int start, int[][] g, char[] s) {
    if (loop && cur == start) {
      return true;
    }
    for (int nex : g[cur]) {
      boolean ret = false;
      if (cs == 0 && s[nex] == 'A') {
        ret = dfs(nex, 1, false, start, g, s);
      } else if (cs == 1 && s[nex] == 'B') {
        ret = dfs(nex, 2, false, start, g, s);
      } else if (cs == 2 && s[nex] == 'B') {
        ret = dfs(nex, 3, false, start, g, s);
      } else if (cs == 3 && s[nex] == 'A') {
        ret = dfs(nex, 0, true, start, g, s);
      }
      if (ret) {
        return true;
      }
    }
    return false;
  }

  static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
      g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }

