                for (int j : graph[cur]) {
                    count[j][s[cur] - 'A']--;
                    if (count[j][s[cur] - 'A'] == 0 && !bad[j]) {
                        bad[j] = true;
                        q[tail++] = j;
                    }
                }
            }


            out.println(head < n ? "Yes" : "No");
        }

    }

    static class Utils {
        public static <T> List<T>[] listArray(int size) {
            List<T>[] result = new List[size];
            for (int i = 0; i < size; i++) {
                result[i] = new ArrayList<>();
            }
            return result;
        }

    }

