	}

	public void run() {
		Scanner sc = new Scanner();
		int N = sc.nextInt();
		int M = sc.nextInt();
		String str = sc.next();
		boolean[] col = new boolean[N];
		for (int i = 0; i < N; ++i) {
			col[i] = str.charAt(i) == 'A';
		}
		ArrayList<Integer>[] g = new ArrayList[N];
		for (int i = 0; i < N; ++i) {
			g[i] = new ArrayList<>();
		}
		ArrayDeque<Integer> dq = new ArrayDeque<>();
		ArrayDeque<Integer> ndq = new ArrayDeque<>();
		for (int i = 0; i < M; ++i) {
			int a = sc.nextInt() - 1;
			int b = sc.nextInt() - 1;
			g[a].add(b);
			g[b].add(a);
		}
		for (int i = 0; i < N; ++i) {
			if (col[i])
				dq.add(i);
		}
		int[] vis = new int[N];
		Arrays.fill(vis, -1);
		for (int i = 0; i <= 2 * N + 1; ++i) {
			while (!dq.isEmpty()) {
				int cur = dq.poll();
				for (int dst : g[cur]) {
					if (i % 2 == 0 && col[cur] == col[dst] && vis[dst] < i) {
						ndq.add(dst);
						vis[dst] = i;
					} else if (i % 2 == 1 && col[cur] != col[dst] && vis[dst] < i) {
						ndq.add(dst);
						vis[dst] = i;
					}
				}
			}
			dq.addAll(ndq);
			ndq.clear();
		}
		System.out.println(dq.size() > 0 ? "Yes" : "No");
	}

