import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Main {

  private static void solve() {
    int n = ni();
    int m = ni();
    char[] s = ns();
    int[] from = new int[m];
    int[] to = new int[m];

    int[][] cnt = new int[n][2];
    for (int i = 0; i < m; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;

      cnt[from[i]][s[to[i]] == 'A' ? 0 : 1]++;
      cnt[to[i]][s[from[i]] == 'A' ? 0 : 1]++;
    }
    int[][] g = packU(n, from, to);

    Set<Integer> cand = new HashSet<>();
    Set<Integer> rem = new HashSet<>();
    for (int i = 0; i < n; i++) {
      if (cnt[i][0] > 0 && cnt[i][1] > 0) {
        cand.add(i);
      } else {
        rem.add(i);
      }
    }

    Set<Integer> removed = new HashSet<>();
    while (rem.size() > 0) {
      List<Integer> newRem = new ArrayList<>();
      for (int v : rem) {
        int y = s[v] == 'A' ? 0 : 1;
        for (int u : g[v]) {
          if (cand.contains(u)) {
            cnt[u][y]--;

            if (cnt[u][y] == 0) {
              cand.remove(u);
              newRem.add(u);
            }
          }
        }
        removed.add(v);
      }
      rem.clear();

      for (int v : newRem) {
        if (!removed.contains(v)) {
          rem.add(v);
        }
      }
    }

    System.out.println(cand.size() > 0 ? "Yes" : "No");
  }


  static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
      g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }

