        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        char[] s = in.nextToken().toCharArray();
        int[] ab = new int[n];
        for (int i = 0; i < s.length; i++) {
            ab[i] = s[i] == 'A' ? 0 : 1;
        }

        List<Integer>[] graph = new List[n];
        for (int i = 0; i < n ; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int i = 0; i < m ; i++) {
            int a = in.nextInt()-1;
            int b = in.nextInt()-1;
            if (a != b) {
                graph[a].add(b);
                graph[b].add(a);
            } else {
                graph[a].add(a);
            }
        }

        boolean isOK = false;
        int[] que = new int[32*n*3];
        int[][] dp = new int[2][n];
        for (int i = 0; i < n ; i++) {
            int cur = i+1;
            if (ab[i] == 0 && dp[0][i] == 0) {
                dp[0][i] = cur;
                int qh = 0;
                int qt = 0;
                que[qh++] = 0;
                que[qh++] = i;
                while (qt < qh) {
                    int par = que[qt++];
                    int now = que[qt++];
                    for (int to : graph[now]) {
                        if (ab[to] != ab[now]) {
                            if (par == 1) {
                                int tp = 0;
                                if (dp[tp][to] == 0) {
                                    dp[tp][to] = cur;
                                    que[qh++] = tp;
                                    que[qh++] = to;
                                } else {
                                    if (ab[now] == 1 && ab[to] == 0 && dp[0][to] == cur) {
                                        isOK = true;
                                    }
                                }
                            }
                        } else {
                            if (par == 0) {
                                int tp = par ^ 1;
                                if (dp[tp][to] == 0) {
                                    dp[tp][to] = 1;
                                    que[qh++] = tp;
                                    que[qh++] = to;
                                }
                            }
                        }
                    }
                }
            }
        }


        out.println(isOK ? "Yes" : "No");
