    public static class Task {
        int N, M;
        int[] value;
        List<Integer>[] edges;
        int[] state;
        int[][] color;
        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            N = sc.nextInt();
            M = sc.nextInt();
            value = new int[N];
            String s = sc.next();
            for (int i = 0; i < N; i++) {
                value[i] = s.charAt(i) - 'A';
            }
            edges = new List[N];
            for (int i = 0; i < N; i++) {
                edges[i] = new ArrayList<>();
            }
            color = new int[N][2];
            for (int i = 0; i < M; i++) {
                int a = sc.nextInt() - 1;
                int b = sc.nextInt() - 1;
                edges[a].add(b);
                edges[b].add(a);
                color[a][value[b]]++;
                color[b][value[a]]++;
            }
            state = new int[N];
            for (int i = 0; i < N; i++) {
                if (state[i] == 0 && (color[i][0] == 0 || color[i][1] == 0)) {
                    dfs(i);
                }
            }
            for (int i = 0; i < N; i++) {
                if (state[i] == 0) {
                    pw.println("Yes");
                    return;
                }
            }
            pw.println("No");

        }

        public void dfs(int u) {
            state[u] = 1;
            for (int v: edges[u]) {
                color[v][value[u]]--;
                if (color[v][value[u]] == 0 && state[v] == 0) {
                    dfs(v);
                }
            }
            state[u] = 2;
        }
    }

