        X = new int[M];
        Y = new int[M];
        for (int i = 0; i < M; i++) {
            X[i] = sc.nextInt()-1;
            Y[i] = sc.nextInt()-1;
        }

        System.out.println( solve() ? "Yes" : "No" );
    }

    static boolean solve() {
        List<Edge> AE = new ArrayList<>();
        List<Edge> BE = new ArrayList<>();
        List<Edge> ABE = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int x = X[i];
            int y = Y[i];

            if( S.charAt(x) == 'A' && S.charAt(y) == 'A' ) {
                AE.add( new Edge(x, y) );

            } else if(S.charAt(x) == 'B' && S.charAt(y) == 'B') {
                BE.add( new Edge(x, y) );

            } else {
                if( S.charAt(x) == 'A' ) {
                    ABE.add( new Edge(x, y) );
                } else {
                    ABE.add( new Edge(y, x) );
                }
            }
        }

        int[][] GA = adjB(N, AE);
        int[][] GB = adjB(N, BE);
        int[][] GAB = adjB(N, ABE);


        for (int i = 0; i < N; i++) {
            if( S.charAt(i) == 'A' && check(i, GA, GB, GAB) ) return true;
        }

        return false;
    }

    static ArrayDeque<State> q = new ArrayDeque<>();

    static boolean check(int a, int[][] GA, int[][] GB, int[][] GAB) {
        q.add(new State(a, 0));

        while( !q.isEmpty() ) {
            State s = q.poll();

            if( s.d == 0 ) {
                // a -> aa
                for (int aa : GA[s.a]) {
                    q.add( new State(aa, 1) );
                }

            } else if( s.d == 1 ) {
                // aa -> bb
                for (int bb : GAB[s.a]) {
                    q.add( new State(bb, 2) );
                }

            } else if( s.d == 2 ) {
                // bb -> b
                for (int b : GB[s.a]) {
                    q.add(new State(b, 3));
                }

            } else if( s.d == 3 ) {
                // b -> a
                for (int ra : GAB[s.a]) {
                    if( ra == a ) return true;
                }
            }
        }
        return false;
    }

    static class State {
        int a;
        int d;

        public State(int a, int d) {
            this.a = a;
            this.d = d;
        }
    }

    static int[][] adjB(int n, List<Edge> edges) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (Edge e : edges) {
            cnt[e.x]++;
        }
        for (Edge e : edges) {
            cnt[e.y]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (Edge e : edges) {
            adj[e.x][--cnt[e.x]] = e.y;
            adj[e.y][--cnt[e.y]] = e.x;
        }
        return adj;
    }

    static int[][] adjD(int n, List<Edge> es) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];

        for (Edge e : es) {
            cnt[e.x]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (Edge e : es) {
            adj[e.x][--cnt[e.x]] = e.y;
        }
        return adj;
    }

    static class Edge {
        int x;
        int y;

        public Edge(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
