import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    static long __startTime = System.currentTimeMillis();

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        char[] s = in.nextToken().toCharArray();
        int[] ab = new int[n];
        for (int i = 0; i < s.length; i++) {
            ab[i] = s[i] == 'A' ? 0 : 1;
        }

        List<Integer>[] graph = new List[n];
        for (int i = 0; i < n ; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int i = 0; i < m ; i++) {
            int a = in.nextInt()-1;
            int b = in.nextInt()-1;
            if (a != b) {
                graph[a].add(b);
                graph[b].add(a);
            } else {
                graph[a].add(a);
            }
        }

        List<Integer>[] dg2 = new List[2*n];
        for (int i = 0; i < dg2.length ; i++) {
            dg2[i] = new ArrayList<>();
        }
        for (int i = 0; i < n ; i++) {
            for (int j : graph[i]) {
                if (ab[i] == ab[j]) {
                    dg2[i].add(n+j);
                    dg2[j].add(n+i);
                } else {
                    dg2[n+i].add(j);
                    dg2[n+j].add(i);
                }
            }
        }

        out.println(toposort(dg2) == null ? "Yes" : "No");
        out.flush();
    }

    static int[] toposort(List<Integer>[] graph) {
        int n = graph.length;
        int[] in = new int[n];
        for (int i = 0 ; i < n ; i++) {
            for (int t : graph[i]) {
                in[t]++;
            }
        }

        Queue<Integer> q = new PriorityQueue<>();
        int[] res = new int[n];
        for (int i = 0 ; i < n ; i++) {
            if (in[i] == 0) {
                q.add(i);
            }
        }

        int idx = 0;
        while (q.size() >= 1) {
            int now = q.poll();
            res[idx++] = now;
            for (int t : graph[now]) {
                in[t]--;
                if (in[t] == 0) {
                    q.add(t);
                }
            }
        }
        for (int i = 0 ; i < n ; i++) {
            if (in[i] >= 1) {
                return null;
            }
        }
        return res;
    }




