  static class TaskC {

    ArrayList<Integer>[] g;
    int[] ca;
    int[] cb;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
      int n = in.nextInt();
      int m = in.nextInt();
      char[] s = in.nextToken().toCharArray();
      g = new ArrayList[n];
      for (int i = 0; i < n; ++i) {
        g[i] = new ArrayList<>();
      }
      for (int i = 0; i < m; ++i) {
        int x = in.nextInt() - 1;
        int y = in.nextInt() - 1;
        g[x].add(y);
        g[y].add(x);
      }
      ca = new int[n];
      cb = new int[n];
      for (int i = 0; i < n; ++i) {
        for (int x : g[i]) {
          if (s[x] == 'A') {
            ++ca[i];
          } else {
            ++cb[i];
          }
        }
      }
      boolean[] bad = new boolean[n];
      int[] q = new int[n + 10];
      int ql = 0, qr = 0;
      for (int i = 0; i < n; ++i) {
        if (ca[i] == 0 || cb[i] == 0) {
          bad[i] = true;
          q[ql++] = i;
        }
      }
      while (ql > qr) {
        int x = q[qr++];
        for (int y : g[x]) {
          if (s[x] == 'A') {
            --ca[y];
          } else {
            --cb[y];
          }
          if (!bad[y] && (ca[y] == 0 || cb[y] == 0)) {
            bad[y] = true;
            q[ql++] = y;
          }
        }
      }
      out.printLine(bad[0] ? "No" : "Yes");
    }

  }

