		}
		for(int _i=0; _i<m; _i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			es.get(a).add(b);
			es.get(b).add(a);
			if(s[a]=='A') {
				degA[b]++;
			} else {
				degB[b]++;
			}
			if(s[b]=='A') {
				degA[a]++;
			} else {
				degB[a]++;
			}
		}
		ArrayDeque<Integer> q = new ArrayDeque<>();
		boolean[] removed = new boolean[n+1];
		for(int i=1; i<=n; i++) {
