import java.util.ArrayDeque;
import java.util.Queue;

public class Main {

  private static void solve() {
    int n = ni();
    int m = ni();
    char[] s = ns();
    int[] from = new int[m];
    int[] to = new int[m];
    int[][] deg = new int[n][2];
    for (int i = 0; i < m; i ++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
      deg[to[i]][s[from[i]] - 'A'] ++;
      deg[from[i]][s[to[i]] - 'A'] ++;
    }
    int[][] g = packU(n, from, to);

    Queue<Integer> q = new ArrayDeque<>();
    boolean[] removed = new boolean[n];
    int cnt = 0;
    for (int i = 0; i < n; i ++) {
      if (deg[i][0] == 0 || deg[i][1] == 0) {
        q.add(i);
        removed[i] = true;
        cnt ++;
      }
    }

    while (q.size() > 0) {
      int v = q.poll();
      for (int u : g[v]) {
        deg[u][s[v] - 'A'] --;
        if (deg[u][0] == 0 || deg[u][1] == 0) {
          if (!removed[u]) {
            removed[u] = true;
            q.add(u);
            cnt ++;
          }
        }
      }
    }
    System.out.println(cnt == n ? "No" : "Yes");

  }

  private static void dfs(int n, int[][] g, int[][] cnt, char[] s, boolean[] visited) {
    visited[n] = true;
    if (cnt[n][0] == 0 || cnt[n][1] == 0) {

      for (int next : g[n]) {
        if (cnt[next][0] == 0 && cnt[next][1] == 0) {
          continue;
        }
        cnt[next][s[n] - 'A'] --;
        cnt[n][s[next] - 'A'] --;

        if (cnt[next][0] > 0 || cnt[next][1] > 0) {
          visited[next] = false;
        }
      }
    }


    for (int next : g[n]) {
      if (visited[next]) {
        continue;
      }
      dfs(next, g, cnt, s, visited);
    }
  }

  public static int[][] packU(int n, int[] from, int[] to){ return packU(n, from, to, from.length); }
  public static int[][] packU(int n, int[] from, int[] to, int sup)
  {
      int[][] g = new int[n][];
      int[] p = new int[n];
      for(int i = 0;i < sup;i++)p[from[i]]++;
      for(int i = 0;i < sup;i++)p[to[i]]++;
      for(int i = 0;i < n;i++)g[i] = new int[p[i]];
      for(int i = 0;i < sup;i++){
          g[from[i]][--p[from[i]]] = to[i];
          g[to[i]][--p[to[i]]] = from[i];
      }
      return g;
  }

