/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author prakharjain
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        agc027c solver = new agc027c();
        solver.solve(1, in, out);
        out.close();
    }

    static class agc027c {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            String s = in.next();

            DsuInteger dsu = new DsuInteger(n);

            for (int i = 0; i < n; i++) {
                dsu.createSet(i);
            }

            int[] isa = new int[n];
            int[] isb = new int[n];

            List[] g = new List[n];

            for (int i = 0; i < n; i++) {
                g[i] = new ArrayList();
            }

            boolean[] iss = new boolean[n];

            int ca = 0, cb = 0;
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;

                if (u == v) {
                    iss[u] = true;
                    if (s.charAt(u) == 'A') {
                        isa[u]++;
                    } else {
                        isb[u]++;
                    }
                    continue;
                }

                if (s.charAt(u) == 'A') {
                    isa[v]++;
                } else {
                    isb[v]++;
                }

                if (s.charAt(v) == 'A') {
                    isa[u]++;
                } else {
                    isb[u]++;
                }

                g[u].add(v);
                g[v].add(u);
            }

            ArrayDeque<Integer> dq = new ArrayDeque<>();

            for (int i = 0; i < n; i++) {
                if (isa[i] == 0 || isb[i] == 0) {
                    dq.addLast(i);
                }
            }

            boolean[] isd = new boolean[n];
            while (dq.size() > 0) {
                int ele = dq.removeFirst();

                isd[ele] = true;

                char ch = s.charAt(ele);

                for (int v : (List<Integer>) g[ele]) {
                    if (!isd[v]) {
                        if (ch == 'A') {
                            isa[v]--;
                            if (isa[v] <= 0) {
                                dq.addLast(v);
                            }
                        } else {
                            isb[v]--;
                            if (isb[v] <= 0) {
                                dq.addLast(v);
                            }
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                if (!isd[i]) {
                    if (s.charAt(i) == 'A') {
                        ca++;
                        if (iss[i])
                            ca++;
                    } else {
                        cb++;
                        if (iss[i])
                            cb++;
                    }
                }
            }

            if (ca >= 2 && cb >= 2) {
                out.println("Yes");
            } else {
                out.println("No");
            }

        }

        class DsuInteger {
            int[] parent;
            int[] rank;
            int n;

            public DsuInteger(int n) {
                this.n = n;
                this.parent = new int[n];
                this.rank = new int[n];
            }

            int createSet(int x) {
                parent[x] = x;
                rank[x] = 0;
                return x;
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public String next() {
            return nextString();
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;

public class Main {
	static int n, m;
	static char[] s;
	static List<List<Integer>> list;
	static boolean[][] ng;

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] sa = br.readLine().split(" ");
		n = Integer.parseInt(sa[0]);
		m = Integer.parseInt(sa[1]);
		s = br.readLine().toCharArray();
		list = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			list.add(new ArrayList<>());
		}
		for (int i = 0; i < m; i++) {
			sa = br.readLine().split(" ");
			int a = Integer.parseInt(sa[0]) - 1;
			int b = Integer.parseInt(sa[1]) - 1;
			list.get(a).add(b);
			if (a != b) {
				list.get(b).add(a);
			}
		}
		br.close();

		ng = new boolean[n][2];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < 2; j++) {
				if (!ng[i][j]) {
					if (dfs(i * 10 + j, new LinkedHashSet<>())) {
						System.out.println("Yes");
						return;
					}
				}
			}
		}
		System.out.println("No");
	}

	static boolean dfs(int x, LinkedHashSet<Integer> his) {
		int cur = x / 10;
		int t = x % 10;
		char nc = s[cur];
		if (t == 1) {
			nc = (char) ('A' + 'B' - s[cur]);
		}
		int nt = 1 - t;
		for (int next : list.get(cur)) {
			if (s[next] == nc) {
				int nx = next * 10 + nt;
				if (his.contains(nx)) {
					return true;
				}
				if (!ng[next][nt]) {
					his.add(nx);
					if (dfs(nx, his)) {
						return true;
					}
					his.remove(nx);
				}
			}
		}
		ng[cur][t] = true;
		return false;
	}
}

