import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[] s = in.nextChars();

            List<Integer>[] g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

            int[] deg1 = new int[n];
            int[] deg2 = new int[n];
            for (int i = 0; i < m; i++) {
                int a = in.nextInt() - 1;
                int b = in.nextInt() - 1;
                if (s[a] == s[b]) {
                    deg1[a]++;
                    deg1[b]++;
                } else {
                    deg2[a]++;
                    deg2[b]++;
                }
                g[a].add(b);
                g[b].add(a);
            }

            boolean[] vis = new boolean[n];
            Queue<Integer> que = new ArrayDeque<>();
            for (int r = 0; r < n; r++)
                if (deg2[r] == 0 || deg1[r] == 0) {
                    que.add(r);
                    vis[r] = true;
                }
            while (!que.isEmpty()) {
                int a = que.poll();
                for (int b : g[a]) {
                    if (s[a] == s[b]) {
                        deg1[a]--;
                        deg1[b]--;
                    } else {
                        deg2[a]--;
                        deg2[b]--;
                    }
                    if (!vis[b] && (deg1[b] == 0 || deg2[b] == 0)) {
                        vis[b] = true;
                        que.add(b);
                    }
                }
            }
            boolean ok = false;
            for (boolean b : vis) ok |= !b;
            out.println(ok ? "Yes" : "No");
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        public char[] nextChars() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            return Arrays.copyOf(str, len);
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

public class Main {

  private static void solve() {
    int n = ni();
    int m = ni();
    char[] s = ns();
    int[] from = new int[m];
    int[] to = new int[m];
    int[][] cnt = new int[n][2];
    for (int i = 0; i < m; i ++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;

      if (s[from[i]] == 'A') {
        cnt[to[i]][0] ++;
      } else {
        cnt[to[i]][1] ++;
      }
      if (s[to[i]] == 'A') {
        cnt[from[i]][0] ++;
      } else {
        cnt[from[i]][1] ++;
      }
    }
    int[][] g = packU(n, from, to);

    boolean[] visited = new boolean[n];
    for (int i = 0; i < n; i ++) {
      dfs(i, g, cnt, s, visited);
    }

    for (int i = 0; i < n; i ++) {
      if (cnt[i][0] > 0) {
        System.out.println("Yes");
        return;
      }
    }
    System.out.println("No");

  }

  private static void dfs(int n, int[][] g, int[][] cnt, char[] s, boolean[] visited) {
    visited[n] = true;
    if (cnt[n][0] == 0 || cnt[n][1] == 0) {

      for (int next : g[n]) {
        if (cnt[next][0] == 0 && cnt[next][1] == 0) {
          continue;
        }
        cnt[next][s[n] - 'A'] --;
        cnt[n][s[next] - 'A'] --;

        if (cnt[next][0] > 0 || cnt[next][1] > 0) {
          visited[next] = false;
        }
      }
    }


    for (int next : g[n]) {
      if (visited[next]) {
        continue;
      }
      dfs(next, g, cnt, s, visited);
    }
  }

  public static int[][] packU(int n, int[] from, int[] to){ return packU(n, from, to, from.length); }
  public static int[][] packU(int n, int[] from, int[] to, int sup)
  {
      int[][] g = new int[n][];
      int[] p = new int[n];
      for(int i = 0;i < sup;i++)p[from[i]]++;
      for(int i = 0;i < sup;i++)p[to[i]]++;
      for(int i = 0;i < n;i++)g[i] = new int[p[i]];
      for(int i = 0;i < sup;i++){
          g[from[i]][--p[from[i]]] = to[i];
          g[to[i]][--p[to[i]]] = from[i];
      }
      return g;
  }

