class Graph {
	Node ns;
	Node nsLast;
	int numNodes;

	Graph() {
		ns = null;
		numNodes = 0;
	}

	void addNode(Node n) {
		if (ns == null) {
			ns = nsLast = n;
		} else {
			nsLast.next = n;
			n.prev = nsLast;
			nsLast = n;
		}
		numNodes++;
	}

	void addEdge(Node n1, Node n2) {
		if (n1 == n2) { // loop
			n1.counts[n1.label]++;
			return;
		}
		Edge e12 = new Edge(n2);
		Edge e21 = new Edge(n1);
		e12.other = e21;
		e21.other = e12;
		n1.addEdge(e12);
		n2.addEdge(e21);
	}

	void removeNode(Node n, Set<Node> affected) {
		if (n.removed)
			throw new RuntimeException("ha?");
		if (n.prev != null)
			n.prev.next = n.next;
		if (n.next != null)
			n.next.prev = n.prev;
		if (n == ns)
			ns = ns.next;
		if (n == nsLast)
			nsLast = nsLast.prev;
		Edge e = n.es;
		Node from = n;
		while (e != null) {
			Edge next = e.next;
			Node to = e.to;
			Edge other = e.other;
			from.removeEdge(e);
			to.removeEdge(other); // remove edges connected

			if (to.counts[0] == 0 || to.counts[1] == 0) {
				affected.add(to); // next deletion
			}

			e = next;
		}
		n.removed = true;
		numNodes--;
	}
}

class Node {
	static int id = 0;
	int hash;
	int label; // 0: A, 1: B
	int[] counts;
	Edge es;
	Edge esLast;
	Node prev;
	Node next;
	boolean removed;

	Node(boolean isA) {
		label = isA ? 0 : 1;
		counts = new int[2];
		hash = ++id;
	}

	void addEdge(Edge e) {
		if (es == null) {
			es = esLast = e;
		} else {
			esLast.next = e;
			e.prev = esLast;
			esLast = e;
		}
		counts[e.to.label]++;
	}

	void removeEdge(Edge e) {
		if (e.prev != null)
			e.prev.next = e.next;
		if (e.next != null)
			e.next.prev = e.prev;
		if (e == es)
			es = es.next;
		if (e == esLast)
			esLast = esLast.prev;
		counts[e.to.label]--;
	}

	public int hashCode() {
		return hash;
	}

	@Override
	public String toString() {
		String res = "[id:" + hash + " counts:{" + counts[0] + "," + counts[1] + "} conn:{";
		Edge e = es;
		while (e != null) {
			res += e.to.hash + ",";
			e = e.next;
		}
		res += "}]";
		return res;
	}
}

class Edge {
	Node to;
	Edge other;
	Edge prev;
	Edge next;

	Edge(Node to) {
		this.to = to;
	}
}

