            int x = X[i];
            int y = Y[i];

            if( x == y ) {
                if( S.charAt(x) == 'A' ) {
                    A[x]++;
                } else {
                    B[x]++;
                }

            } else {
                (S.charAt(y) == 'A' ? A : B)[x]++;
                (S.charAt(x) == 'A' ? A : B)[y]++;
            }
        }

        int last = N;
        ArrayDeque<Integer> bads = new ArrayDeque<>();
        boolean[] done = new boolean[N];
        for (int i = 0; i < N; i++) {
            if( A[i] == 0 || B[i] == 0 ) {
                bads.add(i);
                done[i] = true;
            }
        }

        while(!bads.isEmpty()) {
            int bad = bads.poll();
            boolean is_a = S.charAt(bad) == 'A';
            for (int i : G[bad]) {
                if( done[i] ) continue;

                (is_a ? A : B)[i]--;

                if( A[i] == 0 || B[i] == 0 ) {
                    bads.add(i);
                    done[i] = true;
                }
            }
            last--;
        }

        return last > 0;
    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

