public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        int m = In.ni();
        char[] c = In.nc();
        boolean[] s = new boolean[n + 2];
        for (int i = 0; i < n; i++) s[i] = c[i] == 'A';
        s[n] = true;
        IntArrayList[] g = new IntArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new IntArrayList();
        UnionFindTree t = new UnionFindTree(n);
        for (int i = 0; i < m; i++) {
            int u = In.ni() - 1;
            int v = In.ni() - 1;
            g[u].add(v);
            if (v != u) {
                g[v].add(u);
                t.unite(u, v);
            }
        }
        boolean[] set = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (t.isRoot(i) && (dfs(g, i, n, s, set) > 0 || dfs(g, i, n + 1, s, set) > 0)) {
                out.append("Yes");
                return;
            }
        }
        out.append("No");
    }

    public static int dfs(IntArrayList[] g, int u, int p, boolean[] s, boolean[] set) {
        set[u] = true;
        PrimitiveIterator.OfInt it = g[u].iterator();
        while (it.hasNext()) {
            int v = it.nextInt();
            if (s[v] ^ s[p] && (set[v] && v != u || dfs(g, v, u, s, set) > 0)) return 1;
        }
        set[u] = false;
        return -1;
    }
}


