import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.PrimitiveIterator;
import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;

public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        int m = In.ni();
        char[] c = In.nc();
        boolean[] s = new boolean[n + 2];
        for (int i = 0; i < n; i++) s[i] = c[i] == 'A';
        s[n] = true;
        IntArrayList[] g = new IntArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new IntArrayList();
        UnionFindTree t = new UnionFindTree(n);
        for (int i = 0; i < m; i++) {
            int u = In.ni() - 1;
            int v = In.ni() - 1;
            g[u].add(v);
            if (v != u) {
                g[v].add(u);
                t.unite(u, v);
            }
        }
        boolean[] set = new boolean[n];
        int[] next = new int[n];
        int[] prev = new int[n];
        for (int i = 0; i < n; i++) {
            if (t.isRoot(i)){
                if (dfs(g, i, n, s, set, next, prev) > 0) {
                    out.append("Yes");
                    return;
                }
                if (dfs(g, i, n + 1, s, set, next, prev) > 0) {
                    out.append("Yes");
                    return;
                }
            }
        }
        out.append("No");
    }

    public static int dfs(IntArrayList[] g, int u, int p, boolean[] s, boolean[] set, int[] next, int[] prev) {
        prev[u] = p;
        set[u] = true;
        PrimitiveIterator.OfInt it = g[u].iterator();
        while (it.hasNext()) {
            int v = it.nextInt();
            next[u] = v;
            if (s[v] ^ s[p]){
                if (set[v] && v != u) {
                    if (prev[v] == v) {
                        if (s[v] ^ s[u]) return 1;
                    } else {
                        if (s[next[v]] ^ s[u]) return 1;
                    }
                } else if (dfs(g, v, u, s, set, next, prev) > 0) {
                    return 1;
                }
            }
        }
        set[u] = false;
        return -1;
    }
}


