	@SuppressWarnings("unchecked")
	static class TaskX {

		List<Integer>[] g;
		int[][] cnt;
		char[] s;
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt(), m = in.nextInt();
			s = in.nextString().toCharArray();

			g = new ArrayList[n];
			g = Stream.generate(ArrayList::new).limit(n).toArray(List[]::new);

			cnt = new int[n][2];
			for (int i = 0; i < m; i++) {
				int a = in.nextInt()-1, b = in.nextInt()-1;
				if (a != b) {
					g[a].add(b);
					g[b].add(a);
					cnt[a][s[b]-'A']++;
					cnt[b][s[a]-'A']++;
				} else {
					g[a].add(b);
					cnt[a][s[b]-'A']++;
				}
			}

			boolean[] used = new boolean[n];
			for (int cur = 0; cur < n; cur++) {

				if (cnt[cur][0] >= 1 && cnt[cur][1] >= 1) continue;
				dfs(cur, used);

			}

			long ans = 0;
			for (int i = 0; i < n; i++) {
				if (cnt[i][0] <= 0 && cnt[i][1] <= 0) ans++;
			}

			out.println(ans == n ? "No" : "Yes");
		}

		void dfs(int cur, boolean[] used) {
			used[cur] = true;
			for (int to : g[cur]) {
				cnt[to][s[cur]-'A']--;
				if (used[to]) continue;
				if (cnt[to][0] >= 1 && cnt[to][1] >= 1) continue;
				dfs(to, used);
			}
		}
	}

