                    if (vert[connection].Version == currentVersion)
                    {
                        //求めているletterと一致していたら
                        if (vert[connection].Letter == currentPos.Item2)
                        {
                            //現在の場所の文字と求めている文字が違ったら(つまり問答無用でokな奴)
                            if (vert[currentPos.Item1].Letter != currentPos.Item2)
