using System;
using System.Collections.Generic;
using System.Linq;

public class Program
{
    private int N, M;
    private char[] S;
    private HashSet<int>[] ToA, ToB;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        S = sc.Next().ToCharArray();
        ToA = new HashSet<int>[N];
        ToB = new HashSet<int>[N];
        for (int i = 0; i < N; i++)
        {
            ToA[i] = new HashSet<int>();
            ToB[i] = new HashSet<int>();
        }

        for (int i = 0; i < M; i++)
        {
            int a = sc.NextInt() - 1;
            int b = sc.NextInt() - 1;
            if (S[a] == 'A')
            {
                ToA[b].Add(a);
            }
            else if (S[a] == 'B')
            {
                ToB[b].Add(a);
            }

            if (S[b] == 'A')
            {
                ToA[a].Add(b);
            }
            else if (S[b] == 'B')
            {
                ToB[a].Add(b);
            }
        }

        /*
         * a--b
         * |  |
         * a--b があるかどうか
         */
        // AへとBへの辺が両方ある頂点だけ残す
        // 上のがあるかどうか -> 頂点が1個以上残るか

        bool[] rm = new bool[N];
        var stack = new Stack<int>();
        for (int i = 0; i < N; i++)
        {
            if (ToA[i].Count == 0 || ToB[i].Count == 0)
            {
                stack.Push(i);
            }
        }

        while (stack.Count > 0)
        {
            int pop = stack.Pop();
            rm[pop] = true;
            HashSet<int> ls = new HashSet<int>();
            var arToA = ToA[pop].ToArray();
            var arToB = ToB[pop].ToArray();
            foreach (var i in arToA)
            {
                ToA[i].Remove(pop);
                ToB[i].Remove(pop);
                if (ToA[i].Count == 0 || ToB[i].Count == 0)
                {
                    ls.Add(i);
                }
            }

            foreach (var i in arToB)
            {
                ToA[i].Remove(pop);
                ToB[i].Remove(pop);
                if (ToA[i].Count == 0 || ToB[i].Count == 0)
                {
                    ls.Add(i);
                }
            }

            foreach (int i in ls)
            {
                stack.Push(i);
            }
        }

        Console.WriteLine(rm.Any(f => !f) ? "Yes" : "No");
    }


    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

#region PriorityQueue

/// <summary>
/// 指定した型のインスタンスを最も価値が低い順に取り出すことが可能な可変サイズのコレクションを表します．
/// </summary>
/// <typeparam name="T">優先度付きキュー内の要素の型を指定します．</typeparam>
/// <remarks>内部的にはバイナリヒープによって実装されています．</remarks>
public class PriorityQueue<T>
{
    readonly List<T> heap = new List<T>();
    readonly Comparison<T> cmp;

    /// <summary>
    /// デフォルトの比較子を使用してインスタンスを初期化します．
    /// </summary>
    /// <remarks>この操作は O(1) で実行されます．</remarks>
    public PriorityQueue()
    {
        cmp = Comparer<T>.Default.Compare;
    }

    /// <summary>
    /// デリゲートで表されるような比較関数を使用してインスタンスを初期化します．
    /// </summary>
    /// <param name="comparison"></param>
    /// <remarks>この操作は O(1) で実行されます．</remarks>
    public PriorityQueue(Comparison<T> comparison)
    {
        cmp = comparison;
    }

    /// <summary>
    /// 指定された比較子を使用してインスタンスを初期化します．
    /// </summary>
    /// <param name="comparer"></param>
    /// <remarks>この操作は O(1) で実行されます．</remarks>
    public PriorityQueue(IComparer<T> comparer)
    {
        cmp = comparer.Compare;
    }

    /// <summary>
    /// 優先度付きキューに要素を追加します．
    /// </summary>
    /// <param name="item">優先度付きキューに追加される要素</param>
    /// <remarks>最悪計算量 O(log N) で実行されます．</remarks>
    public void Enqueue(T item)
    {
        var pos = heap.Count;
        heap.Add(item);
        while (pos > 0)
        {
            var par = (pos - 1) / 2;
            if (cmp(heap[par], item) <= 0)
                break;
            heap[pos] = heap[par];
            pos = par;
        }

        heap[pos] = item;
    }

    /// <summary>
    /// 優先度付きキューから最も価値が低い要素を削除し，返します．
    /// </summary>
    /// <returns>優先度付きキューから削除された要素．</returns>
    /// <remarks>最悪計算量 O(log N) で実行されます．</remarks>
    public T Dequeue()
    {
        var ret = heap[0];
        var pos = 0;
        var x = heap[heap.Count - 1];

        while (pos * 2 + 1 < heap.Count - 1)
        {
            var lch = pos * 2 + 1;
            var rch = pos * 2 + 2;
            if (rch < heap.Count - 1 && cmp(heap[rch], heap[lch]) < 0) lch = rch;
            if (cmp(heap[lch], x) >= 0)
                break;
            heap[pos] = heap[lch];
            pos = lch;
        }

        heap[pos] = x;
        heap.RemoveAt(heap.Count - 1);
        return ret;
    }

    /// <summary>
    ///  優先度付きキューに含まれる最も価値が低い要素を削除せずに返します．
    /// </summary>
    /// <returns>優先度付きキューに含まれる最も価値が低い要素．</returns>
    /// <remarks>この操作は O(1) で実行されます．</remarks>
    public T Peek()
    {
        return heap[0];
    }

    /// <summary>
    /// 優先度付きキュー内の要素の数を取得します．
    /// </summary>
    /// <returns>優先度付キュー内にある要素の数</returns>
    /// <remarks>最悪計算量 O(1) で実行されます．</remarks>
    public int Count
    {
        get { return heap.Count; }
    }

    /// <summary>
    /// 優先度付きキュー内に要素が存在するかどうかを O(1) で判定します．
    /// </summary>
    /// <returns>優先度付キュー内にある要素が存在するならば true，そうでなければ　false．</returns>
    /// <remarks>この操作は O(1) で実行されます．</remarks>
    public bool Any()
    {
        return heap.Count > 0;
    }

    /// <summary>
    /// 優先度付きキューに含まれる要素を昇順に並べて返します．
    /// </summary>
    /// <remarks>この操作は計算量 O(N log N)で実行されます．</remarks>
    public T[] Items
    {
        get
        {
            var ret = heap.ToArray();
            Array.Sort(ret, cmp);
            return ret;
        }
    }
}

#endregion

class HashMap<K, V> : Dictionary<K, V>
{
    new public V this[K i]
    {
        get
        {
            V v;
            return TryGetValue(i, out v) ? v : base[i] = default(V);
        }
        set { base[i] = value; }
    }
}

