public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int M = GetInt();
		string s = GetString();

		var adj = Enumerable.Range(0, N).Select(_ => new List<int>()).ToArray();
		for(int i = 0; i < M; i++)
		{
			int a = GetInt() - 1;
			int b = GetInt() - 1;
			adj[a].Add(b);
			adj[b].Add(a);
		}

		int[] degA = new int[N];
		int[] degB = new int[N];
		for(int v = 0; v < N; v++)
		{
			int[] deg = (s[v] == 'A') ? degA : degB;
			foreach(int u in adj[v])
				deg[u]++;				
		}

		var queue = new Queue<int>();
		for(int v = 0; v < N; v++)
		{
			if(degA[v] == 0 || degB[v] == 0)
				queue.Enqueue(v);
		}

		bool[] deleted = new bool[N];
		while(queue.Count > 0)
		{
			int v = queue.Dequeue();
			deleted[v] = true;

			int[] deg = (s[v] == 'A') ? degA : degB;
			foreach(int u in adj[v])
			{
				if(deleted[u])
					continue;

				deg[u]--;
				if(deg[u] == 0)
					queue.Enqueue(u);
			}
		}

		Console.WriteLine((deleted.Count(x => x) < N) ? "Yes" : "No");
	}
}


