class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }

    Scanner cin;

    int N, M;
    string s;
    List<int>[] es;

    Queue<long> q;
    long[] hash;
    XRand rnd;

    Dictionary<long, bool[]> dic;
    bool ok;

    void calc()
    {
        cin = new Scanner();
        N = cin.nextInt();
        M = cin.nextInt();
        s = cin.next();
        es = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            es[i] = new List<int>();
        }

        for (int i = 0; i < M; i++)
        {
            int a = cin.nextInt() - 1;
            int b = cin.nextInt() - 1;
            es[a].Add(b);
            es[b].Add(a);
        }

        ok = true;
        rnd = new XRand();
        bool[] first = new bool[N];
        hash = new long[N];
        for (int i = 0; i < N; i++)
        {
            first[i] = true;
            hash[i] = ((long)rnd.nextInt(1 << 30) << 30) + rnd.nextInt(1 << 30);
        }
        q = new Queue<long>();
        dic = new Dictionary<long, bool[]>();
        addQueue(first);

        while(q.Count != 0)
        {
            bool[] br = dic[q.Dequeue()];
            bool[] next = new bool[N];
            for (int i = 0; i < N; i++)
            {
                if (!br[i]) continue;
                foreach (var j in es[i])
                {
                    next[j] = true;
                }
            }
            addQueue(next);
        }

        if (ok) Console.WriteLine("Yes");
        else Console.WriteLine("No");
    }

    void addQueue(bool[] ar)
    {
        bool[] a = new bool[N];
        bool[] b = new bool[N];
        for (int i = 0; i < N; i++)
        {
            if (!ar[i]) continue;
            if (s[i] == 'A') a[i] = true;
            else b[i] = true;
        }
        long ah = getHash(a);
        long bh = getHash(b);

        if (!dic.ContainsKey(ah))
        {
            dic[ah] = a;
            q.Enqueue(ah);
        }

        if (!dic.ContainsKey(bh))
        {
            dic[bh] = b;
            q.Enqueue(bh);
        }

    }

    long getHash(bool[] ar)
    {
        long ans = 0;
        for (int i = 0; i < N; i++)
        {
            if (!ar[i]) continue;
            ans ^= hash[i];
        }
        if (ans == 0) ok = false;
        return ans;
    }
}






