	public class Program
	{
		static void Main()
		{
			var cin = new Scanner();
			int n = cin.Int();
			int m = cin.Int();
			var s = cin.Next();
			var edge = new HashSet<(int a, int b)>();
			var to = Helper.Array(n, x => new HashSet<int>());
			for (int i = 0; i < m; i++) {
				int a = cin.Int() - 1;
				int b = cin.Int() - 1;
				if (a > b) {
					int temp = a;
					a = b;
					b = temp;
				}

				edge.Add((a, b));
				if (a != b) {
					to[a].Add(b);
					to[b].Add(a);
				}
			}

			var countA = new int[n];
			var countB = new int[n];
			foreach (var x in edge) {
				if (s[x.a] == 'A') {
					countA[x.b]++;
				} else {
					countB[x.b]++;
				}

				if (s[x.b] == 'A') {
					countA[x.a]++;
				} else {
					countB[x.a]++;
				}
			}

			var movable = Helper.Array(n, x => true);
			var q = new Queue<int>();
			for (int i = 0; i < n; i++) {
				if (countA[i] <= 0 || countB[i] <= 0) {
					q.Enqueue(i);
				}
			}

			while (q.Count > 0) {
				int cur = q.Dequeue();
				if (movable[cur] == false) {
					continue;
				}

				movable[cur] = false;
				foreach (var next in to[cur]) {
					if (s[cur] == 'A') {
						countA[next]--;
					} else {
						countB[next]--;
					}

					if (movable[next]) {
						if (countA[next] <= 0 || countB[next] <= 0) {
							q.Enqueue(next);
						}
					}
				}
			}

			var uf = new UnionFindTree(n);
			foreach (var x in edge) {
				if (movable[x.a] && movable[x.b]) {
					uf.Unite(x.a, x.b);
				}
			}

			bool ok = false;
			for (int i = 0; i < n; i++) {
				if (uf.GetSizeOf(i) > 1) {
					ok = true;
				}
			}

			Console.WriteLine(ok ? "Yes" : "No");
		}
	}

	public class UnionFindTree
	{
		private readonly int[] sizes_;
		private readonly int[] parents_;

		public int Count { get; private set; }
		public int GroupCount { get; private set; }

		public UnionFindTree(int count)
		{
			parents_ = new int[count];
			sizes_ = new int[count];

			Count = 0;
			GroupCount = count;
			while (Count < count) {
				parents_[Count] = Count;
				sizes_[Count] = 1;
				++Count;
			}
		}

		public int GetSizeOf(int x) => sizes_[Find(x)];

		public bool IsUnited(int x, int y) => Find(x) == Find(y);
		public bool Unite(int x, int y)
		{
			x = Find(x);
			y = Find(y);
			if (y == x) {
				return false;
			}

			int parent = sizes_[x] < sizes_[y] ? y : x;
			int child = sizes_[x] < sizes_[y] ? x : y;

			--GroupCount;
			parents_[child] = parent;
			sizes_[parent] += sizes_[child];

			return true;
		}

		public int Find(int x)
		{
			while (x != parents_[x]) {
				parents_[x] = parents_[parents_[x]];
				x = parents_[x];
			}

			return x;
		}

		public IEnumerable<int> GetAllRoots => parents_.Where(x => x == parents_[x]);
	}

	public struct ModInt
	{
		public const long P = 1000000007;
		//public const long P = 998244353;

		public static ModInt Inverse(ModInt value) => Pow(value, P - 2);
		public static ModInt Pow(ModInt value, long k) => Pow(value.value_, k);
		public static ModInt Pow(long value, long k)
		{
			long ret = 1;
			for (k %= P - 1; k > 0; k >>= 1, value = value * value % P) {
				if ((k & 1) == 1) {
					ret = ret * value % P;
				}
			}
			return new ModInt(ret);
		}

		private long value_;

		public ModInt(long value)
			=> value_ = value;
		public ModInt(long value, bool mods)
		{
			if (mods) {
				value %= P;
				if (value < 0) {
					value += P;
				}
			}

			value_ = value;
		}

		public static ModInt operator +(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (lhs.value_ + rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator +(long lhs, ModInt rhs)
		{
			rhs.value_ = (lhs + rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator +(ModInt lhs, long rhs)
		{
			lhs.value_ = (lhs.value_ + rhs) % P;
			return lhs;
		}

		public static ModInt operator -(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator -(long lhs, ModInt rhs)
		{
			rhs.value_ = (P + lhs - rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator -(ModInt lhs, long rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs) % P;
			return lhs;
		}

		public static ModInt operator *(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = lhs.value_ * rhs.value_ % P;
			return lhs;
		}
		public static ModInt operator *(long lhs, ModInt rhs)
		{
			rhs.value_ = lhs * rhs.value_ % P;
			return rhs;
		}
		public static ModInt operator *(ModInt lhs, long rhs)
		{
			lhs.value_ = lhs.value_ * rhs % P;
			return lhs;
		}

		public static ModInt operator /(ModInt lhs, ModInt rhs)
		{
			long exp = P - 2;
			while (exp > 0) {
				if (exp % 2 > 0) {
					lhs *= rhs;
				}

				rhs *= rhs;
				exp /= 2;
			}

			return lhs;
