    {
        int[] nm = Console.ReadLine().Split().Select(int.Parse).ToArray();
        int n = nm[0];
        int m = nm[1];
        string s = Console.ReadLine();
        //a-aを一つの頂点として扱う
        //すべてのinfに属している頂点は、その頂点がどのinfに属しているかのdictを持つ
        //a-bを繋ぐそれが出た場合は、infとinfを繋いでいるか
        //そのグループが奇数と偶数どちらも生成可能なことが条件として必要
        //グループidみたいなのを持ってあげて、id持ちとマージした時はそれぞれの頂点に対して[id,いちばんからのindex]をもたせてあげる
        //文字ジェネレータを隣り合ってるところ両方がジェネレータと接触しているものとする
        //a-a
        //| |
        //b-b
        //これをどうにか判定してあげたい
        //a-aのとこにジェネレータ候補indexを持たせてあげて、そのジェネレータ候補がジェネレータにることがジェネレータ昇格への制約となっているものに対してindexを伝搬
        //a-aを見つけたらまずdfsを決行 dfsによって通過した頂点はジェネレータでないならばそれが保証される状態にする
        //a-a この次はbを探す この次もbを探す そしてaを探す
        //通った逆要素に接触した場合、OK
        //通った同要素に接触した場合、逆要素と接触していたらOK していなかったらcontinue
        //DFSが終点してしまったら全ての頂点群を殺す(そこからDFSで辿ってももうのぞみはないことは確定しているので)
        //次の頂点からDFSスタート

        //DFSで来てるってことは

        //AABBAABB…
        //これでDFS回すのが明らかに正解なんですが、
        //Aから始めてAABBとなるように回し、自分と違う色が求めている色の時にループが閉じるのが嬉しい(問答無用でOK)
        //なんだけど、同じ色の時に閉じてもOKな場合があるんだよな
        //同じ色の時に閉じた場合、もし閉じたところに自己ループが隣り合ってたらOK
        //自己ループから評価を始めてあげる?嘘

        //自己ループはどちらでもOKなので、


        Vertex[] vert = Enumerable.Repeat(0, n).Select(_ => new Vertex()).ToArray();
        for (int i = 0; i < s.Length; i++)
        {
            vert[i].Letter = s[i] == 'A' ? 0 : 1;
        }
        for (int i = 0; i < m; i++)
        {
            int[] xy = Console.ReadLine().Split().Select(x => int.Parse(x) - 1).ToArray();
            if(xy[0] == xy[1])
            {
                vert[xy[0]].Connections.Add(xy[1]);
                vert[xy[0]].isSelfLoop = true;
            }
            else
            {
                vert[xy[0]].Connections.Add(xy[1]);
                vert[xy[1]].Connections.Add(xy[0]);
            }
        }
        long currentVersion = 1;
        for (int i = 0; i < n; i++)
        {
            if (vert[i].Version != 0) continue;
            vert[i].Version = currentVersion;
            //index,次に欲しい色
            Stack<Tuple<int, int>> stack = new Stack<Tuple<int, int>>();
            stack.Push(new Tuple<int, int>(i, vert[i].Letter));
            if (vert[i].isSelfLoop) stack.Push(new Tuple<int, int>(i, (vert[i].Letter + 1) % 2));
            while (stack.Count != 0)
            {
                //
                var currentPos = stack.Pop();
                Debug.WriteLine(currentPos.Item1);
                //繋がってるところ全てに対して回す
                foreach (var connection in vert[currentPos.Item1].Connections)
                {
                    if (currentPos.Item1 == connection) continue;
                    //一回通過したことがあったら
                    if (vert[connection].Version == currentVersion)
                    {
                        //求めているletterと一致していたら
                        if (vert[connection].Letter == currentPos.Item2)
                        {
                            //現在の場所の文字と求めている文字が違ったら(つまり問答無用でokな奴)
                            if (vert[currentPos.Item1].Letter != currentPos.Item2)
                            {
                                Console.WriteLine("Yes");
                                return;
                            }
                            else
                            {
                                //現在のとこと求めてる文字が同じだったら
                                //お前自信が自己ループで帰ってきてたりしたら最悪
                                foreach (var item in vert[connection].Connections)
                                {
                                    if (connection == item) continue;
                                    if (vert[item].isSelfLoop)
                                    {
                                        Console.WriteLine("Yes");
                                        return;
                                    }
                                }
                            }
                        }
                        continue;
                    }
                    if (vert[connection].Letter != currentPos.Item2) continue;
                    if (vert[connection].isSelfLoop && vert[currentPos.Item1].isSelfLoop)
                    {
                        Console.WriteLine("Yes");
                        return;
                    }
                    //別の時に通過したことがあったら(見込み0なので)
                    if (vert[connection].Version != 0) continue;
                    vert[connection].Version = currentVersion;
                    //次に欲しい色が今の色だったら、
                    int next = ((vert[currentPos.Item1].Letter == currentPos.Item2) ? (vert[currentPos.Item1].Letter + 1) % 2 : currentPos.Item2);
                    stack.Push(new Tuple<int, int>(connection, next));
                    if (vert[connection].isSelfLoop) stack.Push(new Tuple<int, int>(connection, (next + 1) % 2));
                }
            }
            currentVersion++;
        }
        Console.WriteLine("No");
    }
}
