class Solver
{
    Scanner sc = new Scanner();
    //
    public void Solve()
    {
        int N, M;
        sc.Make(out N, out M);
        var s = ReadLine();
        var edge = Create(N, () => new List<int>());
        for(var i = 0; i < M; i++)
        {
            int a, b;
            sc.Make(out a, out b);
            a--;b--;edge[a].Add(b);edge[b].Add(a);
        }
        var ct = new Pi[N];
        var del = new bool[N];
        var q = new Queue<int>();
        for (var i = 0; i < N; i++)
        {
            int a = 0, b = 0;
            foreach (var e in edge[i])
            {
                if (s[e] == 'A') a++;
                else b++;
            }
            if (a == 0 || b == 0) { del[i] = true; q.Enqueue(i); }
            ct[i] = new Pi(a, b);
        }
        while (q.Any())
        {
            var p = q.Dequeue();
            foreach (var e in edge[p])
                if (!del[e])
                {
                    if (s[p] == 'A') ct[e].v1--;
                    else ct[e].v2--;
                    if (ct[e].v1 == 0 || ct[e].v2 == 0)
                    { del[e] = true; q.Enqueue(e); }
                }
        }
      	WriteLine(del.Any(p=>p)?"Yes":"No");
    }
}

