                    {
                        //求めているletterと一致していたら
                        if (vert[connection].Letter == currentPos.Item2)
                        {
                            //現在の場所の文字と求めている文字が違ったら(つまり問答無用でokな奴)
                            if (vert[currentPos.Item1].Letter != currentPos.Item2)
                            {
                                Console.WriteLine("Yes");
                                return;
                            }
                            else
                            {
                                //現在のとこと求めてる文字が同じだったら
                                //お前自信が自己ループで帰ってきてたりしたら最悪
                                foreach (var item in vert[connection].Connections)
                                {
                                    if (connection == item) continue;
                                    if (vert[item].isSelfLoop)
                                    {
                                        Console.WriteLine("Yes");
                                        return;
                                    }
                                }
                            }
                        }
                        continue;
                    }
                    if (vert[connection].Letter != currentPos.Item2) continue;
                    if (vert[connection].isSelfLoop && vert[currentPos.Item1].isSelfLoop)
                    {
                        Console.WriteLine("Yes");
                        return;
                    }
                    //別の時に通過したことがあったら(見込み0なので)
                    if (vert[connection].Version != 0) continue;
                    vert[connection].Version = currentVersion;
                    //次に欲しい色が今の色だったら、
                    int next = ((vert[currentPos.Item1].Letter == currentPos.Item2) ? (vert[currentPos.Item1].Letter + 1) % 2 : currentPos.Item2);
                    stack.Push(new Tuple<int, int>(connection, next));
                    if (vert[connection].isSelfLoop) stack.Push(new Tuple<int, int>(connection, (next + 1) % 2));
                }
            }
            currentVersion++;
        }
        throw new Exception();
        Console.WriteLine("No");
    }
}
class Vertex
{
    public long Version = 0;
    public int Letter;
    public List<int> Connections = new List<int>();
    public bool isSelfLoop;
}

