            {
                if (removed[i]) continue;

                Queue<int> que = new Queue<int>();
                que.Enqueue(i);
                while (que.Count > 0)
                {
                    int now = que.Dequeue();
                    if (removed[now]) continue;
                    bool a = false;
                    bool b = false;
                    for(int j = 0; j < graph[now].Count; j++)
