			int m = cin.Int();
			var s = cin.Next();
			var edge = new HashSet<(int a, int b)>();
			var to = Helper.Array(n, x => new List<int>());
			for (int i = 0; i < m; i++) {
				int a = cin.Int() - 1;
				int b = cin.Int() - 1;
				if (a > b) {
					int temp = a;
					a = b;
					b = temp;
				}

				edge.Add((a, b));
				if (a != b) {
					to[a].Add(b);
					to[b].Add(a);
				}
			}

			var countA = new int[n];
			var countB = new int[n];
			foreach (var x in edge) {
				if (s[x.a] == 'A') {
					countA[x.b]++;
				} else {
					countB[x.b]++;
				}

				if (s[x.b] == 'A') {
					countA[x.a]++;
				} else {
					countB[x.a]++;
				}
			}

			var movable = Helper.Array(n, x => true);
			var q = new Queue<int>();
			for (int i = 0; i < n; i++) {
				if (countA[i] <= 0 || countB[i] <= 0) {
					q.Enqueue(i);
				}
			}

			while (q.Count > 0) {
				int cur = q.Dequeue();
				if (movable[cur] == false) {
					continue;
				}

				movable[cur] = false;
				foreach (var next in to[cur]) {
					if (s[cur] == 'A') {
						countA[next]--;
					} else {
						countB[next]--;
					}

					if (movable[next]) {
						if (countA[next] <= 0 || countB[next] <= 0) {
							q.Enqueue(next);
						}
					}
				}
			}

