                    next[j] = true;
                }
            }
            addQueue(next);
            if (cnt > 10) break;
        }

        if (ok) Console.WriteLine("Yes");
        else Console.WriteLine("No");
    }

    void addQueue(bool[] ar)
    {
        bool[] a = new bool[N];
        bool[] b = new bool[N];
        for (int i = 0; i < N; i++)
        {
            if (!ar[i]) continue;
            if (s[i] == 'A') a[i] = true;
            else b[i] = true;
        }
        long ah = getHash(a);
        long bh = getHash(b);

        if (!dic.ContainsKey(ah))
        {
            dic[ah] = a;
            q.Enqueue(ah);
        }

        if (!dic.ContainsKey(bh))
        {
            dic[bh] = b;
            q.Enqueue(bh);
        }

    }

    long getHash(bool[] ar)
    {
        long ans = 0;
        for (int i = 0; i < N; i++)
        {
            if (!ar[i]) continue;
            ans ^= hash[i];
        }
        if (ans == 0) ok = false;
        return ans;
    }
