func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

func Solve() {
  NM := NextIntVec()
  N, M := NM[0], NM[1]
  V := make([]int, N)
  G := make([][]int, N)
  for i := range G {
    G[i] = make([]int, 0)
  }
  S := NextLine()
  for i, s := range S {
    V[i] = int(s - rune('A'))
  }
  D := make([][]int, N)
  for i := range D {
    D[i] = make([]int, 2)
  }
  for i := 0; i < M; i++ {
    AB := NextIntVec()
    a, b := AB[0] - 1, AB[1] - 1
    G[a] = append(G[a], b)
    G[b] = append(G[b], a)
    D[a][V[b]]++
    D[b][V[a]]++
  }
  Q := make([]int, 0)
  for i, d := range D {
    if d[0] < 1 || d[1] < 1 {
      Q = append(Q, i)
    }
  }
  for 0 < len(Q) {
    q := Q[0]
    Q = Q[1:]
    for _, adj := range G[q] {
      if D[adj][0] < 1 || D[adj][1] < 1 { continue }
      D[adj][V[q]]--
      if D[adj][V[q]] < 1 { Q = append(Q, adj) }
    }
  }
  for _, d := range D {
    if 0 < d[0] && 0 < d[1] {
      Write("Yes")
      return
    }
  }
  Write("No")
  return
}

