import "fmt"

type Node struct {
    na, nb int
}

func addNeighbor(c byte, v *Node) {
    if c == 'A' {
        v.na++
    } else {
        v.nb++
    }
}

func removeNeighbor(c byte, v*Node) int {
    if c == 'A' {
        v.na--
        return v.na
    }
    v.nb--
    return v.nb
}

func main() {
    var n, m int
    var s string
    fmt.Scan(&n, &m, &s)
    vs := make([][]int, n)
    counts := make([]Node, n)
    for i := 0; i < m; i++ {
        var a, b int
        fmt.Scan(&a, &b)
        a--
        b--
        vs[a] = append(vs[a], b)
        vs[b] = append(vs[b], a)
        addNeighbor(s[a], &counts[b])
        addNeighbor(s[b], &counts[a])
    }

    var used []bool = make([]bool, n)

    var del []int
    var n_del int = 0
    for i, c := range counts {
        if c.na == 0 || c.nb == 0 {
            used[i] = true
            del = append(del, i)
            n_del++
        }
    }
    for i := 0; i < n_del; i++ {
        var del_i int = del[i]
        for _, x := range vs[del_i] {
            if used[x] == false && removeNeighbor(s[del_i], &counts[x]) == 0 {
                used[x] = true
                del = append(del, x)
                n_del++
            }
        }
    }
    if n_del == n {
        fmt.Println("No")
    } else {
        fmt.Println("Yes")
    }
}

