using namespace std;
using uint = unsigned int;
using ll = long long;
using ull = unsigned long long;
constexpr ll TEN(int n) { return (n==0) ? 1 : 10*TEN(n-1); }
template<class T> using V = vector<T>;
template<class T> using VV = V<V<T>>;

template<class T> ostream& operator<<(ostream& os, const V<T> &v) {
    cout << "[";
    for (auto p: v) cout << p << ", ";
    cout << "]";
    return os;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << setprecision(20) << fixed;
    int n, m;
    cin >> n >> m;
    string s;
    cin >> s;
    V<int> d(n);
    for (int i = 0; i < n; i++) d[i] = s[i] - 'A';

    VV<int> g(n);
    V<array<int, 2>> c(n);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v; u--; v--;
        g[u].push_back(v);
        g[v].push_back(u);
        c[u][d[v]]++;
        c[v][d[u]]++;
    }

    queue<int> q;
    for (int i = 0; i < n; i++) {
        if (c[i][0] == 0 || c[i][1] == 0) q.push(i);
    }

    V<bool> used(n);
    int uc = 0;
    while (q.size()) {
        int p = q.front(); q.pop();
        if (used[p]) continue;
        used[p] = true;
        uc++;
        int x = d[p];
        for (int v: g[p]) {
            c[v][x]--;
            if (c[v][x] == 0) q.push(v);
        }
    }
    cout << (uc == n ? "No" : "Yes") << endl;
    return 0;
}

import std.stdio;
import std.algorithm;
import std.conv;
import std.string;

void main()
{
	auto tokens = split(chomp(readln()));
	auto n   = to!int(tokens[0]);
	auto m   = to!int(tokens[1]);
	string s = chomp(readln());
	int[][] node;
	node.length = n;
	foreach (i; 0..m)
	{
		auto tokens2 = split(chomp(readln()));
		auto n1      = to!int(tokens2[0]) - 1;
		auto n2      = to!int(tokens2[1]) - 1;
		node[n1] ~= n2;
		node[n2] ~= n1;
	}

	bool[] nodeS;
	nodeS.length = n;
	fill(nodeS, true);

	int changed = int.max;
	while (changed != 0)
	{
		changed = 0;
		foreach (i, node2; node)
		{
			if (!nodeS[i]) continue;

			bool isDone1 = false, isDone2 = false;
			char c1 = s[i];
			foreach (j; node2)
			{
				if (!nodeS[j]) continue;

				char c2 = s[j];
				if (c1 == c2) isDone1 = true;
				else		  isDone2 = true;
			}
			if (!isDone1 || !isDone2)
			{
				nodeS[i] = false;
				++changed;
			}
		}
	}

	bool isComplete = false;
	foreach (e; nodeS) if (e) isComplete = true;

	writeln(isComplete ? "Yes" : "No");
	stdout.flush();
}

