def have_loop(G, V):
    #Gに閉路があるかを判定 Gは隣接グラフによる表現. 0-based Vは頂点数
    parent = [{v} for v in range(V)] #各頂点の親集合
    reached = [False] * V
    for v in range(V):
        stack = []
        if not reached[v]:
            stack.append(v)
            while stack:
                u = stack.pop()
                reached[u] = True
                for w in G[u]:
                    if w in parent[u]:
                        return True
                    elif not reached[w]:
                        parent[w] |= parent[u]
                        stack.append(w)
    return False

