#入力受け取り
def getlist():
	return list(map(int, input().split()))

#処理内容
def main():
	#入力
	N, M = getlist()
	s = list(input())
	outE = defaultdict(list)
	inEA = defaultdict(int)
	inEB = defaultdict(int)
	E = set()
	for i in range(M):
		a, b = sorted(getlist())
		a = a - 1
		b = b - 1
		E.add((a, b))
	E = list(E)
	#print(E)
	m = len(E)
	for i in range(m):
		a = E[i][0]
		b = E[i][1]
		outE[a].append(b)
		outE[b].append(a)
		if s[a] == "A":
			inEA[b] += 1
		else:
			inEB[b] += 1

		if s[b] == "A":
			inEA[a] += 1
		else:
			inEB[a] += 1

	Q = deque()
	for i in range(N):
		if inEA[i] == 0 or inEB[i] == 0:
			Q.append(i)

	visit = ["No"] * N
	check = ["Yes"] * N
	while Q:
		u = Q.popleft()
		visit[u] = "Yes"
		check[u] = "No"
		for v in outE[u]:
			if s[u] == "A":
				inEA[v] -= 1
				if inEA[v] == 0:
					check[v] = "No"
					Q.append(v)
			else:
				inEB[v] -= 1
				if inEB[v] == 0:
					check[v] = "No"
					Q.append(v)

	judge = "No"
	#print(check)
	for i in range(N):
		if check[i] == "Yes":
			judge = "Yes"
	print(judge)

