        graph[a].push(b);
        graph[b].push(a);
    }

    for i in 0..n {
        for &next in graph[i].iter() {
            if s[next] == 'A' {
                a[i] += 1;
            } else {
                b[i] += 1;
            }
        }
    }

    let mut visit = vec![false; n];
    let mut queue = VecDeque::new();
    for i in 0..n {
        if a[i] == 0 || b[i] == 0 {
            queue.push_back(i);
