use std::collections::{BTreeSet, VecDeque};

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();
    let s: Vec<_> = sc
        .read::<String>()
        .chars()
        .map(|c| c as usize - 'A' as usize)
        .collect();
    let mut graph = vec![BTreeSet::new(); n];
    let mut count = vec![[0; 2]; n];
    for _ in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        if !graph[a].contains(&b) {
            graph[a].insert(b);
            count[a][s[b]] += 1;
        }
        if !graph[b].contains(&a) {
            graph[b].insert(a);
            count[b][s[a]] += 1;
        }
    }

    let mut q = VecDeque::new();
    let mut removed = vec![false; n];
    for i in 0..n {
        if count[i][0] == 0 || count[i][1] == 0 {
            removed[i] = true;
            q.push_back(i);
        }
    }

    while let Some(v) = q.pop_front() {
        let next: Vec<_> = graph[v].iter().cloned().collect();
        for next in next.into_iter() {
            assert!(graph[next].remove(&v));
            assert!(count[next][s[v]] > 0);
            count[next][s[v]] -= 1;
            if count[next][s[v]] == 0 && !removed[next] {
                removed[next] = true;
                q.push_back(next);
            }

            if next != v {
                assert!(graph[v].remove(&next));
                assert!(count[v][s[next]] > 0);
                count[v][s[next]] -= 1;
            }
        }

        graph[v].clear();
        assert_eq!(count[v][0], 0);
        assert_eq!(count[v][1], 0);
    }

    if removed.into_iter().all(|r| r) {
        println!("No");
    } else {
        println!("Yes");
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

