fn has_cycle(graph: Vec<Vec<usize>>) -> bool {
    let n = graph.len();
    let mut indeg = vec![0; n];
    for i in 0..n {
        for &j in graph[i].iter() {
            indeg[j] += 1;
        }
    }

    let mut deq = VecDeque::new();
    let mut cnt = 0;
    for i in 0..n {
        if indeg[i] == 0 {
            deq.push_back(i);
            cnt += 1;
        }
    }

    while deq.len() >= 1 {
        let u = deq.pop_front().unwrap();
        for &j in graph[u].iter() {
            indeg[j] -= 1;
            if indeg[j] == 0 {
                deq.push_back(j);
                cnt += 1;
            }
        }
    }
    return cnt != n;
}

