        }
    }

    let mut graph = vec![vec![]; n];
    for &(u, v) in edges.iter() {
        if u == v {
            graph[u].push(v);
        } else {
            graph[u].push(v);
            graph[v].push(u);
        }
    }

    let mut dgraph = vec![vec![]; 2*n];
    for i in 0..n {
        for &t in graph[i].iter() {
            // i*2(R,R) -> t*2(R,B)
