            let tt = t*2 + (snum[i] ^ snum[t] ^ 1);
            if snum[t] == snum[i] {
                dgraph[i*2].push(tt);
            }
            if snum[t] != snum[i] {
                dgraph[i*2+1].push(tt);
            }
        }
    }

    if has_cycle(dgraph) {
        println!("Yes");
    } else {
        println!("No");
    }
