const MOD: i64 = 1000000007;
const NOTHING: usize = std::usize::MAX;
const DX: [usize; 4] = [1, 0, std::usize::MAX, 0];
const DY: [usize; 4] = [0, 1, 0, std::usize::MAX];

fn solve<R: std::io::BufRead, W: std::io::Write>(io: &mut IO<R, W>) {
    let (n, m): (usize, usize) = io.readln();
    let cs: Vec<char> = io.readln();
    let mut gr: Vec<HashSet<usize>> = vec![HashSet::new();n];
    for _ in 0..m {
        let (u, v): (usize, usize) = io.readln();
        let u = u - 1;
        let v = v - 1;
        gr[u].insert(v);
        gr[v].insert(u);
    }

    for s in 0..n {
        let mut sa: Vec<usize> = Vec::new();
        let mut sb: Vec<usize> = Vec::new();
        for &u in &gr[s] {
            if cs[u] == 'A' {
                sa.push(u);
            } else {
                sb.push(u);
            }
        }
        let mut a = NOTHING;
        let mut a_max = 0;
        for &v in &sa {
            if a_max < gr[v].len() {
                a = v;
                a_max = gr[v].len();
            }
        }
        for &v in &sa {
            if v != a {
                let mut set: HashSet<usize> = HashSet::new();
                for &t in &gr[v] {
                    set.insert(t);
                }
                for &e in &set {
                    gr[a].insert(e);
                }
                gr[v].clear();
            }
        }

        let mut b = NOTHING;
        let mut b_max = 0;
        for &v in &sb {
            if b_max < gr[v].len() {
                b = v;
                b_max = gr[v].len();
            }
        }
        for &v in &sb {
            if v != b {
                let mut set: HashSet<usize> = HashSet::new();
                for &t in &gr[v] {
                    set.insert(t);
                }
                for &e in &set {
                    gr[b].insert(e);
                }
                gr[v].clear();
            }
        }
    }

    for s in 0..n {
        if cs[s] == 'B' {
            continue;
        }
        let mut sa: HashSet<usize> = HashSet::new();
        let mut sb: HashSet<usize> = HashSet::new();
        for &u in &gr[s] {
            if cs[u] == 'A' {
                for &v in &gr[u] {
                    if cs[v] == 'B' {
                        sa.insert(v);
                    }
                }
            } else {
                for &v in &gr[u] {
                    if cs[v] == 'B' {
                        sb.insert(v);
                    }
                }
            }
            for _ in sa.intersection(&sb) {
                io.writeln("Yes");
                return;
            }
        }
    }

    io.writeln("No")
}



