                a_count[to] += 1;
            } else {
                b_count[to] += 1;
            }
        }
    }

    let mut new_unuse = HashSet::new();
    let mut usable = vec![true; n];
    for from in 0..n {
        if a_count[from] == 0 || b_count[from] == 0 {
            usable[from] = false;
            new_unuse.insert(from);
        }
    }

    while !new_unuse.is_empty() {
        let mut unuse = HashSet::new();
        std::mem::swap(&mut unuse, &mut new_unuse);
        for &i in unuse.iter() {
            for &to in g[i].iter() {
                if s[i] == 'A' {
                    a_count[to] -= 1;
                } else {
                    b_count[to] -= 1;
                }
                if (a_count[to] == 0 || b_count[to] == 0) && usable[to] {
                    new_unuse.insert(to);
                    usable[to] = false;
                }
            }
        }
    }
    if usable.iter().any(|&x| x) {
        println!("Yes");
    } else {
        println!("No");
    }
}

