use std::io::*;
use std::str::FromStr;
use utils::*;

pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (n, m) = i.read2::<usize, usize>();
    let s: Vec<_> = i
        .read_line()
        .as_bytes()
        .iter()
        .map(|&x| if x == b'A' { 0 } else { 1 })
        .collect();

    let mut abs = Vec::new();
    for _ in 0..m {
        let (a, b) = i.read2::<usize, usize>();
        abs.push((a - 1, b - 1));
    }
    let r = if solve(n, &s, &abs) { "Yes" } else { "No" };
    writeln!(o, "{}", r).unwrap();
}
fn solve(n: usize, s: &[usize], abs: &[(usize, usize)]) -> bool {
    let mut c = vec![[0; 2]; n];
    let mut edges = vec![Vec::new(); n];
    for &(a, b) in abs {
        c[a][s[b]] += 1;
        c[b][s[a]] += 1;
        edges[a].push(b);
        edges[b].push(a);
    }
    let mut is_enabled = vec![true; n];
    let mut count_enabled = n;
    let mut q: Vec<usize> = (0..n).collect();

    while let Some(i) = q.pop() {
        if is_enabled[i] && (c[i][0] == 0 || c[i][1] == 0) {
            is_enabled[i] = false;
            count_enabled -= 1;
            let si = s[i];
            for &j in &edges[i] {
                if is_enabled[j] {
                    c[j][si] -= 1;
                    if c[j][si] == 0 {
                        q.push(j);
                    }
                }
            }
        }
    }
    count_enabled != 0
}

