enum Visit {
    Unvisited,
    Visiting,
    Visited
}
use Visit::*;

fn dfs(v: usize, adj: &[Vec<usize>], visits: &mut [Visit]) -> bool {
    let result = match visits[v] {
        Visited => false,
        Visiting => true,
        Unvisited => {
            visits[v] = Visiting;
            adj[v].iter().any(|&next| dfs(next, adj, visits))
        }
    };
    visits[v] = Visited;
    result
}

