fn solve<R: std::io::BufRead, W: std::io::Write>(io: &mut IO<R, W>) {
    let (n, m): (usize, usize) = io.readln();
    let cs: Vec<char> = io.readln();
    //    let mut gr: Vec<Vec<usize>> = vec![Vec::new();n];
    let mut gr: Vec<HashSet<usize>> = vec![HashSet::new();n];
    for _ in 0..m {
        let (u, v): (usize, usize) = io.readln();
        let u = u - 1;
        let v = v - 1;
        gr[u].insert(v);
        gr[v].insert(u);
    }

    for s in 0..n {
        let mut sa: HashSet<usize> = HashSet::new();
        let mut sb: HashSet<usize> = HashSet::new();
        for &u in &gr[s] {
            if cs[u] == 'A' {
                sa.insert(u);
            } else {
                sb.insert(u);
            }
        }
        let mut set = HashSet::new();
        for &ua in &sa {
            for &va in gr[ua].intersection(&sa) {
                if ua != va {
                    set.insert((ua, va));
                }
            }
        }
        for &ub in &sb {
            for &vb in gr[ub].intersection(&sb) {
                if ub != vb {
                    set.insert((ub, vb));
                }
            }
        }
        for &(x, y) in &set {
            if gr[x].len() < gr[y].len() {
                let mut tmp = Vec::new();
                for &z in &gr[x] {
                    tmp.push(z);
                }
                for &t in &tmp {
                    gr[y].insert(t);
                }
            } else {
                let mut tmp = Vec::new();
                for &z in &gr[y] {
                    tmp.push(z);
                }
                for &t in &tmp {
                    gr[x].insert(t);
                }
            }
        }

    }

    for s in 0..n {
        if cs[s] == 'B' {
            continue;
        }
        let mut sa: HashSet<usize> = HashSet::new();
        let mut sb: HashSet<usize> = HashSet::new();
        for &u in &gr[s] {
            if cs[u] == 'A' {
                for &v in &gr[u] {
                    if cs[v] == 'B' {
                        sa.insert(v);
                    }
                }
            } else {
                for &v in &gr[u] {
                    if cs[v] == 'B' {
                        sb.insert(v);
                    }
                }
            }
            for _ in sa.intersection(&sb) {
                io.writeln("Yes");
                return;
            }
        }
    }

    io.writeln("No")
}



