macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
    ($($r:tt)*) => {
        let mut s = {
            use std::io::Read;
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).unwrap();
            s
        };
        let mut iter = s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};

    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };

    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };

    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };

    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };

    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input!(n: usize, m: usize, s: chars, edges: [(usize1, usize1); m]);

    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let (from, to) = edges[i];
        graph[from].push(to);
        graph[to].push(from);
    }

    let mut result = 0;
    for _ in 0..35 {
        let mut ok = vec![false; n];
        for i in 0..n {
            let mut ok_a = false;
            let mut ok_b = false;
            for &next in graph[i].iter() {
                if s[next] == 'A' {
                    ok_a = true;
                }
                if s[next] == 'B' {
                    ok_b = true;
                }
            }
            ok[i] = ok_a && ok_b;
        }

        let mut added = 0;
        graph = vec![vec![]; n];
        for &(u, v) in edges.iter() {
            if ok[u] && ok[v] {
                graph[u].push(v);
                graph[v].push(u);
                added += 1;
            }
        }
        result = added;
    }

    if result == 0 {
        println!("No");
    } else {
        println!("Yes");
    }
}

fn check(
    v: usize,
    graph: &Vec<Vec<usize>>,
    visit: &mut Vec<bool>,
    same: bool,
    s: &Vec<char>,
) -> bool {
    if visit[v] {
        return true;
    }

    visit[v] = true;
    for &next in graph[v].iter() {
        if same == (s[v] == s[next]) && check(next, graph, visit, same, s) {
            return true;
        }
    }
    return false;
}

