fn to_num(n: char) -> usize {
    n as usize - 'A' as usize
}

fn solve() {
    let (n,m) = get!(usize,usize);
    let s = get!(String).chars().collect::<Vec<_>>();
    let ab = get!(usize,usize;m);

    let mut nodes = vec![BTreeMap::new(); n];
    let mut abvec = vec![vec![0usize;2];n];
    for (a,b) in ab {
        let a = a-1;
        let b = b-1;
        *nodes[a].entry(b).or_insert(0) += 1;
        abvec[a][to_num(s[b])] += 1;
        if a != b {
            *nodes[b].entry(a).or_insert(0) += 1;
            abvec[b][to_num(s[a])] += 1;
        }
    }
    let mut list = VecDeque::new();
    let mut removed = vec![false; n];
    for i in 0..n {
        if abvec[i][0] == 0 || abvec[i][1] == 0 {
            list.push_back(i);
            removed[i] = true;
        }
    }

    let mut count = 0usize;
    while let Some(node) = list.pop_front() {
        count += 1;
        let c = to_num(s[node]);
        for (&next,&num) in &nodes[node] {
            if removed[next] {
                continue;
            }
            abvec[next][c] -= num; 
            if abvec[next][c] == 0 {
                list.push_back(next);
                removed[next] = true;
            }
        }
    }
    if count < n {
        println!("Yes");
    } else {
        println!("No");
    }
}

use self::mod_int::ModInt;
