const MOD: usize = 1e9 as usize + 7;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();
    let s = sc
        .read::<String>()
        .chars()
        .map(|c| c as usize - 'A' as usize)
        .collect::<Vec<_>>();
    let mut graph = vec![BTreeSet::new(); n];
    let mut count = vec![[0, 0]; n];
    for _ in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].insert(b);
        graph[b].insert(a);
    }

    for i in 0..n {
        for &next in graph[i].iter() {
            count[i][s[next]] += 1;
        }
    }

    let mut queued = vec![false; n];
    let mut q = VecDeque::new();
    for i in 0..n {
        if count[i][0] == 0 || count[i][1] == 0 {
            q.push_back(i);
            queued[i] = true;
        }
    }

    while let Some(v) = q.pop_front() {
        let next = graph[v].iter().cloned().collect::<Vec<_>>();
        for next in next.into_iter() {
            graph[next].remove(&v);
            count[next][s[v]] -= 1;
            if !queued[next] && count[next][s[v]] == 0 {
                queued[next] = true;
                q.push_back(next);
            }
        }
    }

    if queued.into_iter().any(|q| !q) {
        println!("Yes");
    } else {
        println!("No");
    }
}

pub mod mod_int {
