fn main() {
    input!(n: usize, m: usize, s: chars, edges: [(usize1, usize1); m]);

    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let (from, to) = edges[i];
        graph[from].push(to);
        graph[to].push(from);
    }

    let mut result = 0;
    for _ in 0..100 {
        let mut ok = vec![false; n];
        for i in 0..n {
            let mut ok_a = false;
            let mut ok_b = false;
            for &next in graph[i].iter() {
                if s[next] == 'A' {
                    ok_a = true;
                }
                if s[next] == 'B' {
                    ok_b = true;
                }
            }
            ok[i] = ok_a && ok_b;
        }

        let mut added = 0;
        graph = vec![vec![]; n];
        for &(u, v) in edges.iter() {
            if ok[u] && ok[v] {
                graph[u].push(v);
                graph[v].push(u);
                added += 1;
            }
        }
        result = added;
    }

    if result == 0 {
        println!("No");
    } else {
        println!("Yes");
    }
}

fn check(
    v: usize,
    graph: &Vec<Vec<usize>>,
    visit: &mut Vec<bool>,
    same: bool,
    s: &Vec<char>,
) -> bool {
    if visit[v] {
        return true;
    }

    visit[v] = true;
    for &next in graph[v].iter() {
        if same == (s[v] == s[next]) && check(next, graph, visit, same, s) {
            return true;
        }
    }
    return false;
}

