fn main() {
    let (n, m): (usize, usize) = (read(), read());
    let s: Vec<char> = read::<String>().chars().collect();
    let mut graph: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut count: Vec<(i32, i32)> = vec![(0, 0); n];
    for _ in 0..m {
        let (a, b) = (read::<usize>() - 1, read::<usize>() - 1);
        graph[b].push(a);
        if s[a] == 'A' {
            count[b].0 += 1;
        } else {
            count[b].1 += 1;
        }
        if a == b {
            continue;
        }
        graph[a].push(b);
        if s[b] == 'A' {
            count[a].0 += 1;
        } else {
            count[a].1 += 1;
        }
    }
    let mut changed = true;
    let mut po: Vec<bool> = vec![true; n];
    while changed {
        changed = false;
        for i in 0..n {
            if !po[i] {
                continue;
            }
            if count[i].0 <= 0 || count[i].1 <= 0 {
                po[i] = false;
                changed = true;
                for j in &graph[i] {
                    if s[i] == 'A' {
                        count[*j].0 -= 1;
                    } else {
                        count[*j].1 -= 1;
                    }
                }
            }
        }
    }
    let mut ok = false;
    for i in 0..n {
        if count[i].0 > 0 && count[i].1 > 0 {
            ok = true;
        }
    }
    println!("{}", if ok { "Yes" } else { "No" });
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

