#[derive(Clone, Copy, Debug, Default)]
pub struct Adjacent {
    to: usize,
    id: usize,
}
impl Adjacent {
    pub fn new(to: usize, id: usize) -> Adjacent {
        Adjacent { to: to, id: id }
    }
}
#[derive(Clone, Debug, Default)]
pub struct Graph {
    vsize: usize,
    esize: usize,
    graph: Vec<Vec<Adjacent>>,
}
impl Graph {
    pub fn new(vsize: usize) -> Graph {
        Graph {
            vsize: vsize,
            esize: 0,
            graph: vec![vec![]; vsize],
        }
    }
    pub fn add_edge(&mut self, from: usize, to: usize) {
        self.graph[from].push(Adjacent::new(to, self.esize));
        self.esize += 1;
    }
    pub fn add_undirected_edge(&mut self, u: usize, v: usize) {
        self.graph[u].push(Adjacent::new(v, self.esize));
        self.graph[v].push(Adjacent::new(u, self.esize));
        self.esize += 1;
    }
    pub fn vertexes(&self) -> std::ops::Range<usize> {
        0..self.vsize
    }
    pub fn adjacency(&self, from: usize) -> &Vec<Adjacent> {
        &self.graph[from]
    }
}
impl Graph {
    pub fn topological_sort(&self) -> Vec<usize> {
        let mut indeg = vec![0; self.vsize];
        let mut res = vec![];
        for v in self.vertexes().flat_map(|u| self.adjacency(u)) {
            indeg[v.to] += 1;
        }
        let mut stack = self
            .vertexes()
            .filter(|&u| indeg[u] == 0)
            .collect::<Vec<_>>();
        while let Some(u) = stack.pop() {
            res.push(u);
            for v in self.adjacency(u) {
                indeg[v.to] -= 1;
                if indeg[v.to] == 0 {
                    stack.push(v.to);
                }
            }
        }
        res
    }
}
fn main() {
    input! { n, m, s: { chars: 'A' }, ab: [(usize1, usize1); m] };
    let mut graph = Graph::new(n * 2);
    for &(a, b) in ab.iter() {
        if s[a] == s[b] {
            graph.add_edge(a, b + n);
            graph.add_edge(b, a + n);
        } else {
            graph.add_edge(a + n, b);
            graph.add_edge(b + n, a);
        }
    }
    let ans = graph.topological_sort().len() != 2 * n;
    println!("{}", if ans { "Yes" } else { "No" });
}

