fn to_num(n: char) -> usize {
    n as usize - 'A' as usize
}

fn solve() {
    let (n,m) = get!(usize,usize);
    let s = get!(String).chars().collect::<Vec<_>>();
    let ab = get!(usize,usize;m);

    let mut nodes = vec![BTreeSet::new(); n];
    let mut abvec = vec![vec![0;2];n];
    for (a,b) in ab {
        let a = a-1;
        let b = b-1;
        nodes[a].insert(b);
        nodes[b].insert(a);
        abvec[a][to_num(s[b])] += 1;
        abvec[b][to_num(s[a])] += 1;
    }
    let mut list = VecDeque::new();
    for i in 0..n {
        if abvec[i][0] == 0 || abvec[i][1] == 0 {
            list.push_back(i);
        }
    }

    let mut count = 0usize;
    while let Some(node) = list.pop_front() {
        count += 1;
        let c = to_num(s[node]);
        for &next in &nodes[node].clone() {
            abvec[next][c] -= 1; 
            nodes[next].remove(&node);
            if abvec[next][0] == 0 || abvec[next][1] == 0 {
                list.push_back(next);
            }
        }
    }
    if count < n {
        println!("Yes");
    } else {
        println!("No");
    }
}

use std::collections::VecDeque;
use std::io::*;
use std::str::FromStr;

fn main() {
    let (n, m): (usize, usize) = (read(), read());
    let s: Vec<char> = read::<String>().chars().collect();
    let mut graph: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut count: Vec<(i32, i32)> = vec![(0, 0); n];
    for _ in 0..m {
        let (a, b) = (read::<usize>() - 1, read::<usize>() - 1);
        graph[b].push(a);
        if s[a] == 'A' {
            count[b].0 += 1;
        } else {
            count[b].1 += 1;
        }
        if a == b {
            continue;
        }
        graph[a].push(b);
        if s[b] == 'A' {
            count[a].0 += 1;
        } else {
            count[a].1 += 1;
        }
    }
    let mut que: VecDeque<usize> = VecDeque::new();
    for i in 0..n {
        if count[i].0 <= 0 || count[i].1 <= 0 {
            que.push_back(i);
        }
    }
    let mut deleted = vec![false; n];
    while !que.is_empty() {
        let p = que.pop_front().unwrap();
        deleted[p] = true;
        for i in &graph[p] {
            if deleted[*i] {
                continue;
            }
            if s[p] == 'A' {
                count[*i].0 -= 1;
            } else {
                count[*i].1 -= 1;
            }
            if count[*i].0 <= 0 || count[*i].1 <= 0 {
                que.push_back(*i);
            }
        }
    }
    let mut ok = false;
    for i in 0..n {
        if count[i].0 > 0 && count[i].1 > 0 {
            ok = true;
        }
    }
    println!("{}", if ok { "Yes" } else { "No" });
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

