fn solve<R: std::io::BufRead, W: std::io::Write>(io: &mut IO<R, W>) {
    let (n, m): (usize, usize) = io.readln();
    let cs: Vec<char> = io.readln();
    let mut gr: Vec<Vec<usize>> = vec![vec![];n];
    for _ in 0..m {
        let (u, v): (usize, usize) = io.readln();
        let u = u - 1;
        let v = v - 1;
        gr[u].push(v);
        gr[v].push(u);
    }

    for s in 0..n {
        if cs[s] == 'B' {
            continue;
        }
        let mut sa: HashSet<usize> = HashSet::new();
        let mut sb: HashSet<usize> = HashSet::new();
        for &u in &gr[s] {
            if cs[u] == 'A' {
                for &v in &gr[u] {
                    if cs[v] == 'B' {
                        sa.insert(v);
                    }
                }
            } else {
                for &v in &gr[u] {
                    if cs[v] == 'B' {
                        sb.insert(v);
                    }
                }
            }
            for _ in sa.intersection(&sb) {
                io.writeln("Yes");
                return;
            }
        }
    }

    io.writeln("No")
}



